import React from 'react';
import { View, Text, StyleSheet, ScrollView } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS, SPACING, RADIUS, TYPOGRAPHY } from '../constantes/theme';

export type SyncEvent = {
  type: 'local_operation' | 'remote_snapshot' | 'eco_local_aplicado';
  timestamp: number;
  mesaId: string;
  itemsCount: number;
  operation?: string;
};

type SyncStatusPanelProps = {
  isOnline: boolean;
  lastSync: number;
  events: SyncEvent[];
  mesaId: string | null;
};

export function SyncStatusPanel({ isOnline, lastSync, events, mesaId }: SyncStatusPanelProps) {
  const formatTime = (timestamp: number) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString('es-MX', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  };

  const getEventIcon = (type: SyncEvent['type']) => {
    switch (type) {
      case 'local_operation':
        return { name: 'arrow-up-circle' as const, color: COLORS.primary };
      case 'remote_snapshot':
        return { name: 'arrow-down-circle' as const, color: COLORS.success };
      case 'eco_local_aplicado':
        return { name: 'checkmark-circle' as const, color: COLORS.warning };
    }
  };

  const getEventLabel = (type: SyncEvent['type']) => {
    switch (type) {
      case 'local_operation':
        return 'LOCAL';
      case 'remote_snapshot':
        return 'REMOTO';
      case 'eco_local_aplicado':
        return 'ECO';
    }
  };

  const timeSinceLastSync = lastSync > 0 ? Date.now() - lastSync : null;
  const syncStatus = timeSinceLastSync !== null && timeSinceLastSync < 5000 ? 'ACTIVO' : 'IDLE';

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <View style={styles.statusRow}>
          <Ionicons
            name={isOnline ? 'wifi' : 'wifi-outline'}
            size={16}
            color={isOnline ? COLORS.success : COLORS.error}
          />
          <Text style={[styles.statusText, { color: isOnline ? COLORS.success : COLORS.error }]}>
            {isOnline ? 'ONLINE' : 'OFFLINE'}
          </Text>
        </View>

        <View style={styles.statusRow}>
          <Ionicons
            name="sync"
            size={16}
            color={syncStatus === 'ACTIVO' ? COLORS.primary : COLORS.text.muted}
          />
          <Text
            style={[
              styles.statusText,
              { color: syncStatus === 'ACTIVO' ? COLORS.primary : COLORS.text.muted },
            ]}
          >
            {syncStatus}
          </Text>
        </View>

        {mesaId && (
          <View style={styles.mesaBadge}>
            <Text style={styles.mesaText}>Mesa {mesaId}</Text>
          </View>
        )}
      </View>

      {lastSync > 0 && <Text style={styles.lastSyncText}>Última sync: {formatTime(lastSync)}</Text>}

      <ScrollView style={styles.eventsContainer} showsVerticalScrollIndicator={false}>
        {events.length === 0 ? (
          <Text style={styles.emptyText}>Sin eventos recientes</Text>
        ) : (
          events.map((event, index) => {
            const icon = getEventIcon(event.type);
            const label = getEventLabel(event.type);

            return (
              <View key={`${event.timestamp}-${index}`} style={styles.eventRow}>
                <Ionicons name={icon.name} size={14} color={icon.color} />
                <Text style={[styles.eventLabel, { color: icon.color }]}>{label}</Text>
                <Text style={styles.eventTime}>{formatTime(event.timestamp)}</Text>
                <Text style={styles.eventCount}>{event.itemsCount} items</Text>
              </View>
            );
          })
        )}
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    backgroundColor: COLORS.bg.elevated,
    borderRadius: RADIUS.md,
    padding: SPACING.sm,
    borderWidth: 1,
    borderColor: COLORS.bg.elevated,
    maxHeight: 180,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: SPACING.sm,
    marginBottom: SPACING.xs,
  },
  statusRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
    paddingHorizontal: SPACING.xs,
    paddingVertical: 2,
    borderRadius: RADIUS.sm,
    backgroundColor: COLORS.bg.secondary,
  },
  statusText: {
    fontSize: 10,
    fontWeight: TYPOGRAPHY.weights.bold,
  },
  mesaBadge: {
    marginLeft: 'auto',
    paddingHorizontal: SPACING.xs,
    paddingVertical: 2,
    borderRadius: RADIUS.sm,
    backgroundColor: COLORS.alpha.primary20,
  },
  mesaText: {
    fontSize: 10,
    fontWeight: TYPOGRAPHY.weights.bold,
    color: COLORS.primary,
  },
  lastSyncText: {
    fontSize: 9,
    color: COLORS.text.muted,
    marginBottom: SPACING.xs,
  },
  eventsContainer: {
    flex: 1,
  },
  emptyText: {
    fontSize: 10,
    color: COLORS.text.muted,
    textAlign: 'center',
    paddingVertical: SPACING.sm,
  },
  eventRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
    paddingVertical: 4,
    borderBottomWidth: 1,
    borderBottomColor: COLORS.bg.secondary,
  },
  eventLabel: {
    fontSize: 10,
    fontWeight: TYPOGRAPHY.weights.bold,
    minWidth: 50,
  },
  eventTime: {
    fontSize: 9,
    color: COLORS.text.secondary,
    flex: 1,
  },
  eventCount: {
    fontSize: 9,
    color: COLORS.text.muted,
  },
});

import { useMemo } from 'react';
import { Dimensions, Platform, StyleSheet, Text, View } from 'react-native';
import { LineChart } from 'react-native-chart-kit';
import { useAppTheme } from '../../temas/ThemeContext';
import { Card } from '../ui/Card';

const SCREEN_WIDTH = Dimensions.get('window').width;

interface SalesLineChartProps {
  data: { label: string; total: number }[];
  title?: string;
  height?: number;
}

export const SalesLineChart = ({
  data,
  title = 'Tendencia de Ventas',
  height = 220,
}: SalesLineChartProps) => {
  const { theme, isElite } = useAppTheme();

  // 🎨 Configuración de Colores Dinámica
  const chartConfig = useMemo(() => {
    return {
      backgroundGradientFrom: isElite ? '#111115' : '#ffffff',
      backgroundGradientTo: isElite ? '#0a0a0c' : '#ffffff',
      decimalPlaces: 0,
      color: (opacity = 1) =>
        isElite
          ? `rgba(197, 160, 89, ${opacity})` // Elite Gold
          : `rgba(37, 99, 235, ${opacity})`, // Classic Blue
      labelColor: (opacity = 1) =>
        isElite ? `rgba(255, 255, 255, ${opacity})` : `rgba(107, 114, 128, ${opacity})`,
      style: {
        borderRadius: 16,
      },
      propsForDots: {
        r: '4',
        strokeWidth: '2',
        stroke: isElite ? '#fbbf24' : '#2563EB',
        fill: isElite ? '#000' : '#fff',
      },
      propsForBackgroundLines: {
        strokeDasharray: '5', // Dotted lines
        stroke: isElite ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.05)',
      },
    };
  }, [isElite, theme]);

  // Transformar datos para el chart
  const chartData = useMemo(() => {
    // Si no hay datos, mostramos una línea plana
    if (!data || data.length === 0) {
      return {
        labels: ['0h', '4h', '8h', '12h', '16h', '20h'],
        datasets: [{ data: [0, 0, 0, 0, 0, 0] }],
      };
    }

    // Tomar solo algunos labels para no saturar el eje X
    const step = Math.ceil(data.length / 6);
    const labels = data.map((d, i) => (i % step === 0 ? d.label : ''));
    const values = data.map((d) => d.total);

    return {
      labels,
      datasets: [
        {
          data: values,
          color: (opacity = 1) =>
            isElite ? `rgba(212, 175, 55, ${opacity})` : `rgba(37, 99, 235, ${opacity})`,
          strokeWidth: 3,
        },
      ],
      legend: [isElite ? 'Ventas (Elite)' : 'Ventas'],
    };
  }, [data, isElite]);

  return (
    <Card style={[styles.container, { backgroundColor: theme.colors.card }]}>
      <View style={styles.header}>
        <Text style={[styles.title, { color: theme.colors.text }]}>{title}</Text>
        {isElite && (
          <View style={styles.badge}>
            <Text style={styles.badgeText}>LIVE</Text>
          </View>
        )}
      </View>

      <View style={styles.chartContainer}>
        <LineChart
          data={chartData}
          width={Platform.OS === 'web' ? 500 : SCREEN_WIDTH - 64}
          height={height}
          chartConfig={chartConfig}
          bezier // Curvas suaves
          style={{
            marginVertical: 8,
            borderRadius: 16,
          }}
          withInnerLines={true}
          withOuterLines={false}
          withVerticalLines={false}
          yAxisLabel="$"
          yAxisInterval={1}
          fromZero
          segments={4}
        />
      </View>
    </Card>
  );
};

const styles = StyleSheet.create({
  container: {
    padding: 16,
    borderRadius: 20,
    marginBottom: 16,
