/**
 * 🖨️ REPOSITORIO DE DISPOSITIVOS
 * Capa de abstracción para operaciones de dispositivos e impresión
 * NUNCA llamar a Firebase directamente desde componentes o hooks de negocio
 */

import type { Database } from 'firebase/database';
import { off, onValue, ref, set, update } from 'firebase/database';
import type { PrintPolicies, PrinterRef } from '../../core/printing/policies';

/**
 * Configuración de formato de ticket
 */
export type TicketConfig = {
  // Header
  businessName: string;
  businessLogo?: string;
  businessAddress?: string;
  businessPhone?: string;
  businessRFC?: string;
  businessEmail?: string;

  // Formato
  printLogo: boolean;
  paperWidth: 48 | 58 | 80; // mm
  fontSize: 'small' | 'normal' | 'large';

  // Footer
  footerMessage?: string;
  printDate: boolean;
  printTime: boolean;
  printCashier: boolean;

  // Social
  facebook?: string;
  instagram?: string;
  whatsapp?: string;
};

export class DevicesRepository {
  constructor(private db: Database, private tenantPath: string) {}

  private getPoliciesPath() {
    return `${this.tenantPath}/ajustes/dispositivos/impresion/politicas`;
  }

  private getDefaultPrinterPath() {
    return `${this.tenantPath}/ajustes/dispositivos/impresion/defaultPrinter`;
  }

  private getTestMessagePath() {
    return `${this.tenantPath}/ajustes/dispositivos/impresion/testMessage`;
  }

  private getTicketConfigPath() {
    return `${this.tenantPath}/ajustes/ticket`;
  }

  /**
   * Suscribirse a políticas de impresión
   */
  suscribirPoliticasImpresion(
    callback: (policies: Partial<PrintPolicies> | null) => void
  ): () => void {
    const r = ref(this.db, this.getPoliciesPath());
    const cb = onValue(r, (snap) => {
      callback(snap.exists() ? (snap.val() as Partial<PrintPolicies>) : null);
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Actualizar políticas de impresión (actualización parcial)
   */
  async actualizarPoliticasImpresion(updates: Partial<PrintPolicies>): Promise<void> {
    const r = ref(this.db, this.getPoliciesPath());
    await update(r, updates);
  }

  /**
   * Suscribirse a impresora por defecto
   */
  suscribirDefaultPrinter(callback: (printer: PrinterRef | null) => void): () => void {
    const r = ref(this.db, this.getDefaultPrinterPath());
    const cb = onValue(r, (snap) => {
      callback(snap.exists() ? (snap.val() as PrinterRef) : null);
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Establecer impresora por defecto
   */
  async establecerDefaultPrinter(printer: PrinterRef | null): Promise<void> {
    const r = ref(this.db, this.getDefaultPrinterPath());
    await set(r, printer);
  }

  /**
   * Suscribirse a mensaje de prueba
   */
  suscribirTestMessage(callback: (message: string) => void): () => void {
    const r = ref(this.db, this.getTestMessagePath());
    const cb = onValue(r, (snap) => {
      callback(snap.exists() ? String(snap.val()) || '' : '');
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Establecer mensaje de prueba
   */
  async establecerTestMessage(message: string): Promise<void> {
    const r = ref(this.db, this.getTestMessagePath());
    await set(r, message || '');
  }

  /**
   * Suscribirse a configuración de formato de ticket
   */
  suscribirTicketConfig(callback: (config: Partial<TicketConfig> | null) => void): () => void {
    const r = ref(this.db, this.getTicketConfigPath());
    const cb = onValue(r, (snap) => {
      callback(snap.exists() ? (snap.val() as Partial<TicketConfig>) : null);
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Actualizar configuración de formato de ticket (reemplazo completo)
   */
  async actualizarTicketConfig(config: TicketConfig): Promise<void> {
    const r = ref(this.db, this.getTicketConfigPath());
    await set(r, config);
  }

  private getHubConfigPath() {
    return `${this.tenantPath}/config/hub`;
  }

  /**
   * Suscribirse a la configuración de Hub Central
   */
  suscribirHubConfig(callback: (config: Partial<HubConfig> | null) => void): () => void {
    const r = ref(this.db, this.getHubConfigPath());
    const cb = onValue(r, (snap) => {
      callback(snap.exists() ? (snap.val() as Partial<HubConfig>) : null);
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Establecer configuración de Hub Central (reemplazo completo)
   */
  async establecerHubConfig(config: HubConfig): Promise<void> {
    const r = ref(this.db, this.getHubConfigPath());
    await set(r, config);
  }

  /**
   * Actualizar configuración de Hub Central (actualización parcial)
   */
  async actualizarHubConfig(updates: Partial<HubConfig>): Promise<void> {
    const r = ref(this.db, this.getHubConfigPath());
    await update(r, updates);
  }
}

/**
 * Configuración de Hub Central
 */
export type HubConfig = {
  enabled: boolean;
  destination: 'restaurante' | 'venta_crudo' | null;
  updatedAt: number;
  deviceId: string;
};

/**
 * 📝 REPOSITORIO LOCAL DE BORRADORES (order_drafts_v1)
 *
 * DOGMA ADI — CORE CIEGO:
 * - Opera exclusivamente sobre SQLiteStorageAdapter. CERO Firebase.
 * - Idempotente: cada mutación exige `operationId` + `dedupeKey`.
 * - Variantes como Record<string, string> plano (sin arrays).
 * - Aislado por tenantId + deviceId. Nunca cruza tenants.
 */

import { SQLiteStorageAdapter } from '../../core/offline/storage/SQLiteStorageAdapter';
import { logger } from '../../core/monitoring';

// ─────────────────────────────────────────────────────────────────────────────
// TIPOS CANÓNICOS (schema order_drafts_v1)
// ─────────────────────────────────────────────────────────────────────────────

export type DraftItem = {
  itemId: string; // UUID del ítem — generado en punto de emisión
  draftId: string; // FK hacia order_drafts_v1
  productoId: string;
  nombre: string;
  precio: number;
  cantidad: number;
  tamano?: Record<string, string>; // variante de tamaño: plana, sin arrays
  preparacion?: Record<string, string>; // variante de preparación: plana, sin arrays
  precioBase?: number;
  deltaPrecio?: number;
  prepMinutos?: number;
};

export type DraftEstado = 'abierto' | 'enviado' | 'cerrado';
export type DraftOrigen = 'mesa' | 'takeaway' | 'barra';

export type OrderDraft = {
  draftId: string;
  mesaId: string;
  origen: DraftOrigen;
  estado: DraftEstado;
  deviceId: string;
  createdAt: number;
  updatedAt: number;
};

/** Sobre para comandos idempotentes — OBLIGATORIO en toda mutación */
export type ComandoIdempotente = {
  operationId: string; // UUID v4 único por intención
  dedupeKey: string; // `${draftId}:${deviceId}:${accion}`
};

// ─────────────────────────────────────────────────────────────────────────────
// INICIALIZACIÓN DEL SCHEMA
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Asegura que las tablas `order_drafts_v1` y `order_draft_items_v1` existan.
 * Llamar una vez al arranque del módulo POS (antes de cualquier operación).
 */
export async function inicializarSchemaDrafts(): Promise<void> {
  const adapter = SQLiteStorageAdapter as any;
  if (!adapter.db) return; // web fallback

  await adapter.db.execAsync(`
    CREATE TABLE IF NOT EXISTS order_drafts_v1 (
      draftId   TEXT PRIMARY KEY,
      mesaId    TEXT NOT NULL,
      origen    TEXT NOT NULL,
      estado    TEXT NOT NULL DEFAULT 'abierto',
      deviceId  TEXT NOT NULL,
      createdAt INTEGER NOT NULL,
      updatedAt INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS order_draft_items_v1 (
      itemId      TEXT PRIMARY KEY,
      draftId     TEXT NOT NULL REFERENCES order_drafts_v1(draftId) ON DELETE CASCADE,
      productoId  TEXT NOT NULL,
      nombre      TEXT NOT NULL,
      precio      REAL NOT NULL,
      cantidad    INTEGER NOT NULL DEFAULT 1,
      tamano      TEXT,
      preparacion TEXT,
      precioBase  REAL,
      deltaPrecio REAL,
      prepMinutos INTEGER
    );

    CREATE INDEX IF NOT EXISTS idx_drafts_mesa  ON order_drafts_v1(mesaId);
    CREATE INDEX IF NOT EXISTS idx_items_draft  ON order_draft_items_v1(draftId);
  `);

  logger.info('DRAFTS_REPO', '✅ Schema order_drafts_v1 inicializado');
}

// ─────────────────────────────────────────────────────────────────────────────
// REPOSITORIO
// ─────────────────────────────────────────────────────────────────────────────

export class DraftsLocalRepo {
  constructor(private readonly tenantId: string, private readonly deviceId: string) {}

  // ── DRAFTS ────────────────────────────────────────────────────────────────

  /** Crea un borrador nuevo. Idempotente: si ya existe con ese draftId, no duplica. */
  async crearDraft(
    cmd: ComandoIdempotente,
    draft: Omit<OrderDraft, 'createdAt' | 'updatedAt'>
  ): Promise<void> {
    const adapter = SQLiteStorageAdapter as any;
    if (!adapter.db) return;

    const ahora = Date.now();
    await adapter.db.runAsync(
      `INSERT OR IGNORE INTO order_drafts_v1
         (draftId, mesaId, origen, estado, deviceId, createdAt, updatedAt)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [draft.draftId, draft.mesaId, draft.origen, draft.estado, this.deviceId, ahora, ahora]
    );

    logger.info('DRAFTS_REPO', `Draft creado: ${draft.draftId}`, {
      operationId: cmd.operationId,
      dedupeKey: cmd.dedupeKey,
    });
  }

  /** Obtiene todos los borradores activos del tenant/dispositivo. */
  async obtenerDraftsAbiertos(): Promise<OrderDraft[]> {
    const adapter = SQLiteStorageAdapter as any;
    if (!adapter.db) return [];

    return (await adapter.db.getAllAsync(
      `SELECT * FROM order_drafts_v1
       WHERE deviceId = ? AND estado = 'abierto'
       ORDER BY updatedAt DESC`,
      [this.deviceId]
    )) as OrderDraft[];
  }

  /** Obtiene un borrador por ID de mesa (el más reciente abierto). */
  async obtenerDraftPorMesa(mesaId: string): Promise<OrderDraft | null> {
    const adapter = SQLiteStorageAdapter as any;
    if (!adapter.db) return null;

    return (await adapter.db.getFirstAsync(
      `SELECT * FROM order_drafts_v1
       WHERE mesaId = ? AND deviceId = ? AND estado = 'abierto'
       ORDER BY updatedAt DESC`,
      [mesaId, this.deviceId]
    )) as OrderDraft | null;
  }

  /** Cambia el estado del borrador (enviado/cerrado). */
  async actualizarEstado(
    cmd: ComandoIdempotente,
    draftId: string,
    nuevoEstado: DraftEstado
  ): Promise<void> {
    const adapter = SQLiteStorageAdapter as any;
    if (!adapter.db) return;

    await adapter.db.runAsync(
      `UPDATE order_drafts_v1 SET estado = ?, updatedAt = ? WHERE draftId = ?`,
      [nuevoEstado, Date.now(), draftId]
    );

    logger.info('DRAFTS_REPO', `Draft ${draftId} → ${nuevoEstado}`, {
      operationId: cmd.operationId,
    });
  }

  // ── ÍTEMS ─────────────────────────────────────────────────────────────────

  /** Agrega un ítem al borrador. Idempotente por itemId. */
  async agregarItem(cmd: ComandoIdempotente, item: DraftItem): Promise<void> {
    const adapter = SQLiteStorageAdapter as any;
    if (!adapter.db) return;

    await adapter.db.runAsync(
      `INSERT OR REPLACE INTO order_draft_items_v1
         (itemId, draftId, productoId, nombre, precio, cantidad,
          tamano, preparacion, precioBase, deltaPrecio, prepMinutos)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        item.itemId,
        item.draftId,
        item.productoId,
        item.nombre,
        item.precio,
        item.cantidad,
        item.tamano ? JSON.stringify(item.tamano) : null,
        item.preparacion ? JSON.stringify(item.preparacion) : null,
        item.precioBase ?? null,
        item.deltaPrecio ?? null,
        item.prepMinutos ?? null,
      ]
    );

    logger.info('DRAFTS_REPO', `Ítem agregado: ${item.itemId} → draft ${item.draftId}`, {
      operationId: cmd.operationId,
      dedupeKey: cmd.dedupeKey,
    });
  }

  /** Incrementa la cantidad de un ítem. */
  async incrementarCantidad(
    cmd: ComandoIdempotente,
    itemId: string,
    delta: number = 1
  ): Promise<void> {
    const adapter = SQLiteStorageAdapter as any;
    if (!adapter.db) return;

    await adapter.db.runAsync(
      `UPDATE order_draft_items_v1 SET cantidad = cantidad + ? WHERE itemId = ?`,
      [delta, itemId]
    );

    // Marcar draft actualizado
    await this._tocarDraftDeItem(itemId);

    logger.info('DRAFTS_REPO', `Cantidad +${delta} en ítem ${itemId}`, {
      operationId: cmd.operationId,
    });
  }

  /** Elimina un ítem por su ID. */
  async eliminarItem(cmd: ComandoIdempotente, itemId: string): Promise<void> {
    const adapter = SQLiteStorageAdapter as any;
    if (!adapter.db) return;

    await adapter.db.runAsync(`DELETE FROM order_draft_items_v1 WHERE itemId = ?`, [itemId]);

    logger.info('DRAFTS_REPO', `Ítem eliminado: ${itemId}`, {
      operationId: cmd.operationId,
    });
  }

  /** Obtiene todos los ítems de un borrador. */
  async obtenerItems(draftId: string): Promise<DraftItem[]> {
    const adapter = SQLiteStorageAdapter as any;
    if (!adapter.db) return [];

    const rows = (await adapter.db.getAllAsync(
      `SELECT * FROM order_draft_items_v1 WHERE draftId = ?`,
      [draftId]
    )) as Record<string, any>[];

    return rows.map((row: Record<string, any>) => ({
      itemId: row.itemId,
      draftId: row.draftId,
      productoId: row.productoId,
      nombre: row.nombre,
      precio: row.precio,
      cantidad: row.cantidad,
      tamano: row.tamano ? (JSON.parse(row.tamano) as Record<string, string>) : undefined,
      preparacion: row.preparacion
        ? (JSON.parse(row.preparacion) as Record<string, string>)
        : undefined,
      precioBase: row.precioBase ?? undefined,
      deltaPrecio: row.deltaPrecio ?? undefined,
      prepMinutos: row.prepMinutos ?? undefined,
    }));
  }

  /** Vacía todos los ítems de un borrador y marca estado cerrado. */
  async vaciarDraft(cmd: ComandoIdempotente, draftId: string): Promise<void> {
    const adapter = SQLiteStorageAdapter as any;
    if (!adapter.db) return;

    await adapter.db.runAsync(`DELETE FROM order_draft_items_v1 WHERE draftId = ?`, [draftId]);
    await adapter.db.runAsync(
      `UPDATE order_drafts_v1 SET estado = 'cerrado', updatedAt = ? WHERE draftId = ?`,
      [Date.now(), draftId]
    );

    logger.info('DRAFTS_REPO', `Draft vaciado y cerrado: ${draftId}`, {
      operationId: cmd.operationId,
    });
  }

  // ── PRIVADO ───────────────────────────────────────────────────────────────

  private async _tocarDraftDeItem(itemId: string): Promise<void> {
    const adapter = SQLiteStorageAdapter as any;
    if (!adapter.db) return;

    await adapter.db.runAsync(
      `UPDATE order_drafts_v1
       SET updatedAt = ?
       WHERE draftId = (
         SELECT draftId FROM order_draft_items_v1 WHERE itemId = ?
       )`,
      [Date.now(), itemId]
    );
  }
}

/**
 * 📦 REPOSITORIO DE INVENTARIO V2
 * Soporta jerarquías de Áreas, Catálogo Global y Transferencias Internas.
 */

import type { Database } from 'firebase/database';
import {
  get,
  off,
  onValue,
  push,
  ref,
  runTransaction,
  set,
  update,
  query,
  limitToLast,
} from 'firebase/database';
import { z } from 'zod';
import { stripVoidDeep } from '../../core/domain/itemCanonical';

// --- Esquemas de Datos ---

export type InventorySectionId = 'alimentos' | 'losa_cristaleria' | 'otros';

export const InventorySectionV2Schema = z.object({
  id: z.string(),
  nombre: z.string(),
  icon: z.string().optional(),
  stock: z.record(z.string(), z.number()).default({}),
  updatedAt: z.number(),
});

export type InventorySectionV2 = z.infer<typeof InventorySectionV2Schema>;

export const InventoryItemV2Schema = z.object({
  id: z.string(),
  nombre: z.string(),
  sectionId: z.enum(['alimentos', 'losa_cristaleria', 'otros']).optional(),
  unidad: z.enum(['kg', 'g', 'l', 'ml', 'pza', 'caja']),
  minStock: z.number().default(0),
  costo: z.number().optional(),
  proveedor: z.string().optional(),
  metadata: z.record(z.string(), z.any()).optional(),
  updatedAt: z.number(),
});

export type InventoryItemV2 = z.infer<typeof InventoryItemV2Schema>;

export const InventoryAreaV2Schema = z.object({
  id: z.string(),
  hubId: z.enum(['restaurante', 'venta_crudo']).default('restaurante'), // 🔥 Vinculación física
  sectionId: z.enum(['alimentos', 'losa_cristaleria', 'otros']).optional(),
  nombre: z.string(),
  icon: z.string().optional(),
  tipo: z.enum(['almacen', 'refri', 'mostrador', 'cocina', 'otro']).default('almacen'),
  parentId: z.string().optional(), // Para jerarquía recursiva
  stock: z.record(z.string(), z.number()).default({}), // itemId -> cantidad
  updatedAt: z.number(),
});

export type InventoryAreaV2 = z.infer<typeof InventoryAreaV2Schema>;

export const InventoryMovementV2Schema = z.object({
  id: z.string(),
  tipo: z.enum(['entrada', 'salida', 'ajuste', 'transferencia', 'merma']),
  itemId: z.string(),
  cantidad: z.number(),
  areaId: z.string().optional(), // Para entrada/salida/ajuste/merma
  fromAreaId: z.string().optional(), // Para transferencia
  toAreaId: z.string().optional(), // Para transferencia
  razon: z.string().optional(),
  usuario: z.string().optional(),
  timestamp: z.number(),
  permiteNegativo: z.boolean().optional(),
});

export type InventoryMovementV2 = z.infer<typeof InventoryMovementV2Schema>;

// --- Esquema de Ventas (Historial) ---

export const VentaV2Schema = z.object({
  id: z.string(),
  items: z.array(
    z.object({
      productoId: z.string(),
      nombre: z.string(),
      precio: z.number(),
      cantidad: z.number(),
      unidad: z.string(),
      subtotal: z.number(),
    })
  ),
  total: z.number(),
  metodoPago: z.string(),
  areaId: z.string(), // De dónde salió el stock
  usuario: z.string().optional(),
  timestamp: z.number(),
  metadata: z.record(z.string(), z.any()).optional(),
});

export type VentaV2 = z.infer<typeof VentaV2Schema>;

// --- Repositorio ---

export class InventoryV2Repository {
  private baseRef: string;

  constructor(private db: Database, tenantPath: string) {
    this.baseRef = `${tenantPath}/inventory_v2`;
  }

  // ==================== CATÁLOGO (Global por Tenant) ====================

  async crearItem(item: Omit<InventoryItemV2, 'id' | 'updatedAt'>): Promise<string> {
    const r = ref(this.db, `${this.baseRef}/catalog`);
    const newRef = push(r);
    const payload = {
      ...item,
      updatedAt: Date.now(),
    };
    await set(newRef, payload);
    return newRef.key!;
  }

  async obtenerCatalogo(): Promise<Record<string, InventoryItemV2>> {
    const snap = await get(ref(this.db, `${this.baseRef}/catalog`));
    return snap.val() || {};
  }

  suscribirCatalogo(callback: (items: Record<string, InventoryItemV2>) => void): () => void {
    const r = ref(this.db, `${this.baseRef}/catalog`);
    const cb = onValue(r, (snap) => callback(snap.val() || {}));
    return () => off(r, 'value', cb);
  }

  // ==================== ÁREAS ====================

  async crearArea(area: Omit<InventoryAreaV2, 'id' | 'updatedAt'>): Promise<string> {
    const r = ref(this.db, `${this.baseRef}/areas`);
    const newRef = push(r);
    const payload = {
      ...area,
      updatedAt: Date.now(),
    };
    await set(newRef, payload);
    return newRef.key!;
  }

  async obtenerAreas(): Promise<Record<string, InventoryAreaV2>> {
    const snap = await get(ref(this.db, `${this.baseRef}/areas`));
    return snap.val() || {};
  }

  suscribirAreas(callback: (areas: Record<string, InventoryAreaV2>) => void): () => void {
    const r = ref(this.db, `${this.baseRef}/areas`);
    const cb = onValue(r, (snap) => callback(snap.val() || {}));
    return () => off(r, 'value', cb);
  }

  async registrarMissingAreaAssignment(params: {
    hubId: 'restaurante' | 'venta_crudo';
    productoId?: string;
    itemId?: string;
    preferredAreaId?: string | null;
    fallbackAreaId: string;
    actor?: string;
    reason?: string;
    nombre?: string;
  }): Promise<void> {
    const key = params.productoId || params.itemId;
    if (!key) return;

    const r = ref(this.db, `${this.baseRef}/missing_area_assignments/${key}`);

    await runTransaction(r, (current: any) => {
      const prev = current || {};
      const next = stripVoidDeep({
        ...prev,
        hubId: params.hubId,
        productoId: params.productoId,
        itemId: params.itemId,
        preferredAreaId: params.preferredAreaId ?? undefined,
        fallbackAreaId: params.fallbackAreaId,
        actor: params.actor,
        reason: params.reason,
        nombre: params.nombre,
        lastTs: Date.now(),
        count: (typeof prev.count === 'number' ? prev.count : 0) + 1,
      });

      return next as any;
    });
  }

  // ==================== MOVIMIENTOS Y STOCK ====================

  /**
   * Registra una transferencia interna entre áreas.
   * 🔑 OPERACIÓN CRÍTICA: Descuenta de uno y suma en otro de forma atómica.
   */
  async transferir(params: {
    itemId: string;
    cantidad: number;
    fromAreaId: string;
    toAreaId: string;
    usuario?: string;
    razon?: string;
  }): Promise<void> {
    const { itemId, cantidad, fromAreaId, toAreaId, usuario, razon } = params;

    // Usar transacción para asegurar atomicidad
    const fromStockRef = ref(this.db, `${this.baseRef}/areas/${fromAreaId}/stock/${itemId}`);
    const toStockRef = ref(this.db, `${this.baseRef}/areas/${toAreaId}/stock/${itemId}`);

    // Nota: Firebase Transactions en múltiples nodos no son directas, pero podemos usar un atomo de movimiento
    // Para simplificar en RTDB, haremos un update batch
    const updates: Record<string, any> = {};

    // Obtener valores actuales (con precaución)
    const [fromSnap, toSnap] = await Promise.all([get(fromStockRef), get(toStockRef)]);
    const fromVal = fromSnap.val() || 0;
    const toVal = toSnap.val() || 0;

    if (fromVal < cantidad) throw new Error('Stock insuficiente en área origen');

    updates[`${this.baseRef}/areas/${fromAreaId}/stock/${itemId}`] = fromVal - cantidad;
    updates[`${this.baseRef}/areas/${toAreaId}/stock/${itemId}`] = toVal + cantidad;

    // Registrar el movimiento
    const movRef = push(ref(this.db, `${this.baseRef}/movements`));
    updates[`${this.baseRef}/movements/${movRef.key}`] = {
      tipo: 'transferencia',
      itemId,
      cantidad,
      fromAreaId,
      toAreaId,
      usuario,
      razon: razon || 'Transferencia interna',
      timestamp: Date.now(),
    };

    await update(ref(this.db), updates);
  }

  async registrarSalidaMultiple(params: {
    items: { itemId: string; cantidad: number; razon?: string }[];
    areaId: string;
    usuario?: string;
    razon?: string;
    allowNegative?: boolean;
    metadata?: any;
  }): Promise<void> {
    const { items, areaId, usuario, razon, allowNegative = false, metadata } = params;

    const areaRef = ref(this.db, `${this.baseRef}/areas/${areaId}`);
    const areaSnap = await get(areaRef);
    if (!areaSnap.exists()) throw new Error('Área de inventario no encontrada');
    const areaData = areaSnap.val() as InventoryAreaV2;
    const currentStock = areaData.stock || {};

    const updates: Record<string, any> = {};
    const timestamp = Date.now();

    for (const it of items) {
      const itemId = it.itemId;
      const cantidad = Number(it.cantidad) || 0;
      if (!itemId || cantidad <= 0) continue;

      const current = currentStock[itemId] || 0;
      if (!allowNegative && current < cantidad) {
        throw new Error(`Stock insuficiente para itemId=${itemId}. Disponible: ${current}`);
      }

      const newStock = allowNegative ? current - cantidad : Math.max(0, current - cantidad);
      updates[`${this.baseRef}/areas/${areaId}/stock/${itemId}`] = newStock;

      const movRef = push(ref(this.db, `${this.baseRef}/movements`));
      updates[`${this.baseRef}/movements/${movRef.key}`] = {
        tipo: 'salida',
        itemId,
        cantidad,
        areaId,
        usuario,
        razon: it.razon || razon || 'Salida',
        timestamp,
        permiteNegativo: allowNegative,
        metadata,
      };
    }

    if (Object.keys(updates).length === 0) return;
    await update(ref(this.db), updates);
  }

  /**
   * Registra mermas o desperdicios.
   */
  async registrarMerma(params: {
    itemId: string;
    areaId: string;
    cantidad: number;
    usuario?: string;
    razon: string;
  }): Promise<void> {
    const { itemId, areaId, cantidad, usuario, razon } = params;
    const stockRef = ref(this.db, `${this.baseRef}/areas/${areaId}/stock/${itemId}`);

    const snap = await get(stockRef);
    const current = snap.val() || 0;

    const updates: Record<string, any> = {};
    updates[`${this.baseRef}/areas/${areaId}/stock/${itemId}`] = Math.max(0, current - cantidad);

    const movRef = push(ref(this.db, `${this.baseRef}/movements`));
    updates[`${this.baseRef}/movements/${movRef.key}`] = {
      tipo: 'merma',
      itemId,
      cantidad,
      areaId,
      usuario,
      razon,
      timestamp: Date.now(),
    };

    await update(ref(this.db), updates);
  }

  /**
   * Venta operativa (Mostrador).
   * Descuenta stock de un área específica.
   * Valida stock antes de descontar si allowNegative es false.
   */
  async registrarVenta(params: {
    itemId: string;
    areaId: string;
    cantidad: number;
    usuario?: string;
    allowNegative?: boolean;
  }): Promise<void> {
    const { itemId, areaId, cantidad, usuario, allowNegative = false } = params;
    const stockRef = ref(this.db, `${this.baseRef}/areas/${areaId}/stock/${itemId}`);

    // Obtener snapshot actual
    const snap = await get(stockRef);
    const current = snap.val() || 0;

    // Validación estricta
    if (!allowNegative && current < cantidad) {
      throw new Error(`Stock insuficiente. Disponible: ${current}, Solicitado: ${cantidad}`);
    }

    const updates: Record<string, any> = {};

    // Calcular nuevo stock (permitiendo negativos si está habilitado)
    const newStock = allowNegative ? current - cantidad : Math.max(0, current - cantidad);

    updates[`${this.baseRef}/areas/${areaId}/stock/${itemId}`] = newStock;

    const movRef = push(ref(this.db, `${this.baseRef}/movements`));
    updates[`${this.baseRef}/movements/${movRef.key}`] = {
      tipo: 'salida',
      itemId,
      cantidad,
      areaId,
      usuario,
      razon: 'Venta Mostrador',
      timestamp: Date.now(),
      permiteNegativo: allowNegative,
    };

    await update(ref(this.db), updates);
  }

  /**
   * 🚀 REGISTRO DE VENTA POR LOTE (BATCH UPDATE)
   * Registra toda una venta en una sola transacción atómica:
   * 1. Descuenta stock de todos los items en el área.
   * 2. Registra movimientos individuales (logs).
   * 3. Guarda el registro maestro de la venta en /ventas_v2.
   */
  async registrarVentaMultiple(params: {
    items: any[];
    areaId: string;
    total: number;
    metodoPago: string;
    usuario?: string;
    allowNegative?: boolean;
    metadata?: any;
  }): Promise<string> {
    const { items, areaId, total, metodoPago, usuario, allowNegative = false, metadata } = params;

    // 1. Obtener snapshot actual del área para cálculos
    const areaRef = ref(this.db, `${this.baseRef}/areas/${areaId}`);
    const areaSnap = await get(areaRef);
    if (!areaSnap.exists()) throw new Error('Área de inventario no encontrada');

    const areaData = areaSnap.val() as InventoryAreaV2;
    const currentStock = areaData.stock || {};
    const updates: Record<string, any> = {};
    const timestamp = Date.now();

    // Generar ID de Venta
    const ventaRef = push(ref(this.db, `${this.baseRef.replace('inventory_v2', 'ventas_v2')}`));
    const ventaId = ventaRef.key!;

    // 2. Procesar cada item para el batch update
    for (const item of items) {
      const itemId = item.productoId;
      const cantidad = item.cantidad;
      const current = currentStock[itemId] || 0;

      // Validación (si no permite negativos)
      if (!allowNegative && current < cantidad) {
        throw new Error(`Stock insuficiente para ${item.nombre}. Disponible: ${current}`);
      }

      // Nuevo stock
      const newStock = allowNegative ? current - cantidad : Math.max(0, current - cantidad);
      updates[`${this.baseRef}/areas/${areaId}/stock/${itemId}`] = newStock;

      // Movimiento (Log)
      const movRef = push(ref(this.db, `${this.baseRef}/movements`));
      updates[`${this.baseRef}/movements/${movRef.key}`] = {
        tipo: 'salida',
        itemId,
        cantidad,
        areaId,
        usuario,
        razon: `Venta #${ventaId}`,
        timestamp,
        permiteNegativo: allowNegative,
      };
    }

    // 3. Registro de Venta Maestro
    const ventaPayload: VentaV2 = {
      id: ventaId,
      items: items.map((i) => ({
        productoId: i.productoId,
        nombre: i.nombre,
        precio: i.precio,
        cantidad: i.cantidad,
        unidad: i.unidad,
        subtotal: i.subtotal,
      })),
      total,
      metodoPago,
      areaId,
      usuario,
      timestamp,
      metadata,
    };

    updates[`${this.baseRef.replace('inventory_v2', 'ventas_v2')}/${ventaId}`] = ventaPayload;

    // 4. Ejecutar ráfaga atómica
    await update(ref(this.db), updates);
    console.log(`[InventoryRepo] ✅ Venta lote registrada con éxito: ${ventaId}`);

    return ventaId;
  }

  /**
   * Suscribirse a los movimientos recientes de inventario
   */
  suscribirMovimientosRecientes(
    limitCount: number,
    callback: (movements: Record<string, any>) => void
  ): () => void {
    const movementsRef = ref(this.db, `${this.baseRef}/movements`);
    const q = query(movementsRef, limitToLast(limitCount));
    const cb = onValue(q, (snap) => {
      callback(snap.val() || {});
    });
    return () => off(movementsRef, 'value', cb as any);
  }
}

/**
 * 📋 REPOSITORIO DE MENÚ
 * Capa de abstracción para operaciones de menú (categorías y productos)
 */

import type { Database } from 'firebase/database';
import { get, off, onValue, push, ref, remove, set, update } from 'firebase/database';

export type Categoria = {
  id: string;
  nombre: string;
  orden?: number;
  activa?: boolean;
  slug?: string;
  /**
   * 🔥 NUEVO: Define si items de esta categoría van a COCINA o se quedan en MESERA
   * - true (default): Items van a cocina, pasan por estados (nuevo → en_cocina → en_preparacion → listo)
   * - false: Items se quedan en mesera, saltan directo a 'listo' (bebidas, postres, etc.)
   */
  enviarACocina?: boolean;
  /**
   * ⚡ NUEVO: Define si items de esta categoría saltan el estado PREPARANDO
   * Solo aplica si enviarACocina = true
   * - false (default): Flujo completo (en_cocina → en_preparacion → listo)
   * - true: Flujo rápido (en_cocina → listo)
   */
  saltarPreparando?: boolean;
  /**
   * 👪 HERENCIA DE VISIBILIDAD
   * Configuración que se propaga a nuevos productos creados en esta categoría.
   */
  herencia?: {
    mesero?: boolean;
    digital?: boolean;
    ventaCrudo?: boolean;
  };
};

export type Producto = {
  id: string;
  nombre: string;
  precio: number;
  categoriaId: string;
  slug?: string;
  descripcion?: string;
  imagen?: string;
  variantes?: {
    grupos?: Record<string, VariantGroup>;
    reglas?: {
      visible?: Record<string, VariantRule>;
      disable?: Record<string, VariantRule>;
    };
  };
  visible?: {
    digital?: boolean;
    mesero?: boolean;
    ventaCrudo?: boolean;
  };
  activo?: boolean;
  orden?: number;
  prepMin?: number;
  receta?: {
    ingredientes?: Record<string, number>; // itemId: quantity
  };
  /**
   * 🔥 CONFIGURACIÓN DE COCINA POR PRODUCTO (prevalece sobre categoría)
   * Si usarConfigPersonalizada = true, se usan estos valores en lugar de los de la categoría
   */
  usarConfigPersonalizada?: boolean; // Si false/undefined, hereda de categoría
  enviarACocina?: boolean;
  saltarPreparando?: boolean;
  // Propiedades para módulo POS/Caja Rápida
  codigoBarras?: string;
  unidad?: 'kg' | 'g' | 'l' | 'ml' | 'pza' | 'caja';
};

export type VariantGroup = {
  obligatorio?: boolean;
  opciones: Record<string, VariantOption>;
  rol?: string; // Opcional: si falta, se asume igual a titulo
  tipo: 'single' | 'multi';
  titulo: string;
  nextGroupId?: string; // 🔥 NUEVO: Referencia al siguiente grupo en el flujo
  excludeFromSibling?: string; // 🔄 NUEVO: ID del grupo con el que no se puede repetir selección (Mixtos)
};

export type VariantOption = {
  delta?: number; // Opcional: si falta, se asume 0
  titulo: string;
  triggers?: {
    // ⚡ NUEVO: Disparadores de visibilidad dinámicos
    showGroups?: string[];
    hideGroups?: string[];
  };
};

export type VariantRule = {
  showGroups?: Record<string, boolean>;
  hideGroups?: Record<string, boolean>;
  disableGroups?: Record<string, boolean>;
  whenGroup: string;
  whenOpt: string;
};

export class MenuRepository {
  constructor(private db: Database, private tenantPath: string) {}

  private slugify(x?: string | null) {
    const raw = String(x || '').trim();
    const s = raw
      .toLowerCase()
      .normalize('NFD')
      .replace(/\p{Diacritic}/gu, '');
    const slug = s
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 48);
    if (slug) return slug;
    if (!raw) return '';

    // Fallback estable para nombres con solo emojis/símbolos.
    // Evita slug vacío y permite unicidad consistente.
    let h = 0;
    for (let i = 0; i < raw.length; i++) {
      h = (h * 31 + raw.charCodeAt(i)) >>> 0;
    }
    return `x-${h.toString(36)}`.slice(0, 48);
  }

  /**
   * Suscribir productos de una categoría específica (dual-read)
   * - Nested: menu/categorias/{catId}/productos
   * - Fallback flat: menu/productos filtrando categoriaId
   */
  suscribirProductosDeCategoria(
    catId: string,
    callback: (productos: Record<string, Producto>) => void
  ): () => void {
    const nestedRef = ref(this.db, `${this.getCategoriasPath()}/${catId}/productos`);
    const flatRef = ref(this.db, this.getFlatProductosPath());
    let nested: Record<string, Producto> = {};
    let flatFiltered: Record<string, Producto> = {};

    const emit = () => {
      callback({ ...(flatFiltered || {}), ...(nested || {}) });
    };

    const cbNested = onValue(nestedRef, (snap) => {
      const raw = ((snap.val() as any) || {}) as Record<string, any>;
      const fixed: Record<string, Producto> = {};
      for (const [pid, p] of Object.entries(raw)) {
        fixed[pid] = { ...(p as any), id: pid } as Producto;
      }
      nested = fixed;
      emit();
    });
    const cbFlat = onValue(flatRef, (snap) => {
      const all = ((snap.val() as any) || {}) as Record<string, any>;
      const filtered: Record<string, Producto> = {};
      for (const [pid, p] of Object.entries(all)) {
        if ((p as any)?.categoriaId === catId) {
          filtered[pid] = { ...(p as any), id: pid } as Producto;
        }
      }
      flatFiltered = filtered;
      emit();
    });

    return () => {
      off(nestedRef, 'value', cbNested as any);
      off(flatRef, 'value', cbFlat as any);
    };
  }

  private getFlatProductosPath() {
    return `${this.tenantPath}/menu/productos`;
  }
  private getCategoriasPath() {
    return `${this.tenantPath}/menu/categorias`;
  }
  private getIndexPath() {
    return `${this.tenantPath}/menu/productos_index`;
  }

  private async ensureUniqueCategorySlug(base: string, excludeId?: string): Promise<string> {
    const snap = await get(ref(this.db, `${this.tenantPath}/menu/categorias`));
    const cats = ((snap.val() as any) || {}) as Record<string, { slug?: string; nombre?: string }>;
    const existing = new Set(
      Object.entries(cats)
        .filter(([id]) => id !== excludeId)
        .map(([_, c]) => c?.slug || this.slugify(c?.nombre))
    );
    if (!existing.has(base)) return base;
    let i = 2;
    while (existing.has(`${base}-${i}`)) i++;
    return `${base}-${i}`;
  }

  private async ensureUniqueProductSlug(
    catId: string,
    base: string,
    excludeProdId?: string
  ): Promise<string> {
    const snap = await get(ref(this.db, this.getIndexPath()));
    const idx = ((snap.val() as any) || {}) as Record<string, { catId?: string; slug?: string }>;
    const existing = new Set(
      Object.entries(idx)
        .filter(([pid, e]) => pid !== excludeProdId && e?.catId === catId)
        .map(([_, e]) => e?.slug)
        .filter(Boolean) as string[]
    );
    if (!existing.has(base)) return base;
    let i = 2;
    while (existing.has(`${base}-${i}`)) i++;
    return `${base}-${i}`;
  }

  // ==================== CATEGORÍAS ====================

  /**
   * Suscribirse a todas las categorías
   */
  suscribirCategorias(callback: (categorias: Record<string, Categoria>) => void): () => void {
    const r = ref(this.db, `${this.tenantPath}/menu/categorias`);
    const cb = onValue(r, (snap) => {
      callback((snap.val() as any) || {});
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Obtener todas las categorías
   */
  async obtenerCategorias(): Promise<Record<string, Categoria>> {
    const snap = await get(ref(this.db, `${this.tenantPath}/menu/categorias`));
    return (snap.val() as any) || {};
  }

  /**
   * Crear categoría
   */
  async crearCategoria(categoria: Omit<Categoria, 'id'>): Promise<string> {
    const r = ref(this.db, `${this.tenantPath}/menu/categorias`);
    const newRef = push(r);
    const base = this.slugify(categoria.nombre);
    const slug = await this.ensureUniqueCategorySlug(base);
    await set(newRef, { ...categoria, slug });
    return newRef.key!;
  }

  /**
   * Actualizar categoría
   */
  async actualizarCategoria(categoriaId: string, datos: Partial<Categoria>): Promise<void> {
    const patch: any = { ...datos };
    if (datos.nombre && !('slug' in datos)) {
      const base = this.slugify(datos.nombre);
      patch.slug = await this.ensureUniqueCategorySlug(base, categoriaId);
    }
    await update(ref(this.db, `${this.tenantPath}/menu/categorias/${categoriaId}`), patch);
  }

  /**
   * Eliminar categoría
   */
  async eliminarCategoria(categoriaId: string): Promise<void> {
    await remove(ref(this.db, `${this.tenantPath}/menu/categorias/${categoriaId}`));
  }

  // ==================== PRODUCTOS ====================

  /**
   * Suscribirse a todos los productos
   */
  suscribirProductos(callback: (productos: Record<string, Producto>) => void): () => void {
    const flatRef = ref(this.db, this.getFlatProductosPath());
    let flatData: Record<string, Producto> = {};
    let nestedData: Record<string, Producto> = {};
    const nestedByCat: Record<string, Record<string, Producto>> = {};

    const emit = () => {
      const merged = { ...(flatData || {}), ...(nestedData || {}) } as Record<string, Producto>;
      callback(merged);
    };

    const flatCb = onValue(flatRef, (snap) => {
      const raw = ((snap.val() as any) || {}) as Record<string, any>;
      const fixed: Record<string, Producto> = {};
      for (const [pid, p] of Object.entries(raw)) {
        fixed[pid] = { ...(p as any), id: pid } as Producto;
      }
      flatData = fixed;
      emit();
    });

    const catsRef = ref(this.db, this.getCategoriasPath());
    const nestedUnsubs: Record<string, () => void> = {};

    const subscribeCat = (catId: string) => {
      const r = ref(this.db, `${this.getCategoriasPath()}/${catId}/productos`);
      const cb = onValue(r, (snap) => {
        const raw = ((snap.val() as any) || {}) as Record<string, any>;
        const prods: Record<string, Producto> = {};
        for (const [pid, p] of Object.entries(raw)) {
          prods[pid] = { ...(p as any), id: pid } as Producto;
        }
        nestedByCat[catId] = prods;
        // Rebuild nestedData from nestedByCat to avoid stale keys
        const rebuilt: Record<string, Producto> = {};
        for (const m of Object.values(nestedByCat)) {
          Object.assign(rebuilt, m);
        }
        nestedData = rebuilt;
        emit();
      });
      nestedUnsubs[catId] = () => off(r, 'value', cb as any);
    };

    const catsCb = onValue(catsRef, (snap) => {
      const cats = (snap.val() as any) || {};
      const catIds = new Set(Object.keys(cats));
      for (const [cid, unsub] of Object.entries(nestedUnsubs)) {
        if (!catIds.has(cid)) {
          unsub();
          delete nestedUnsubs[cid];
          delete nestedByCat[cid];
        }
      }
      for (const cid of catIds) {
        if (!nestedUnsubs[cid]) {
          subscribeCat(cid);
        }
      }
      // Rebuild after possible removals
      const rebuilt: Record<string, Producto> = {};
      for (const m of Object.values(nestedByCat)) {
        Object.assign(rebuilt, m);
      }
      nestedData = rebuilt;
      emit();
    });

    return () => {
      off(flatRef, 'value', flatCb as any);
      off(catsRef, 'value', catsCb as any);
      Object.values(nestedUnsubs).forEach((u) => u());
    };
  }

  /**
   * Obtener todos los productos
   */
  async obtenerProductos(): Promise<Record<string, Producto>> {
    const [flatSnap, catsSnap] = await Promise.all([
      get(ref(this.db, this.getFlatProductosPath())),
      get(ref(this.db, this.getCategoriasPath())),
    ]);
    const flat = (flatSnap.val() as any) || {};
    const cats = (catsSnap.val() as any) || {};
    const nested: Record<string, Producto> = {};
    const tasks: Promise<any>[] = [];
    for (const cid of Object.keys(cats)) {
      tasks.push(
        get(ref(this.db, `${this.getCategoriasPath()}/${cid}/productos`)).then((s) => {
          Object.assign(nested, (s.val() as any) || {});
        })
      );
    }
    await Promise.all(tasks);
    const merged = { ...(flat || {}), ...(nested || {}) } as Record<string, any>;
    const fixed: Record<string, Producto> = {};
    for (const [pid, p] of Object.entries(merged)) {
      fixed[pid] = { ...(p as any), id: pid } as Producto;
    }
    return fixed;
  }

  /**
   * Obtener producto por ID
   */
  async obtenerProductoPorId(productoId: string): Promise<Producto | null> {
    const idxSnap = await get(ref(this.db, `${this.getIndexPath()}/${productoId}`)).catch(
      () => null as any
    );
    const idx =
      idxSnap && (idxSnap as any).exists && (idxSnap as any).exists() ? idxSnap.val() : null;
    if (idx && idx.catId) {
      const nestedSnap = await get(
        ref(this.db, `${this.getCategoriasPath()}/${idx.catId}/productos/${productoId}`)
      );
      if (nestedSnap.exists()) {
        const val = (nestedSnap.val() as any) || null;
        return val ? ({ id: productoId, ...val } as Producto) : null;
      }
    }
    const flatSnap = await get(ref(this.db, `${this.getFlatProductosPath()}/${productoId}`));
    const fval = (flatSnap.val() as any) || null;
    return fval ? ({ id: productoId, ...fval } as Producto) : null;
  }

  /**
   * Crear producto
   */
  async crearProducto(producto: Omit<Producto, 'id'>): Promise<string> {
    const r = ref(this.db, this.getFlatProductosPath());
    const newRef = push(r);
    const id = newRef.key!;
    const baseSlug = this.slugify(producto.nombre);
    const uniqueSlug = await this.ensureUniqueProductSlug(producto.categoriaId, baseSlug);
    const payload = { ...producto, slug: uniqueSlug } as any;
    // Flat write (compat)
    await set(newRef, payload);
    // Nested write (canonical)
    const catId = producto.categoriaId;
    await set(ref(this.db, `${this.getCategoriasPath()}/${catId}/productos/${id}`), payload);
    // Index write (lookup)
    await set(ref(this.db, `${this.getIndexPath()}/${id}`), {
      catId,
      nombre: producto.nombre,
      precio: producto.precio,
      slug: payload.slug || null,
      hasReceta: !!producto?.receta,
    });
    return id;
  }

  /**
   * Actualizar producto
   */
  async actualizarProducto(productoId: string, datos: Partial<Producto>): Promise<void> {
    console.log('[MenuRepo] 📝 Actualizando producto:', {
      id: productoId,
      updates: Object.keys(datos),
    });

    // Leer producto actual para detectar cambio de categoría
    const currentSnap = await get(ref(this.db, `${this.getFlatProductosPath()}/${productoId}`));
    const current = (currentSnap.val() as any) || {};
    const prevCat = current?.categoriaId;
    const nextCat = datos.categoriaId ?? prevCat;

    if (!nextCat) {
      console.warn('[MenuRepo] ⚠️ Producto sin categoría detectado:', productoId);
    }
    const patch: any = { ...datos };
    if (datos.nombre && !('slug' in datos)) {
      const base = this.slugify(datos.nombre);
      patch.slug = await this.ensureUniqueProductSlug(nextCat, base, productoId);
    }
    // Flat
    await update(ref(this.db, `${this.getFlatProductosPath()}/${productoId}`), patch);
    // Nested: si cambió de categoría, mover
    if (prevCat && prevCat !== nextCat) {
      const prevRef = ref(
        this.db,
        `${this.getCategoriasPath()}/${prevCat}/productos/${productoId}`
      );
      const nextRef = ref(
        this.db,
        `${this.getCategoriasPath()}/${nextCat}/productos/${productoId}`
      );
      const prevDataSnap = await get(prevRef);
      const prevData = (prevDataSnap.val() as any) || {};
      const merged = { ...prevData, ...patch };
      await set(nextRef, merged);
      await set(prevRef, null as any);
    } else if (nextCat) {
      // 🔥 MIGRACIÓN AUTOMÁTICA: Leer datos completos de Flat y fusionar con patch
      const flatSnap = await get(ref(this.db, `${this.getFlatProductosPath()}/${productoId}`));
      const flatData = (flatSnap.val() as any) || {};
      const merged = { ...flatData, ...patch };
      // Usar set() en lugar de update() para crear el producto en Nested si no existe
      await set(
        ref(this.db, `${this.getCategoriasPath()}/${nextCat}/productos/${productoId}`),
        merged
      );
    }
    // Index
    await update(ref(this.db, `${this.getIndexPath()}/${productoId}`), {
      catId: nextCat,
      nombre: patch.nombre ?? current?.nombre,
      precio: patch.precio ?? current?.precio,
      slug: patch.slug ?? current?.slug ?? null,
    } as any);
  }

  /**
   * Eliminar producto
   */
  async eliminarProducto(productoId: string): Promise<void> {
    // Leer para conocer categoria
    const snap = await get(ref(this.db, `${this.getFlatProductosPath()}/${productoId}`));
    const prod = (snap.val() as any) || {};
    const catId = prod?.categoriaId;
    // Flat
    await remove(ref(this.db, `${this.getFlatProductosPath()}/${productoId}`));
    // Nested
    if (catId) {
      await remove(ref(this.db, `${this.getCategoriasPath()}/${catId}/productos/${productoId}`));
    }
    // Index
    await remove(ref(this.db, `${this.getIndexPath()}/${productoId}`));
  }

  /**
   * Activar/desactivar producto
   */
  async toggleProductoActivo(productoId: string, activo: boolean): Promise<void> {
    await this.actualizarProducto(productoId, { activo });
  }

  /**
   * 🚑 REPARACIÓN DE INTEGRIDAD (SELF-HEALING)
   * Sincroniza Flat y Nested para asegurar consistencia total.
   * Prioriza la versión que tenga 'variantes' definidas.
   */
  async repararIntegridad(): Promise<void> {
    try {
      // 1. Leer todo el universo de datos
      const [flatSnap, catsSnap] = await Promise.all([
        get(ref(this.db, this.getFlatProductosPath())),
        get(ref(this.db, this.getCategoriasPath())),
      ]);

      const flatMap = (flatSnap.val() as Record<string, Producto>) || {};
      const catsMap = (catsSnap.val() as Record<string, any>) || {};

      // Recolectar todos los productos anidados
      const nestedMap: Record<string, Producto> = {};
      Object.entries(catsMap).forEach(([catId, catData]) => {
        if (catData.productos) {
          Object.assign(nestedMap, catData.productos);
        }
      });

      const updates: Record<string, any> = {};
      const allIds = new Set([...Object.keys(flatMap), ...Object.keys(nestedMap)]);

      console.log(`[MenuRepo] 🚑 Iniciando auto-reparación en ${allIds.size} productos...`);

      allIds.forEach((id) => {
        const flat = flatMap[id];
        const nested = nestedMap[id];

        // CASO 1: Existe en ambos, pero son diferentes (Discrepancia)
        if (flat && nested) {
          const flatHasVariants = flat.variantes && Object.keys(flat.variantes || {}).length > 0;
          const nestedHasVariants =
            nested.variantes && Object.keys(nested.variantes || {}).length > 0;

          // Si Nested tiene variantes y Flat no (o nombres difieren), Nested gana -> Actualizar Flat
          // O si el nombre en Flat parece corrupto ("Categoría...") y el de Nested no
          if ((nestedHasVariants && !flatHasVariants) || nested.nombre !== flat.nombre) {
            // Preferir el que NO empiece con "Categoría" si es el caso
            const flatBadName = flat.nombre.startsWith('Categoría');
            const nestedBadName = nested.nombre.startsWith('Categoría');

            if (flatBadName && !nestedBadName) {
              updates[`${this.getFlatProductosPath()}/${id}`] = nested;
            } else if (!flatBadName && nestedBadName) {
              updates[`${this.getCategoriasPath()}/${flat.categoriaId}/productos/${id}`] = flat;
            } else {
              // Default: Nested gana si tiene variantes o es igual de válido
              updates[`${this.getFlatProductosPath()}/${id}`] = nested;
            }
          }
        }
        // CASO 2: Existe en Flat pero NO en Nested (Faltante Nested)
        else if (flat && !nested) {
          const catId = flat.categoriaId;
          if (catId) {
            updates[`${this.getCategoriasPath()}/${catId}/productos/${id}`] = flat;
          }
        }
        // CASO 3: Existe en Nested pero NO en Flat (Faltante Flat)
        else if (!flat && nested) {
          updates[`${this.getFlatProductosPath()}/${id}`] = nested;
        }
      });

      // Aplicar correcciones masivas atómicamente
      if (Object.keys(updates).length > 0) {
        console.log(
          `[MenuRepo] ✅ Aplicando ${Object.keys(updates).length} correcciones de integridad.`
        );
        await update(ref(this.db), updates);
      } else {
        console.log('[MenuRepo] ✨ Integridad verificada. Todo correcto.');
      }
    } catch (error) {
      console.error('[MenuRepo] ❌ Error en auto-reparación:', error);
    }
  }
}

/**
 * 🪑 REPOSITORIO DE MESAS
 * Capa de abstracción para operaciones de mesas
 */

import type { Database } from 'firebase/database';
import { get, off, onValue, ref, runTransaction, update } from 'firebase/database';
import { z } from 'zod';
import { ensureNumberTimestamp } from '../../core/domain/normalizers';
import { logger } from '../../core/monitoring/logger';

export type EstadoMesa = 'libre' | 'ocupada' | 'reservada' | 'solicitar_cuenta';

export type Mesa = {
  id: string;
  numero?: number;
  estado: EstadoMesa;
  pedidoActivoId?: string | null;
  updatedAt: number;
  posX?: number;
  posY?: number;
  shape?: 'square' | 'round';
};

export type MesaLayoutInput = {
  id: string;
  posX: number;
  posY: number;
  shape?: 'square' | 'round';
};

export class MesasRepository {
  constructor(private db: Database, private tenantPath: string) {}

  private getBasePath() {
    return `${this.tenantPath}/mesas`;
  }

  /**
   * Suscribirse a todas las mesas
   */
  suscribirTodas(callback: (mesas: Record<string, Mesa>) => void): () => void {
    const r = ref(this.db, this.getBasePath());
    const cb = onValue(r, (snap) => {
      callback((snap.val() as Record<string, Mesa>) || {});
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Suscribirse a una mesa específica
   */
  suscribirPorId(mesaId: string, callback: (mesa: Mesa | null) => void): () => void {
    const r = ref(this.db, `${this.getBasePath()}/${mesaId}`);
    const cb = onValue(r, (snap) => {
      callback((snap.val() as Mesa) || null);
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Obtener una mesa (una sola vez)
   */
  async obtenerPorId(mesaId: string): Promise<Mesa | null> {
    const snap = await get(ref(this.db, `${this.getBasePath()}/${mesaId}`));
    return (snap.val() as Mesa) || null;
  }

  /**
   * Obtener todas las mesas (una sola vez)
   */
  async obtenerTodas(): Promise<Record<string, Mesa>> {
    const snap = await get(ref(this.db, this.getBasePath()));
    return (snap.val() as Record<string, Mesa>) || {};
  }

  /**
   * Actualizar estado de una mesa
   */
  async actualizarEstado(mesaId: string, estado: EstadoMesa): Promise<void> {
    const now = ensureNumberTimestamp(Date.now());
    const rawPayload = { estado, updatedAt: now };
    const MesaWriteSchema = z.object({
      estado: z.string(),
      updatedAt: z.number(),
    });
    const payload = MesaWriteSchema.parse(rawPayload);
    logger.debug('MESAS_REPO', 'actualizarEstado payload', { mesaId, payload });
    await update(ref(this.db, `${this.getBasePath()}/${mesaId}`), payload);
  }

  /**
   * Asignar pedido a mesa
   */
  async asignarPedido(mesaId: string, pedidoId: string): Promise<void> {
    const now = ensureNumberTimestamp(Date.now());
    const rawPayload = { estado: 'ocupada', pedidoActivoId: pedidoId, updatedAt: now };
    const MesaWriteSchema = z.object({
      estado: z.string(),
      pedidoActivoId: z.union([z.string(), z.null()]),
      updatedAt: z.number(),
    });
    const payload = MesaWriteSchema.parse(rawPayload);
    logger.debug('MESAS_REPO', 'asignarPedido payload', { mesaId, pedidoId, payload });
    await update(ref(this.db, `${this.getBasePath()}/${mesaId}`), payload);
  }

  /**
   * Liberar mesa
   */
  async liberar(mesaId: string): Promise<void> {
    const now = ensureNumberTimestamp(Date.now());
    const rawPayload = { estado: 'libre', pedidoActivoId: null, updatedAt: now };
    const MesaWriteSchema = z.object({
      estado: z.string(),
      pedidoActivoId: z.union([z.string(), z.null()]),
      updatedAt: z.number(),
    });
    const payload = MesaWriteSchema.parse(rawPayload);
    logger.debug('MESAS_REPO', 'liberar payload', { mesaId, payload });
    await update(ref(this.db, `${this.getBasePath()}/${mesaId}`), payload);
  }

  /**
   * Eliminar mesa
   */
  async eliminar(mesaId: string): Promise<void> {
    logger.debug('MESAS_REPO', 'eliminar payload', { mesaId });
    await update(ref(this.db, this.getBasePath()), { [mesaId]: null });
  }

  /**
   * Solicitar cuenta
   */
  async solicitarCuenta(mesaId: string): Promise<void> {
    const now = ensureNumberTimestamp(Date.now());
    const rawPayload = { estado: 'solicitar_cuenta', updatedAt: now };
    const MesaWriteSchema = z.object({
      estado: z.string(),
      updatedAt: z.number(),
    });
    const payload = MesaWriteSchema.parse(rawPayload);
    logger.debug('MESAS_REPO', 'solicitarCuenta payload', { mesaId, payload });
    await update(ref(this.db, `${this.getBasePath()}/${mesaId}`), payload);
  }

  /**
   * Obtener los items del borrador (mesa pendiente) de una mesa específica
   */
  async obtenerItemsBorrador(mesaId: string): Promise<any[]> {
    const snap = await get(ref(this.db, `${this.tenantPath}/mesas_pendientes/${mesaId}/items`));
    return (snap.val() as any[]) || [];
  }

  /**
   * Intenta bloquear una mesa para el procesamiento de pedido de forma atómica
   */
  async intentarBloquearMesaPedido(
    mesaId: string,
    sessionId: string,
    timeoutMs: number
  ): Promise<{ committed: boolean; snapshotVal: any }> {
    const mesaRef = ref(this.db, `${this.getBasePath()}/${mesaId}`);
    const transactionResult = await runTransaction(mesaRef, (currentData: unknown) => {
      if (!currentData || typeof currentData !== 'object') {
        return;
      }
      const current = currentData as any;
      const now = Date.now();
      const lock = current._sendOrderLock;

      if (lock && lock.owner && lock.owner !== sessionId) {
        const age = now - (lock.timestamp ?? 0);
        if (age < timeoutMs) return; // Keep current (abort)
      }

      return {
        ...current,
        _sendOrderLock: { owner: sessionId, timestamp: now },
      };
    });

    return {
      committed: transactionResult.committed,
      snapshotVal: transactionResult.snapshot.val(),
    };
  }

  /**
   * Libera el bloqueo de procesamiento de pedido de una mesa
   */
  async liberarBloqueoMesaPedido(mesaId: string): Promise<void> {
    const mesaRef = ref(this.db, `${this.getBasePath()}/${mesaId}`);
    await update(mesaRef, { _sendOrderLock: null });
  }

  async guardarLayout(layout: MesaLayoutInput[]): Promise<void> {
    if (layout.length === 0) return;

    const payload: Record<string, number | string> = {};
    const baseRef = ref(this.db, this.getBasePath());

    layout.forEach(({ id, posX, posY, shape }) => {
      const clampedX = Math.min(1, Math.max(0, Number.isFinite(posX) ? posX : 0.5));
      const clampedY = Math.min(1, Math.max(0, Number.isFinite(posY) ? posY : 0.5));
      payload[`${id}/posX`] = clampedX;
      payload[`${id}/posY`] = clampedY;
      payload[`${id}/updatedAt`] = ensureNumberTimestamp(Date.now());
      if (shape) {
        payload[`${id}/shape`] = shape;
      }
    });

    await update(baseRef, payload);
  }
}

/**
 * 📦 REPOSITORIO DE PEDIDOS
 * Capa de abstracción para operaciones de pedidos
 * NUNCA llamar a Firebase directamente desde componentes o hooks de negocio
 */

import type { Database } from 'firebase/database';
import { get, off, onValue, ref, remove, runTransaction, set, update } from 'firebase/database';
import { ensureNumberTimestamp } from '../../core/domain/normalizers';
import { RtdbSpooler } from '../../core/printing/rtdbSpooler';
import { resolver } from '../../core/utils/paths';
import { SincronizadorCocina } from '../../dominios/alimentos_y_bebidas/sincronizacion/SincronizadorCocina';

export type PedidoItem = {
  id: string;
  nombre: string;
  cantidad: number;
  precio: number;
  variantes?: Record<string, string[]>;
  variantLabels?: string[];
  notas?: string;
  estado: 'nuevo' | 'en_cocina' | 'en_preparacion' | 'listo' | 'entregado';
  productId?: string | null; // Para descuento de inventario
  productCode?: string; // Código legible
  prepMin?: number; // Tiempo límite de preparación en minutos
  startedAt?: number; // Timestamp cuando se empezó a preparar
  agregadoAt?: number; // Timestamp cuando se agregó el item
  agregadoAtISO?: string; // ISO string
  impreso?: boolean;
  inventoryDeducted?: boolean; // ✅ NUEVO: Si ya se descontó del inventario
};

export type Pedido = {
  id: string;
  tipo: 'mesa' | 'para_llevar' | 'delivery';
  mesaId?: string;
  estatus: string;
  items: Record<string, PedidoItem>;
  totales?: {
    subtotal: number;
    total: number;
  };
  createdAt: number;
  createdAtISO?: string;
  updatedAt?: number;
  updatedAtISO?: string;
  sentToKitchenAt?: number;
  sentToKitchenAtISO?: string;
  cuentaSolicitada?: boolean;
  cuentaImpresa?: boolean; // ✅ NUEVO: Si ya se imprimió la cuenta
  cuentaImpresaAt?: number; // ✅ NUEVO: Cuándo se imprimió
  cuentaImpresaAtISO?: string; // ✅ NUEVO: ISO timestamp
  cerrado?: boolean;
  pagadoAt?: number;
  pagadoAtISO?: string;
  _seqItems?: number; // Secuencia interna para IDs de items
};

export class PedidosRepository {
  constructor(private db: Database, private tenantPath: string) {}

  private getBasePath() {
    return `${this.tenantPath}/${resolver('pedidos')}`;
  }

  private getSequencesPath() {
    return `${this.tenantPath}/secuencias`;
  }

  private formatDateYYYYMMDD(ts: number) {
    const d = new Date(ts);
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yyyy}${mm}${dd}`;
  }

  private toISO(ts: number) {
    return new Date(ts).toISOString();
  }

  private slugify(x?: string | null) {
    const s = String(x || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/\p{Diacritic}/gu, '');
    return s
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 32);
  }

  private sanitize<T>(value: T): T {
    if (value === undefined) {
      return undefined as unknown as T;
    }

    if (value === null) {
      return value;
    }

    if (Array.isArray(value)) {
      const sanitizedArray = value
        .map((item) => this.sanitize(item))
        .filter((item) => item !== undefined);
      return sanitizedArray as unknown as T;
    }

    if (typeof value === 'object' && (value as object).constructor === Object) {
      const result: Record<string, unknown> = {};
      for (const [key, rawVal] of Object.entries(value as Record<string, unknown>)) {
        const sanitizedVal = this.sanitize(rawVal as unknown);
        if (sanitizedVal !== undefined) {
          result[key] = sanitizedVal;
        }
      }
      return result as T;
    }

    return value;
  }

  /**
   * Genera un ID de pedido legible y único por día: PED-YYYYMMDD-###
   */
  private async generarIdPedido(): Promise<string> {
    const now = Date.now();
    const ymd = this.formatDateYYYYMMDD(now);
    const seqRef = ref(this.db, `${this.getSequencesPath()}/pedidos/${ymd}`);
    const { snapshot } = await runTransaction(seqRef, (current) => {
      const val = typeof current === 'number' ? current : 0;
      return val + 1;
    });
    const n = snapshot.val() as number;
    const seq = String(n).padStart(3, '0');
    return `PED-${ymd}-${seq}`;
  }

  /**
   * Genera un ID de item incremental por pedido: IT-###
   */
  private async generarIdItem(pedidoId: string): Promise<string> {
    const seqRef = ref(this.db, `${this.getBasePath()}/${pedidoId}/_seqItems`);
    const { snapshot } = await runTransaction(seqRef, (current) => {
      const val = typeof current === 'number' ? current : 0;
      return val + 1;
    });
    const n = snapshot.val() as number;
    return `IT-${String(n).padStart(3, '0')}`;
  }

  /**
   * Suscribirse a todos los pedidos
   */
  suscribirTodos(callback: (pedidos: Record<string, Pedido>) => void): () => void {
    const r = ref(this.db, this.getBasePath());
    const cb = onValue(r, (snap) => {
      callback((snap.val() as any) || {});
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Suscribirse a un pedido específico
   */
  suscribirPorId(pedidoId: string, callback: (pedido: Pedido | null) => void): () => void {
    const r = ref(this.db, `${this.getBasePath()}/${pedidoId}`);
    const cb = onValue(r, (snap) => {
      callback(snap.val() as Pedido | null);
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Suscribirse a los items de un pedido
   */
  suscribirItems(
    pedidoId: string,
    callback: (items: Record<string, PedidoItem>) => void
  ): () => void {
    const r = ref(this.db, `${this.getBasePath()}/${pedidoId}/items`);
    const cb = onValue(r, (snap) => {
      const raw = (snap.val() as any) || {};
      // logger.debug('[PedidosRepo]', 'suscribirItems', pedidoId, Object.keys(raw).length);
      callback(raw);
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Obtener un pedido (una sola vez)
   */
  async obtenerPorId(pedidoId: string): Promise<Pedido | null> {
    const snap = await get(ref(this.db, `${this.getBasePath()}/${pedidoId}`));
    return snap.val() as Pedido | null;
  }

  /**
   * Crear un nuevo pedido
   */
  async crear(pedido: Omit<Pedido, 'id'>): Promise<string> {
    const now = ensureNumberTimestamp(Date.now());
    const id = await this.generarIdPedido();
    const pedidoRef = ref(this.db, `${this.getBasePath()}/${id}`);

    // Escribir base del pedido con items vacíos para poder generar secuencia
    const payloadPedido = this.sanitize({
      ...pedido,
      items: {},
      createdAt: now,
      createdAtISO: this.toISO(now),
      updatedAt: now,
      updatedAtISO: this.toISO(now),
      _seqItems: 0,
    });
    await set(pedidoRef, payloadPedido as any);

    // Si vienen items en el payload, normalizarlos a IT-###
    const itemsPayload: Record<string, Omit<PedidoItem, 'id'>> = (pedido as any).items || {};
    for (const [, raw] of Object.entries(itemsPayload)) {
      const productCode = this.slugify((raw as any).nombre || undefined);
      await this.agregarItem(id, { ...(raw as any), productCode });
    }
    // Index por mesa: acelerar descubrimiento de pedido activo por mesa
    if ((pedido as any).mesaId) {
      const mesaId = (pedido as any).mesaId as string;
      await set(
        ref(this.db, `${this.tenantPath}/pedidos_por_mesa/${mesaId}/${id}`),
        ensureNumberTimestamp(Date.now())
      );
    }
    return id;
  }

  /**
   * Actualizar un pedido
   */
  async actualizar(pedidoId: string, datos: Partial<Pedido>): Promise<void> {
    const now = ensureNumberTimestamp(Date.now());
    const payload = this.sanitize({
      ...datos,
      updatedAt: now,
      updatedAtISO: this.toISO(now),
    });
    await update(ref(this.db, `${this.getBasePath()}/${pedidoId}`), payload as any);
  }

  /**
   * Agregar item a un pedido
   */
  async agregarItem(pedidoId: string, item: Omit<PedidoItem, 'id'>): Promise<string> {
    const itemId = await this.generarIdItem(pedidoId);
    const now = ensureNumberTimestamp(Date.now());
    const payloadItem = this.sanitize({
      ...item,
      productCode: item.productCode || this.slugify((item as any).nombre || undefined),
      agregadoAt: now,
      agregadoAtISO: this.toISO(now),
      impreso: item.impreso ?? false,
    });
    await set(
      ref(this.db, `${this.getBasePath()}/${pedidoId}/items/${itemId}`),
      payloadItem as any
    );
    // Touch updatedAt del pedido
    await this.actualizar(pedidoId, {});
    return itemId;
  }

  /**
   * Actualizar un item específico
   */
  async actualizarItem(
    pedidoId: string,
    itemId: string,
    datos: Partial<PedidoItem>
  ): Promise<void> {
    const payload = this.sanitize(datos);
    await update(ref(this.db, `${this.getBasePath()}/${pedidoId}/items/${itemId}`), payload as any);
    // Touch updatedAt del pedido
    await this.actualizar(pedidoId, {});
  }

  /**
   * Eliminar un item
   */
  async eliminarItem(pedidoId: string, itemId: string): Promise<void> {
    await remove(ref(this.db, `${this.getBasePath()}/${pedidoId}/items/${itemId}`));
  }

  /**
   * Actualizar estado de un item
   * ⚡ OPTIMIZADO: Escritura atómica directa sin doble llamada
   */
  async actualizarEstadoItem(
    pedidoId: string,
    itemId: string,
    estado: PedidoItem['estado']
  ): Promise<void> {
    const now = ensureNumberTimestamp(Date.now());
    const batchUpdates: Record<string, any> = {};
    batchUpdates[`${this.getBasePath()}/${pedidoId}/items/${itemId}/estado`] = estado;
    batchUpdates[`${this.getBasePath()}/${pedidoId}/updatedAt`] = now;
    batchUpdates[`${this.getBasePath()}/${pedidoId}/updatedAtISO`] = this.toISO(now);
    await update(ref(this.db), batchUpdates);
  }

  /**
   * ⚡ Actualizar estado de múltiples items en una sola operación atómica
   * Reduce latencia de N escrituras a 1 sola escritura
   */
  async actualizarEstadoItemsBatch(
    pedidoId: string,
    updates: { itemId: string; estado: PedidoItem['estado']; startedAt?: number }[]
  ): Promise<void> {
    const now = ensureNumberTimestamp(Date.now());
    const batchUpdates: Record<string, any> = {};

    // Actualizar cada item
    updates.forEach(({ itemId, estado, startedAt }) => {
      batchUpdates[`${this.getBasePath()}/${pedidoId}/items/${itemId}/estado`] = estado;
      if (startedAt !== undefined) {
        batchUpdates[`${this.getBasePath()}/${pedidoId}/items/${itemId}/startedAt`] = startedAt;
      }
    });

    // Actualizar timestamp del pedido
    batchUpdates[`${this.getBasePath()}/${pedidoId}/updatedAt`] = now;
    batchUpdates[`${this.getBasePath()}/${pedidoId}/updatedAtISO`] = this.toISO(now);

    await update(ref(this.db), batchUpdates);
  }

  /**
   * Marcar pedido como enviado a cocina
   * ⚡ OPTIMIZADO: Solo cambia estados, NO descuenta inventario (se mueve a transiciones)
   * ⚡ OPTIMIZADO: Lecturas mínimas y escritura atómica
   */
  async enviarACocina(pedidoId: string): Promise<void> {
    try {
      const now = ensureNumberTimestamp(Date.now());
      const nowISO = this.toISO(now);

      const postCommitTasks: (() => Promise<void>)[] = [];

      // 1. Obtener el pedido completo
      const pedido = await this.obtenerPorId(pedidoId);
      if (!pedido) {
        throw new Error('Pedido no encontrado');
      }

      // 2. Filtrar SOLO items nuevos
      const itemsNuevos = Object.entries(pedido.items || {})
        .filter(([_, item]: [string, any]) => item.estado === 'nuevo')
        .map(([itemId, item]: [string, any]) => ({ itemId, item }));

      if (itemsNuevos.length === 0) {
        if (pedido.estatus !== 'enviado_cocina' && pedido.estatus !== 'en_preparacion') {
          await this.actualizar(pedidoId, {
            estatus: 'enviado_cocina',
            sentToKitchenAt: pedido.sentToKitchenAt || now,
            sentToKitchenAtISO: pedido.sentToKitchenAtISO || nowISO,
          });
        }
        return;
      }

      const productosRef = ref(this.db, `${this.tenantPath}/${resolver('menu_productos')}`);
      const categoriasRef = ref(this.db, `${this.tenantPath}/menu/categorias`);

      const [productosSnap, categoriasSnap] = await Promise.all([
        get(productosRef),
        get(categoriasRef),
      ]);

      const productos = (productosSnap.val() as any) || {};
      const categorias = (categoriasSnap.val() as any) || {};

      const kitchenItems: { itemId: string; item: any }[] = [];
      const directItems: { itemId: string; item: any }[] = [];

      console.log(`[PedidosRepo] ⚙️ Clasificando ${itemsNuevos.length} items...`);

      for (const { itemId, item } of itemsNuevos) {
        let vaACocina = true;

        // Buscar producto
        let producto: any = null;
        if (item.productId && productos[item.productId]) {
          producto = productos[item.productId];
        } else {
          // Fallback fuzzy
          const nombreLower = (item.nombre || '').toLowerCase().trim();
          producto = Object.values(productos).find(
            (p: any) => (p.nombre || '').toLowerCase().trim() === nombreLower
          );
        }

        if (producto) {
          if (producto.usarConfigPersonalizada === true) {
            vaACocina = producto.enviarACocina !== false;
          } else {
            const categoriaId = producto.categoriaId;
            if (categoriaId && categorias[categoriaId]) {
              vaACocina = categorias[categoriaId].enviarACocina !== false;
            }
          }
        }

        if (vaACocina) {
          kitchenItems.push({ itemId, item });
        } else {
          directItems.push({ itemId, item });
        }
      }

      console.log(
        `[PedidosRepo] 📋 Clasificación: ${kitchenItems.length} a cocina, ${directItems.length} directos`
      );

      const batchUpdates: Record<string, any> = {};

      // Items for Kitchen
      if (kitchenItems.length > 0) {
        kitchenItems.forEach(({ itemId }) => {
          const path = `${this.getBasePath()}/${pedidoId}/items/${itemId}`;
          batchUpdates[`${path}/impreso`] = true;
        });

        // 🖨️ ENCOLAR COMANDA AL HUB (Canal: standard para restaurante)
        // El Hub Central escuchará esta cola y procesará la impresión
        const comandaItems = kitchenItems.map(({ item }) => ({
          nombre: item.nombre,
          cantidad: item.cantidad,
          variantes: item.variantes ? Object.values(item.variantes).flat().join(', ') : undefined,
        }));

        const spooler = new RtdbSpooler(this.db, this.tenantPath);
        const jobId = `job_comanda_v1_${pedidoId}_${now}`;

        // Fire-and-forget: No bloqueamos el flujo principal
        spooler
          .enqueueToHub({
            jobId,
            orderId: pedidoId,
            purpose: 'comanda',
            templateVersion: 'v1',
            channel: 'standard', // Comandas van al canal estándar (restaurante)
            payload: {
              mesaId: pedido.mesaId,
              tipo: pedido.tipo,
              items: comandaItems,
              timestamp: now,
            },
          } as any)
          .then(() => {
            console.log(`[PedidosRepo] 🖨️ Comanda encolada al Hub: ${jobId}`);
          })
          .catch((err) => {
            console.error('[PedidosRepo] ⚠️ Error encolando comanda:', err);
          });
      }

      // Items Direct -> Ready
      if (directItems.length > 0) {
        for (const { itemId, item } of directItems) {
          const path = `${this.getBasePath()}/${pedidoId}/items/${itemId}`;

          batchUpdates[`${path}/estado`] = 'listo';
          batchUpdates[`${path}/impreso`] = true;
          batchUpdates[`${path}/listoAt`] = now;

          if (item.productId) {
            postCommitTasks.push(async () => {
              try {
                const res = await SincronizadorCocina.descontarPorReceta(
                  item.productId,
                  item.cantidad || 1
                );
                if (res.success && res.descontados && res.descontados.length > 0) {
                  await update(ref(this.db, `${this.getBasePath()}/${pedidoId}/items/${itemId}`), {
                    inventoryDeducted: true,
                  });
                }
              } catch (e) {
                console.error(`[PedidosRepo] ⚠️ Falló descuento directo para ${item.nombre}`, e);
              }
            });
          }
        }
      }

      if (kitchenItems.length > 0) {
        batchUpdates[`${this.getBasePath()}/${pedidoId}/estatus`] = 'enviado_cocina';
        batchUpdates[`${this.getBasePath()}/${pedidoId}/sentToKitchenAt`] =
          pedido.sentToKitchenAt || now;
        batchUpdates[`${this.getBasePath()}/${pedidoId}/sentToKitchenAtISO`] =
          pedido.sentToKitchenAtISO || nowISO;
      } else {
        if (pedido.estatus === 'nuevo' || !pedido.estatus) {
          batchUpdates[`${this.getBasePath()}/${pedidoId}/estatus`] = 'listo';
        }
      }

      batchUpdates[`${this.getBasePath()}/${pedidoId}/updatedAt`] = now;
      batchUpdates[`${this.getBasePath()}/${pedidoId}/updatedAtISO`] = nowISO;

      await update(ref(this.db), batchUpdates);

      if (postCommitTasks.length > 0) {
        for (const task of postCommitTasks) {
          void task();
        }
      }
    } catch (error) {
      console.error('[PedidosRepo] Error en enviarACocina:', error);
      throw error;
    }
  }

  /**
   * Cerrar pedido (pagado)
   */
  async cerrar(pedidoId: string): Promise<void> {
    const now = ensureNumberTimestamp(Date.now());
    await this.actualizar(pedidoId, {
      cerrado: true,
      estatus: 'cerrado',
      pagadoAt: now,
      pagadoAtISO: this.toISO(now),
    });
    // Intentar limpiar índice por mesa
    try {
      const snap = await get(ref(this.db, `${this.getBasePath()}/${pedidoId}`));
      const v = (snap.val() as any) || {};
      const mesaId = v?.mesaId;
      if (mesaId) {
        await remove(ref(this.db, `${this.tenantPath}/pedidos_por_mesa/${mesaId}/${pedidoId}`));
      }
    } catch {}
  }

  /**
   * Eliminar un pedido
   */
  async eliminar(pedidoId: string): Promise<void> {
    await remove(ref(this.db, `${this.getBasePath()}/${pedidoId}`));
  }
}

/**
 * ⚙️ REPOSITORIO DE AJUSTES DE REPARTO
 * Capa de abstracción para operaciones de ajustes de reparto (umbrales, horarios, costos)
 * NUNCA llamar a Firebase directamente desde componentes o hooks de negocio
 */

import { ref, onValue, off, set, update, Unsubscribe } from 'firebase/database';
import type { Database } from 'firebase/database';

export type AjustesReparto = {
  umbrales: {
    stockBajo: number;
    maxPedidosActivos: number;
    tiempoMaxEntregaMin: number;
  };
  horarios: {
    habilitado: boolean;
    ventanas: { inicio: string; fin: string }[];
  };
  costos: {
    base: number;
    porKm: number;
    minimo: number;
  };
};

export class RepartoAjustesRepository {
  constructor(private db: Database, private tenantPath: string) {}

  private getBasePath() {
    return `${this.tenantPath}/ajustes/reparto`;
  }

  /**
   * Suscribirse a umbrales
   */
  suscribirUmbrales(callback: (umbrales: AjustesReparto['umbrales']) => void): () => void {
    const r = ref(this.db, `${this.getBasePath()}/umbrales`);
    const cb = onValue(r, (snap) => {
      const v = (snap.val() as any) || {};
      callback({
        stockBajo: Number(v.stockBajo ?? 5),
        maxPedidosActivos: Number(v.maxPedidosActivos ?? 10),
        tiempoMaxEntregaMin: Number(v.tiempoMaxEntregaMin ?? 45),
      });
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Actualizar umbrales (actualización parcial)
   */
  async actualizarUmbrales(umbrales: Partial<AjustesReparto['umbrales']>): Promise<void> {
    const r = ref(this.db, `${this.getBasePath()}/umbrales`);
    await update(r, umbrales);
  }

  /**
   * Suscribirse a horarios
   */
  suscribirHorarios(callback: (horarios: AjustesReparto['horarios']) => void): () => void {
    const r = ref(this.db, `${this.getBasePath()}/horarios`);
    const cb = onValue(r, (snap) => {
      const v = (snap.val() as any) || {};
      const ventanas = Array.isArray(v.ventanas) ? v.ventanas : [{ inicio: '09:00', fin: '18:00' }];
      callback({
        habilitado: !!v.habilitado,
        ventanas,
      });
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Actualizar horarios (actualización parcial o completa)
   */
  async actualizarHorarios(horarios: Partial<AjustesReparto['horarios']>): Promise<void> {
    const r = ref(this.db, `${this.getBasePath()}/horarios`);
    // Si viene ventanas completas, sobreescribir con set; para parches simples usar update
    if (horarios.ventanas) {
      await set(r, horarios as AjustesReparto['horarios']);
    } else {
      await update(r, horarios);
    }
  }

  /**
   * Toggle habilitado de horarios
   */
  async toggleHorarios(habilitado: boolean): Promise<void> {
    const r = ref(this.db, `${this.getBasePath()}/horarios`);
    await update(r, { habilitado });
  }

  /**
   * Suscribirse a costos
   */
  suscribirCostos(callback: (costos: AjustesReparto['costos']) => void): () => void {
    const r = ref(this.db, `${this.getBasePath()}/costos`);
    const cb = onValue(r, (snap) => {
      const v = (snap.val() as any) || {};
      callback({
        base: Number(v.base ?? 20),
        porKm: Number(v.porKm ?? 5),
        minimo: Number(v.minimo ?? 20),
      });
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Actualizar costos (actualización parcial)
   */
  async actualizarCostos(costos: Partial<AjustesReparto['costos']>): Promise<void> {
    const r = ref(this.db, `${this.getBasePath()}/costos`);
    await update(r, costos);
  }
}

/**
 * 🏢 REPOSITORIO DE TENANT
 * Capa de abstracción para operaciones de tenant (características, features, bootstrap)
 * NUNCA llamar a Firebase directamente desde componentes o hooks de negocio
 */

import type { Database } from 'firebase/database';
import { get, off, onValue, ref, update } from 'firebase/database';
import { ensureTenantBootstrap } from '../../core/bootstrap/ensureTenant';

export type Caracteristicas = {
  roles?: {
    mesero?: boolean;
    cocina?: boolean;
    ventas?: boolean;
    tienda?: boolean;
    admin?:
      | boolean
      | {
          dashboard?: boolean;
          menu?: boolean;
          inventario?: boolean;
          mesas?: boolean;
          dispositivos?: boolean;
          repart?: boolean;
          mostrador?: boolean;
          menu_add_category?: boolean;
          module_venta_crudo?: boolean;
          fastbutton_venta_crudo?: boolean;
          menu_editor_venta_crudo?: boolean;
          inventory_v2?: boolean;
        };
  };
  delivery?: boolean;
  delivery_interno_adi_repart?: boolean;
  delivery_externo?: boolean;
  reabastecimiento_cruzado?: boolean;
  tracking_repartidor?: boolean;
  solicitudes_logisticas?: boolean;
  ia_voice_assistant?: boolean;
  inventory_auto_discount?: boolean;
  menu_digital?: boolean;
  [key: string]: any;
};

export type Features = Record<string, boolean>;

export class TenantRepository {
  constructor(private db: Database, private tenantPath: string) {}

  private getCaracteristicasPath() {
    return `${this.tenantPath}/caracteristicas`;
  }

  private getFeaturesPath() {
    return `${this.tenantPath}/features`;
  }

  /**
   * Asegurar que el tenant tenga la estructura base inicializada
   */
  async asegurarBootstrap(): Promise<void> {
    await ensureTenantBootstrap(this.db, this.tenantPath);
  }

  /**
   * Obtener características del tenant (estructura anidada)
   */
  async obtenerCaracteristicas(): Promise<Caracteristicas | null> {
    const r = ref(this.db, this.getCaracteristicasPath());
    const snap = await get(r);
    return snap.exists() ? (snap.val() as Caracteristicas) : null;
  }

  /**
   * Obtener features del tenant (estructura plana)
   */
  async obtenerFeatures(): Promise<Features | null> {
    const r = ref(this.db, this.getFeaturesPath());
    const snap = await get(r);
    return snap.exists() ? (snap.val() as Features) : null;
  }

  /**
   * Obtener características o features (fallback automático)
   * Retorna el formato raw para normalización posterior
   */
  async obtenerCaracteristicasOFeatures(): Promise<{
    caracteristicas?: Caracteristicas;
    [key: string]: any;
  } | null> {
    const caract = await this.obtenerCaracteristicas();
    if (caract) {
      return { caracteristicas: caract };
    }

    const features = await this.obtenerFeatures();
    return features ? features : null;
  }

  /**
   * Suscribirse a características de admin (para dashboard)
   */
  suscribirCaracteristicasAdmin(
    callback: (
      admin:
        | boolean
        | {
            dashboard?: boolean;
            menu?: boolean;
            inventario?: boolean;
            mesas?: boolean;
            dispositivos?: boolean;
            repart?: boolean;
            mostrador?: boolean;
            menu_add_category?: boolean;
            module_venta_crudo?: boolean;
            fastbutton_venta_crudo?: boolean;
            menu_editor_venta_crudo?: boolean;
            inventory_v2?: boolean;
          }
        | undefined
    ) => void
  ): () => void {
    const r = ref(this.db, `${this.getCaracteristicasPath()}/roles/admin`);
    const cb = onValue(r, (snap) => {
      callback(snap.exists() ? (snap.val() as any) : undefined);
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Suscribirse a todas las características (root de caracteristicas)
   */
  suscribirCaracteristicas(callback: (caract: Caracteristicas) => void): () => void {
    const r = ref(this.db, this.getCaracteristicasPath());
    const cb = onValue(r, (snap) => {
      callback(snap.exists() ? (snap.val() as Caracteristicas) : {});
    });
    return () => off(r, 'value', cb as any);
  }

  /**
   * Actualizar características de admin
   */
  async actualizarCaracteristicasAdmin(
    admin: Partial<{
      dashboard?: boolean;
      menu?: boolean;
      inventario?: boolean;
      mesas?: boolean;
      dispositivos?: boolean;
      repart?: boolean;
      mostrador?: boolean;
      menu_add_category?: boolean;
      module_venta_crudo?: boolean;
      fastbutton_venta_crudo?: boolean;
      menu_editor_venta_crudo?: boolean;
      inventory_v2?: boolean;
    }>
  ): Promise<void> {
    const r = ref(this.db, `${this.getCaracteristicasPath()}/roles/admin`);
    await update(r, admin);
  }
}

import { ref, onValue, off, set, update, get } from 'firebase/database';
import type { Database } from 'firebase/database';

export type TicketElementTipo = 'texto' | 'listaProductos' | 'total' | 'fechaHora';

export type TicketTemplateElemento = {
  id: string;
  tipo: TicketElementTipo;
  label?: string;
  contenido?: string;
  posicion: { x: number; y: number };
  tamano: { width: number; height: number };
  estilo?: {
    alineacion?: 'left' | 'center' | 'right';
    fontSize?: number;
    bold?: boolean;
  };
  bloqueado?: boolean;
};

export type TicketTemplateAcciones = {
  imprimirEn?: string[];
  disparadores?: string[];
};

export type TicketTemplate = {
  idRol: string;
  nombrePlantilla: string;
  elementos: TicketTemplateElemento[];
  acciones: TicketTemplateAcciones;
  metadata: {
    actualizadoPor: string;
    actualizadoEl: number;
  };
};

export type TicketTemplatesPorRol = Record<string, TicketTemplate>;

export class TicketTemplatesRepository {
  constructor(private db: Database, private tenantPath: string) {}

  private basePath() {
    return `${this.tenantPath}/ajustes/dispositivos/tickets`;
  }

  suscribirTemplates(callback: (templates: TicketTemplatesPorRol) => void) {
    const r = ref(this.db, this.basePath());
    const cb = onValue(r, (snap) => {
      const data = (snap.val() as TicketTemplatesPorRol) || {};
      callback(data);
    });
    return () => off(r, 'value', cb as any);
  }

  async obtenerTemplate(rol: string): Promise<TicketTemplate | null> {
    const snap = await get(ref(this.db, `${this.basePath()}/${rol}`));
