/**
 * ⏱️ HOOK DE CRONÓMETRO (TIPO 1)
 *
 * Hook reutilizable para cronómetros en tiempo real.
 *
 * ARQUITECTURA MULTI-TEMPORIZADORES:
 * - TIPO 1 (Pantalla): Cronómetros locales, 100% efímeros, NUNCA se guardan en Firebase
 * - TIPO 2 (Lógica): Cron jobs en Cloud Functions (futuro)
 * - TIPO 3 (Global): Meta-orquestador para limpieza y análisis (futuro)
 *
 * REGLA DE ORO:
 * - Este cronómetro NUNCA escribe en Firebase
 * - Solo lee el timestamp de inicio UNA VEZ
 * - Calcula el tiempo transcurrido cada segundo en el cliente
 *
 * USO:
 * ```typescript
 * const { segundos, minutos, formatoMM_SS } = useCronometro(timestampInicio);
 *
 * return <Text>{formatoMM_SS}</Text>; // "5:32"
 * ```
 */

import { useEffect, useState } from 'react';

export interface CronometroResult {
  /** Segundos transcurridos desde el timestamp de inicio */
  segundos: number;

  /** Minutos transcurridos (Math.floor(segundos / 60)) */
  minutos: number;

  /** Formato MM:SS (ej: "5:32") */
  formatoMM_SS: string;

  /** Formato descriptivo (ej: "Lleva 5 minutos") */
  formatoDescriptivo: string;

  /** Indica si el cronómetro está activo (tiene timestamp válido) */
  activo: boolean;
}

/**
 * Hook de cronómetro en tiempo real
 *
 * @param timestampInicio - Timestamp de inicio en milisegundos (Date.now())
 * @param opciones - Opciones de configuración
 * @returns Objeto con tiempo transcurrido en diferentes formatos
 *
 * @example
 * ```typescript
 * // Cronómetro simple
 * const { formatoMM_SS } = useCronometro(orden.createdAt);
 *
 * // Con límite de tiempo
 * const { segundos, minutos } = useCronometro(item.startedAt);
 * const excedeLimite = minutos >= item.prepMin;
 * ```
 */
export function useCronometro(
  timestampInicio?: number,
  opciones?: {
    /** Intervalo de actualización en ms (default: 1000) */
    intervalo?: number;
    /** Si es false, el cronómetro no se actualizará (útil para pausar) */
    activo?: boolean;
  }
): CronometroResult {
  const [segundos, setSegundos] = useState(0);
  const intervalo = opciones?.intervalo ?? 1000;
  const activo = opciones?.activo ?? true;

  useEffect(() => {
    // Si no hay timestamp o está inactivo, no hacer nada
    if (!timestampInicio || !activo) {
      setSegundos(0);
      return;
    }

    // Función para calcular tiempo transcurrido
    const calcularTiempo = () => {
      const ahora = Date.now();
      const transcurrido = Math.floor((ahora - timestampInicio) / 1000);
      setSegundos(transcurrido);
    };

    // Calcular inmediatamente (primera vez)
    calcularTiempo();

    // Latir cada segundo (o intervalo configurado)
    const timer = setInterval(calcularTiempo, intervalo);

    // Limpiar al desmontar o cuando cambie el timestamp
    return () => clearInterval(timer);
  }, [timestampInicio, intervalo, activo]);

  // Calcular minutos
  const minutos = Math.floor(segundos / 60);
  const segs = segundos % 60;

  // Formato MM:SS
  const formatoMM_SS = `${minutos}:${segs.toString().padStart(2, '0')}`;

  // Formato descriptivo
  const formatoDescriptivo =
    minutos === 0 ? `${segundos} segundos` : minutos === 1 ? `1 minuto` : `${minutos} minutos`;

  return {
    segundos,
    minutos,
    formatoMM_SS,
    formatoDescriptivo,
    activo: !!timestampInicio && activo,
  };
}

/**
 * Hook de cronómetro con límite de tiempo
 *
 * Útil para items de cocina que tienen un tiempo límite de preparación.
 *
 * @param timestampInicio - Timestamp de inicio
 * @param limiteMinutos - Límite de tiempo en minutos
 * @returns Objeto con tiempo transcurrido y estado de límite
 *
 * @example
 * ```typescript
 * const { formatoMM_SS, excedeLimite, porcentaje } = useCronometroConLimite(
 *   item.startedAt,
 *   item.prepMin
 * );
 *
 * return (
 *   <View style={{ backgroundColor: excedeLimite ? 'red' : 'green' }}>
 *     <Text>{formatoMM_SS}</Text>
 *     <Text>{porcentaje}%</Text>
 *   </View>
 * );
 * ```
 */
export function useCronometroConLimite(timestampInicio?: number, limiteMinutos?: number) {
  const cronometro = useCronometro(timestampInicio);

  if (!limiteMinutos) {
    return {
      ...cronometro,
      excedeLimite: false,
      porcentaje: 0,
      tiempoRestante: 0,
    };
  }

  const limiteSegundos = limiteMinutos * 60;
  const excedeLimite = cronometro.segundos >= limiteSegundos;
  const porcentaje = Math.min(100, Math.floor((cronometro.segundos / limiteSegundos) * 100));
  const tiempoRestante = Math.max(0, limiteSegundos - cronometro.segundos);

  return {
    ...cronometro,
    excedeLimite,
    porcentaje,
    tiempoRestante,
    limiteSegundos,
  };
}

/**
 * ⚙️ ENGINE - KITCHEN QUEUE ENGINE
 *
 * Servicio Ciego del KDS (Kitchen Display System).
 *
 * DOGMA ADI:
 * - NO contiene UI.
 * - NO se conecta a Firebase directamente (recibe por sockets LAN desde Admin o lee de DB local).
 * - Centraliza toda la lógica de ordenamiento, priorización y marcado de órdenes.
 */

import { ComandoPOS } from '../../base/tipos/contratos';

export type ItemCocina = {
  id: string;
  nombre: string;
  productoId?: string;
  cantidad: number;
  precio: number;
  estado: 'nuevo' | 'en_cocina' | 'en_preparacion' | 'listo' | 'entregado';
  variantes?: Record<string, string | string[]>;
  variantLabels?: string[];
  notas?: string;
  prepMin?: number;
  startedAt?: number;
  draftId?: string;
  inventoryDeducted?: boolean;
  idsAgrupados?: string[];
};

export type OrdenCocina = {
  id: string;
  tipo: 'mesa' | 'para_llevar' | 'delivery';
  mesaId?: string;
  estatus: string;
  items: ItemCocina[];
  itemsTotal: number;
  itemsPendientes: number;
  itemsListos: number;
  tiempoTranscurrido: number;
  esUrgente: boolean;
  createdAt: number;
  sentToKitchenAt?: number;
};

export type EstadisticasCocina = {
  total: number;
  urgentes: number;
  itemsPendientes: number;
  itemsListos: number;
};

export class KitchenQueueEngine {
  private ordenes: Map<string, OrdenCocina> = new Map();
  private subscribers: Set<(ordenes: OrdenCocina[]) => void> = new Set();
  private urgentThresholdMs: number;

  constructor(urgentThresholdMinutes: number = 15) {
    this.urgentThresholdMs = urgentThresholdMinutes * 60 * 1000;
  }

  /**
   * Suscribe a cambios en la cola (para que la UI reaccione)
   */
  subscribe(callback: (ordenes: OrdenCocina[]) => void): () => void {
    this.subscribers.add(callback);
    callback(this.getOrdenesOrdenadas());
    return () => this.subscribers.delete(callback);
  }

  private notify() {
    const ordenes = this.getOrdenesOrdenadas();
    this.subscribers.forEach((cb) => cb(ordenes));
  }

  /**
   * Ingresa órdenes desde un Socket LAN o base de datos local
   */
  ingresarOrdenes(nuevasOrdenes: OrdenCocina[]) {
    nuevasOrdenes.forEach((orden) => {
      this.ordenes.set(orden.id, orden);
    });
    this.notify();
  }

  /**
   * Retorna las órdenes activas ordenadas (urgentes primero, luego más antiguas)
   */
  getOrdenesOrdenadas(): OrdenCocina[] {
    const now = Date.now();

    const activas = Array.from(this.ordenes.values())
      .map((o) => {
        const baseTime = o.sentToKitchenAt || o.createdAt || now;
        o.esUrgente = now - baseTime >= this.urgentThresholdMs;
        o.tiempoTranscurrido = Math.floor((now - baseTime) / 1000);
        return o;
      })
      .filter((o) => o.estatus === 'enviado_cocina' || o.estatus === 'en_preparacion');

    activas.sort((a, b) => {
      if (a.esUrgente !== b.esUrgente) return a.esUrgente ? -1 : 1;
      const timeA = a.sentToKitchenAt || a.createdAt;
      const timeB = b.sentToKitchenAt || b.createdAt;
      return timeA - timeB;
    });

    return activas;
  }

  getEstadisticas(): EstadisticasCocina {
    const activas = this.getOrdenesOrdenadas();
    return {
      total: activas.length,
      urgentes: activas.filter((o) => o.esUrgente).length,
      itemsPendientes: activas.reduce((sum, o) => sum + o.itemsPendientes, 0),
      itemsListos: activas.reduce((sum, o) => sum + o.itemsListos, 0),
    };
  }

  /**
   * Comienza a preparar un item (actualiza local y genera evento para LAN)
   */
  async startItem(ordenId: string, itemId: string): Promise<void> {
    const orden = this.ordenes.get(ordenId);
    if (!orden) throw new Error(`Orden ${ordenId} no encontrada`);

    const item = orden.items.find((i) => i.id === itemId);
    if (!item) throw new Error(`Item ${itemId} no encontrado`);

    item.estado = 'en_preparacion';
    item.startedAt = Date.now();

    // Si la orden estaba como 'enviado_cocina', pasa a 'en_preparacion'
    if (orden.estatus === 'enviado_cocina') {
      orden.estatus = 'en_preparacion';
    }

    // TODO: Emitir evento LAN/Update local DB (esto será interceptado por el host LAN)
    console.log(`[KitchenQueueEngine] Item started: ${itemId}`);

    this.notify();
  }

  /**
   * Finaliza la preparación de un item
   */
  async finishItem(ordenId: string, itemId: string): Promise<void> {
    const orden = this.ordenes.get(ordenId);
    if (!orden) throw new Error(`Orden ${ordenId} no encontrada`);

    const item = orden.items.find((i) => i.id === itemId);
    if (!item) throw new Error(`Item ${itemId} no encontrado`);

    item.estado = 'listo';

    // Check si toda la orden está lista
    const todosListos = orden.items.every((i) => i.estado === 'listo' || i.estado === 'entregado');
    if (todosListos) {
      orden.estatus = 'listo';
    }

    console.log(`[KitchenQueueEngine] Item finished: ${itemId}`);

    this.notify();
  }

  /**
   * Finaliza toda la orden
   */
  async finishOrder(ordenId: string): Promise<void> {
    const orden = this.ordenes.get(ordenId);
    if (!orden) throw new Error(`Orden ${ordenId} no encontrada`);

    orden.items.forEach((i) => {
      if (i.estado !== 'entregado') {
        i.estado = 'listo';
      }
    });
    orden.estatus = 'listo';

    console.log(`[KitchenQueueEngine] Order finished: ${ordenId}`);

    this.notify();
  }
}

export const kitchenEngine = new KitchenQueueEngine();

import React, { useMemo } from 'react';
import { useStore } from '../store';
import { descomponerRutaTenant } from '../rtdb/rutas/RutaTenant';
import { FallbackScreen } from './FallbackScreen';
import { SCREEN_REGISTRY } from './ScreenRegistry';
import type { ScreenRegistroEntrada, ScreenResuelto, TargetNichoEntrada } from './tipos';

export function useScreenResolver(roleKey: string): ScreenResuelto {
  const sesion = useStore((s) => s.sesion);

  return useMemo(() => {
    if (!roleKey) {
      return {
        Screen: () => <FallbackScreen role={roleKey} message="No se especificó un rol válido." />,
        props: {},
        loading: false,
        error: 'Key de rol inválida',
        niche: sesion.niche,
        category: sesion.category,
      };
    }

    const roleEntry = SCREEN_REGISTRY[roleKey];
    if (!roleEntry || !roleEntry.Screen) {
      return {
        Screen: () => (
          <FallbackScreen role={roleKey} niche={sesion.niche} category={sesion.category} />
        ),
        props: {},
        loading: false,
        error: `Rol '${roleKey}' no registrado en la Fábrica de Marisquerías`,
        niche: sesion.niche,
        category: sesion.category,
      };
    }

    const { Screen, staticProps } = roleEntry as any;

    return {
      Screen,
      props: {
        ...(staticProps || {}),
      },
      loading: false,
      error: null,
      niche: sesion.niche,
      category: sesion.category,
    };
  }, [roleKey, sesion.niche, sesion.category]);
}

