/**
 * 🎯 GESTOS NATIVOS - ANDROID
 *
 * Maneja gestos para navegación sin botones físicos
 * - Deslizar desde borde izquierdo → Back
 * - Deslizar desde abajo → Home/Salir
 */

import { useEffect, useRef } from 'react';
import { BackHandler, Dimensions, PanResponder } from 'react-native';
import { router } from 'expo-router';

type GestureConfig = {
  enableBackGesture?: boolean;
  enableHomeGesture?: boolean;
  onBack?: () => boolean | void;
  onHome?: () => void;
};

export function useGestureNavigation(config: GestureConfig = {}) {
  const { enableBackGesture = true, enableHomeGesture = true, onBack, onHome } = config;

  const { width, height } = Dimensions.get('window');
  const EDGE_THRESHOLD = 30; // Área desde el borde para iniciar gesto
  const SWIPE_THRESHOLD = width * 0.3; // 30% de la pantalla para confirmar
  const HOME_THRESHOLD = height * 0.5; // 50% de la pantalla para salir

  const gestureState = useRef({
    isBackGesture: false,
    isHomeGesture: false,
    startX: 0,
    startY: 0,
  });

  // PanResponder para gestos
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: (evt) => {
        const { locationX, locationY } = evt.nativeEvent;

        // Detectar inicio de gesto de back (borde izquierdo)
        if (enableBackGesture && locationX < EDGE_THRESHOLD) {
          gestureState.current.isBackGesture = true;
          gestureState.current.startX = locationX;
          return true;
        }

        // Detectar inicio de gesto de home (borde inferior)
        if (enableHomeGesture && locationY > height - EDGE_THRESHOLD) {
          gestureState.current.isHomeGesture = true;
          gestureState.current.startY = locationY;
          return true;
        }

        return false;
      },

      onMoveShouldSetPanResponder: () => {
        return gestureState.current.isBackGesture || gestureState.current.isHomeGesture;
      },

      onPanResponderMove: (evt, gestureState) => {
        // Aquí podrías agregar feedback visual si quieres
      },

      onPanResponderRelease: (evt, gesture) => {
        const { dx, dy } = gesture;

        // Gesto de BACK (deslizar desde izquierda hacia derecha)
        if (gestureState.current.isBackGesture && dx > SWIPE_THRESHOLD) {
          if (onBack) {
            const handled = onBack();
            if (handled !== false) {
              router.back();
            }
          } else {
            router.back();
          }
        }

        // Gesto de HOME (deslizar desde abajo hacia arriba)
        if (gestureState.current.isHomeGesture && Math.abs(dy) > HOME_THRESHOLD) {
          if (onHome) {
            onHome();
          } else {
            // Salir de la app (Android)
            BackHandler.exitApp();
          }
        }

        // Reset
        gestureState.current.isBackGesture = false;
        gestureState.current.isHomeGesture = false;
      },

      onPanResponderTerminate: () => {
        gestureState.current.isBackGesture = false;
        gestureState.current.isHomeGesture = false;
      },
    })
  ).current;

  // Manejar botón físico de back (si existe)
  useEffect(() => {
    if (!enableBackGesture) return;

    const backHandler = BackHandler.addEventListener('hardwareBackPress', () => {
      if (onBack) {
        const handled = onBack();
        return handled !== false;
      }
      return false;
    });

    return () => backHandler.remove();
  }, [enableBackGesture, onBack]);

  return {
    panHandlers: panResponder.panHandlers,
  };
}

import NetInfo from '@react-native-community/netinfo';
import { ref, set } from 'firebase/database';
import { useEffect, useRef, useState } from 'react';
import { getRtdb } from '../firebase';
import { OfflinePrintFallback } from '../services/OfflinePrintFallback';
import { PrintSpooler } from '../services/PrintSpooler';

type HubManagerProps = {
  enabled: boolean;
  tenantPath: string;
  deviceId: string;
  channel?: string;
};

export const HubManager = (props: HubManagerProps) => {
  const { enabled, tenantPath, deviceId, channel } = props;
  const spoolerRef = useRef<PrintSpooler | null>(null);
  const [isOnline, setIsOnline] = useState(true);
  const [isStandby, setIsStandby] = useState(false);

  // 🔌 Network status listener
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener((state) => {
      const wasOffline = !isOnline;
      const nowOnline = state.isConnected ?? false;
      setIsOnline(nowOnline);

      if (!nowOnline && !isStandby) {
        console.log('[HubManager] 🔴 Network lost, entering STANDBY mode...');
        setIsStandby(true);
        // Detener spooler para no intentar leer de Firebase
        if (spoolerRef.current) {
          spoolerRef.current.stop();
        }
      } else if (nowOnline && isStandby) {
        console.log('[HubManager] 🟢 Network restored, exiting STANDBY mode...');
        setIsStandby(false);
        // Reiniciar spooler
        if (spoolerRef.current && enabled) {
          spoolerRef.current.start();
        }
        // Procesar cola local de impresión
        OfflinePrintFallback.processLocalQueue();
      }
    });

    return () => unsubscribe();
  }, [isOnline, isStandby, enabled]);

  // 🖨️ Spooler lifecycle
  useEffect(() => {
    if (enabled && tenantPath && isOnline) {
      console.log('[HubManager] 🟢 Activando modo HUB...');

      const db = getRtdb();

      const spooler = PrintSpooler.getInstance(
        db,
        tenantPath,
        deviceId,
        {
          autoProcess: true,
          maxRetries: 1,
          channel: props.channel,
        },
        'hub'
      );

      spoolerRef.current = spooler;
      spooler.start();

      console.log('[HubManager] ✅ Spooler HUB inicializado');

      // 🔥 HEARTBEAT: Avisar que estamos vivos cada 30 segundos
      const heartbeatInterval = setInterval(async () => {
        if (enabled && tenantPath && isOnline) {
          const heartbeatRef = ref(db, `${tenantPath}/config/hub/heartbeat`);
          await set(heartbeatRef, Date.now());
        }
      }, 30000);

      return () => {
        clearInterval(heartbeatInterval);
        if (spoolerRef.current) {
          console.log('[HubManager] 🛑 Deteniendo spooler en cleanup');
          spoolerRef.current.stop();
        }
      };
    } else if (!enabled || !isOnline) {
      console.log(`[HubManager] 🔴 Hub ${!enabled ? 'desactivado' : 'en standby (sin red)'}`);
      if (spoolerRef.current) {
        spoolerRef.current.stop();
      }
    }

    return () => {
      if (spoolerRef.current) {
        console.log('[HubManager] 🛑 Deteniendo spooler en cleanup');
        spoolerRef.current.stop();
      }
    };
  }, [enabled, tenantPath, deviceId, channel, isOnline]);

  return null; // Componente invisible
};

/**
 * Hook para obtener el estado del Hub desde otros componentes
 */
export const useHubStatus = () => {
  const [status, setStatus] = useState<{
    isOnline: boolean;
    pendingLocalJobs: number;
  }>({ isOnline: true, pendingLocalJobs: 0 });

  useEffect(() => {
    const checkStatus = async () => {
      const fallbackStatus = OfflinePrintFallback.getStatus();
      const pendingCount = await OfflinePrintFallback.getPendingCount();
      setStatus({
        isOnline: fallbackStatus.isOnline,
        pendingLocalJobs: pendingCount,
      });
    };

    checkStatus();
    const interval = setInterval(checkStatus, 5000);
    return () => clearInterval(interval);
  }, []);

  return status;
};

import type { Database } from 'firebase/database';
import { get, ref, set, update } from 'firebase/database';
import type { DeviceQueuePort, SpoolJob, SpoolerPort } from './ports';
import { buildJobId } from './ports';

export class RtdbSpooler implements SpoolerPort, DeviceQueuePort {
  constructor(private db: Database, private tenantPath: string) {}

  private jobPath(jobId: string) {
    return `${this.tenantPath}/spool/jobs/${jobId}`;
  }
  private deviceQueuePath(deviceId: string, jobId?: string) {
    return `${this.tenantPath}/spool/devices/${deviceId}/queue${jobId ? `/${jobId}` : ''}`;
  }

  /** 🆕 Path para la cola centralizada del Hub */
  private hubQueuePath(jobId?: string, channel: string = 'standard') {
    return `${this.tenantPath}/spool/hub/${channel === 'standard' ? '' : `${channel}/`}queue${
      jobId ? `/${jobId}` : ''
    }`.replace('//', '/');
  }

  /**
   * 🆕 Encola un trabajo en la cola centralizada del Hub
   * Usado cuando el modo de impresión es "hub"
   */
  async enqueueToHub(
    input: Omit<SpoolJob, 'state' | 'attempts' | 'createdAt' | 'updatedAt'>
  ): Promise<SpoolJob> {
    const jobId =
      input.jobId ||
      buildJobId({
        orderId: input.orderId,
        purpose: input.purpose,
        templateVersion: input.templateVersion,
      });
    const now = Date.now();
    const channel = input.channel || (input.purpose === 'venta_crudo' ? 'venta_crudo' : 'standard');
    const job: SpoolJob = {
      ...input,
      channel,
      jobId,
      state: 'pendiente_impresion',
      attempts: 0,
      createdAt: now,
      updatedAt: now,
    };

    // 🔥 OPTIMIZATION: Parallel writes for lower latency
    await Promise.all([
      set(ref(this.db, this.jobPath(jobId)), job),
      set(ref(this.db, this.hubQueuePath(jobId, channel)), true),
    ]);

    return job;
  }

  /**
   * 🆕 Remueve un trabajo de la cola del Hub
   */
  async removeFromHubQueue(jobId: string, channel: string = 'standard'): Promise<void> {
    await set(ref(this.db, this.hubQueuePath(jobId, channel)), null as any);
  }

  /**
   * 🆕 Lista todos los trabajos pendientes en la cola del Hub
   */
  async listHubQueue(channel: string = 'standard'): Promise<string[]> {
    const snap = await get(ref(this.db, this.hubQueuePath(undefined, channel)));
    if (!snap.exists()) return [];
    const v = snap.val() || {};
    return Object.keys(v);
  }

  async enqueue(
    input: Omit<SpoolJob, 'state' | 'attempts' | 'createdAt' | 'updatedAt'>
  ): Promise<SpoolJob> {
    const jobId =
      input.jobId ||
      buildJobId({
        orderId: input.orderId,
        purpose: input.purpose,
        templateVersion: input.templateVersion,
      });
    const now = Date.now();
    const job: SpoolJob = {
      ...input,
      jobId,
      state: 'pendiente_impresion',
      attempts: 0,
      createdAt: now,
      updatedAt: now,
    };
    await set(ref(this.db, this.jobPath(jobId)), job);
    if (input.deviceId) {
      await set(ref(this.db, this.deviceQueuePath(input.deviceId, jobId)), true);
    }
    return job;
  }

  async cancel(jobId: string): Promise<void> {
    await update(ref(this.db, this.jobPath(jobId)), {
      state: 'fallo',
      lastError: 'cancelled',
      updatedAt: Date.now(),
    });
  }

  async get(jobId: string): Promise<SpoolJob | null> {
    const snap = await get(ref(this.db, this.jobPath(jobId)));
    return snap.exists() ? (snap.val() as SpoolJob) : null;
  }

  async addToDeviceQueue(deviceId: string, jobId: string): Promise<void> {
    await set(ref(this.db, this.deviceQueuePath(deviceId, jobId)), true);
  }

  async removeFromDeviceQueue(deviceId: string, jobId: string): Promise<void> {
    await set(ref(this.db, this.deviceQueuePath(deviceId, jobId)), null as any);
  }

  async listDeviceQueue(deviceId: string): Promise<string[]> {
    const snap = await get(ref(this.db, this.deviceQueuePath(deviceId)));
    if (!snap.exists()) return [];
    const v = snap.val() || {};
    return Object.keys(v);
  }
}

/**
 * 🔒 DEVICE BINDING (VINCULACIÓN DE DISPOSITIVO)
 *
 * Sistema de seguridad que vincula un código de acceso a un dispositivo específico.
 *
 * FLUJO:
 * 1. Usuario ingresa código de acceso por primera vez
 * 2. Sistema obtiene ID único del dispositivo
 * 3. Guarda vinculación en AsyncStorage local
 * 4. Guarda dispositivo autorizado en Firebase
 * 5. Próximas veces: Salta pantalla de código
 *
 * SEGURIDAD:
 * - Código solo se pide la primera vez en cada dispositivo
 * - Si roban el dispositivo, puedes revocar acceso desde Firebase Console
 * - Si reinstalan la app, AsyncStorage se limpia y pide código de nuevo
 *
 * USO:
 * ```typescript
 * import { deviceBinding } from '@/core/security/deviceBinding';
 *
 * // Verificar si dispositivo ya está registrado
 * const isRegistered = await deviceBinding.isDeviceRegistered();
 *
 * // Registrar dispositivo después de login exitoso
 * await deviceBinding.registerDevice(tenantId);
 *
 * // Obtener info del dispositivo
 * const info = await deviceBinding.getDeviceInfo();
 * ```
 */

import AsyncStorage from '@react-native-async-storage/async-storage';
import { ref, serverTimestamp, set } from 'firebase/database';
import DeviceInfo from 'react-native-device-info';
// 🔥 FIX: getRtdb se carga lazy para evitar dependencia circular
import { logger } from '../monitoring';
import { validarRutaTenant, descomponerRutaTenant } from '../rtdb/rutas/RutaTenant';

const STORAGE_KEY = 'device_registered';
const STORAGE_KEY_DEVICE_ID = 'device_id';

export interface DeviceInfoData {
  /** ID único del dispositivo */
  deviceId: string;

  /** Marca del dispositivo (ej: "Samsung") */
  brand: string;

  /** Modelo del dispositivo (ej: "Galaxy A52") */
  model: string;

  /** Versión del sistema operativo */
  systemVersion: string;

  /** Nombre del sistema operativo */
  systemName: string;

  /** Si es un emulador/simulador */
  isEmulator: boolean;
}

/**
 * Obtener información del dispositivo actual
 */
export async function getDeviceInfo(): Promise<DeviceInfoData> {
  try {
    const [deviceId, brand, model, systemVersion, systemName, isEmulator] = await Promise.all([
      DeviceInfo.getUniqueId(),
      DeviceInfo.getBrand(),
      DeviceInfo.getModel(),
      DeviceInfo.getSystemVersion(),
      DeviceInfo.getSystemName(),
      DeviceInfo.isEmulator(),
    ]);

    return {
      deviceId,
      brand,
      model,
      systemVersion,
      systemName,
      isEmulator,
    };
  } catch (error) {
    logger.error('SECURITY', 'Error al obtener info del dispositivo', error as Error);
    throw error;
  }
}

/**
 * Verificar si el dispositivo actual ya está registrado
 *
 * @returns true si el dispositivo ya está vinculado a un tenant
 */
export async function isDeviceRegistered(): Promise<boolean> {
  try {
    const raw = await AsyncStorage.getItem('adi_dispositivo_vinculado');
    if (!raw) return false;
    const dispositivo = JSON.parse(raw);
    return dispositivo && dispositivo.estado === 'activo' && !!dispositivo.deviceIdADI;
  } catch (error) {
    logger.error('SECURITY', 'Error al verificar registro de dispositivo', error as Error);
    return false;
  }
}

/**
 * Registrar el dispositivo actual como autorizador
 *
 * Guarda:
 * 1. Flag local en AsyncStorage (para saltar pantalla de código)
 * 2. Info del dispositivo en Firebase (para auditoría y revocación)
 *
 * @param tenantPath - Path del tenant (ej: "2 alimentos_y_bebidas/marisquerias/puerto-libres")
 */
export async function registerDevice(tenantPath: string): Promise<void> {
  try {
    if (!validarRutaTenant(tenantPath)) {
      throw new Error(`Intento de registrar dispositivo en ruta inválida/legacy: ${tenantPath}`);
    }

    const { resolverDeviceIdADI } = await import(
      '../../instalacion/vinculacion/generar-device-id-adi'
    );
    const deviceIdADI = await resolverDeviceIdADI();
    const deviceInfo = await getDeviceInfo();

    // 1. Guardar flags locales de compatibilidad
    await AsyncStorage.setItem(STORAGE_KEY, 'true');
    await AsyncStorage.setItem(STORAGE_KEY_DEVICE_ID, deviceIdADI);
    await AsyncStorage.setItem('adi_device_id_persistent', deviceIdADI);

    // Guardar también en la persistencia de vinculación local
    const localVinculoRaw = await AsyncStorage.getItem('adi_dispositivo_vinculado');
    let localVinculo = localVinculoRaw ? JSON.parse(localVinculoRaw) : null;
    if (!localVinculo) {
      localVinculo = {
        deviceIdADI,
        tenantPath,
        tenantId: descomponerRutaTenant(tenantPath)?.tenantId || 'desconocido',
        aliasDispositivo: `Fierro ADI ${deviceIdADI.substring(4, 10)}`,
        estado: 'activo',
        nivelOperativo: 'operador',
        puedeCambiarRol: true,
        vinculadoEn: Date.now(),
        actualizadoEn: Date.now(),
      };
      await AsyncStorage.setItem('adi_dispositivo_vinculado', JSON.stringify(localVinculo));
    }

    // 2. Guardar en Firebase para auditoría
    // 🔥 FIX: Import dinámico para evitar ciclo
    const { getRtdb } = await import('../firebase');
    const db = getRtdb();
    const deviceRef = ref(db, `${tenantPath}/dispositivos_autorizados/${deviceIdADI}`);

    await set(deviceRef, {
      deviceId: deviceIdADI,
      brand: deviceInfo.brand,
      model: deviceInfo.model,
      systemVersion: deviceInfo.systemVersion,
      systemName: deviceInfo.systemName,
      isEmulator: deviceInfo.isEmulator,
      estado: 'activo',
      fechaRegistro: serverTimestamp(),
      ultimoAcceso: serverTimestamp(),
    });

    logger.info('SECURITY', 'Dispositivo registrado exitosamente', {
      deviceId: deviceIdADI,
      model: deviceInfo.model,
    });

    logger.event('device_registered', {
      tenantPath,
      deviceId: deviceIdADI,
      model: deviceInfo.model,
    });
  } catch (error) {
    logger.error('SECURITY', 'Error al registrar dispositivo', error as Error);
    throw error;
  }
}

/**
 * Actualizar timestamp de último acceso del dispositivo
 *
 * Llamar esto cada vez que la app inicia para mantener registro de actividad.
 *
 * @param tenantPath - Path del tenant
 */
export async function updateLastAccess(tenantPath: string): Promise<void> {
  try {
    if (!validarRutaTenant(tenantPath)) {
      logger.warn('SECURITY', 'Intento de actualizar último acceso con ruta inválida/legacy', {
        tenantPath,
      });
      return;
    }

    const deviceId = await getStoredDeviceId();
    if (!deviceId) return;

    // 🔥 FIX: Import dinámico para evitar ciclo
    const { getRtdb } = await import('../firebase');
    const db = getRtdb();
    const deviceRef = ref(db, `${tenantPath}/dispositivos_autorizados/${deviceId}/ultimoAcceso`);

    await set(deviceRef, serverTimestamp());

    logger.debug('SECURITY', 'Último acceso actualizado', { deviceId });
  } catch (error) {
    logger.warn('SECURITY', 'Error al actualizar último acceso', { error });
  }
}

/**
 * Desregistrar el dispositivo actual
 *
 * Útil para:
 * - Logout completo
 * - Testing
 * - Cambio de tenant
 */
export async function unregisterDevice(): Promise<void> {
  try {
    await AsyncStorage.removeItem(STORAGE_KEY);
    await AsyncStorage.removeItem(STORAGE_KEY_DEVICE_ID);
    await AsyncStorage.removeItem('adi_dispositivo_vinculado');
    await AsyncStorage.removeItem('adi_device_id_persistent');

    logger.info('SECURITY', 'Dispositivo desregistrado');
  } catch (error) {
    logger.error('SECURITY', 'Error al desregistrar dispositivo', error as Error);
    throw error;
  }
}

/**
 * Obtener ID del dispositivo guardado localmente
 *
 * @returns Device ID o null si no está registrado
 */
export async function getStoredDeviceId(): Promise<string | null> {
  try {
    const raw = await AsyncStorage.getItem('adi_dispositivo_vinculado');
    if (raw) {
      const dispositivo = JSON.parse(raw);
      if (dispositivo && dispositivo.deviceIdADI) {
        return dispositivo.deviceIdADI;
      }
    }
    const legacyId = await AsyncStorage.getItem(STORAGE_KEY_DEVICE_ID);
    if (legacyId) return legacyId;
    return await AsyncStorage.getItem('adi_device_id_persistent');
  } catch (error) {
    logger.error('SECURITY', 'Error al obtener device ID', error as Error);
    return null;
  }
}

// Exportar como objeto para facilitar mocking en tests
export const deviceBinding = {
  getDeviceInfo,
  isDeviceRegistered,
  registerDevice,
  updateLastAccess,
  unregisterDevice,
  getStoredDeviceId,
};

/**
 * 🎯 MODERADOR DE COMANDAS
 *
 * Sistema tonto que DISTRIBUYE información de comandas.
 * NO toma decisiones de negocio, solo ENRUTA.
 *
 * RESPONSABILIDADES:
 * 1. Verificar si items van a COCINA o se quedan en MESERA
 * 2. Distribuir a los destinos correctos (cocina, inventario, analytics, etc.)
 * 3. Validar que operaciones son por MESA (no por usuario)
 * 4. Limitar usuarios suscritos por mesa (máx 3 activos)
 *
 * PRINCIPIOS:
 * - Todo se basa en mesaId
 * - No mezclar lógica de notificaciones
 * - Operaciones atómicas
 */

import { Database, get, ref, runTransaction } from 'firebase/database';
import { resolver } from '../utils/paths';

type ItemParaEnviar = {
  productId?: string;
  nombre: string;
  cantidad: number;
  precio: number;
  variantes?: Record<string, string[]>;
  categoriaId?: string;
};

type ResultadoDistribucion = {
  success: boolean;
  itemsACocina: string[]; // IDs de items que fueron a cocina
  itemsAMesera: string[]; // IDs de items que se quedaron en mesera
  error?: string;
};

export class ModeradorComandas {
  constructor(private db: Database, private tenantPath: string) {}

  /**
   * 🎯 DISTRIBUIR ITEMS DE UNA COMANDA
   *
   * Decide qué va a cocina y qué se queda en mesera según configuración de categorías.
   *
   * @param mesaId - ID de la mesa (TODO se basa en esto)
   * @param pedidoId - ID del pedido/cuenta
   * @param items - Items a distribuir
   * @returns Resultado con IDs distribuidos
   */
  async distribuirComanda(
    mesaId: string,
    pedidoId: string,
    items: ItemParaEnviar[]
  ): Promise<ResultadoDistribucion> {
    try {
      // 1. Obtener configuración de categorías y productos
      const [categoriasSnap, productosSnap] = await Promise.all([
        get(ref(this.db, `${this.tenantPath}/menu/categorias`)),
        get(ref(this.db, `${this.tenantPath}/menu/productos`)),
      ]);
      const categorias = categoriasSnap.val() || {};
      const productos = productosSnap.val() || {};

      const itemsACocina: string[] = [];
      const itemsAMesera: string[] = [];

      // 2. Clasificar items según su configuración (producto > categoría)
      for (const item of items) {
        const categoriaId = item.categoriaId;
        const productId = item.productId;
        const categoria = categoriaId ? categorias[categoriaId] : null;
        const producto = productId ? productos[productId] : null;

        // 🔥 RESOLUCIÓN DE HERENCIA:
        // Si el producto tiene config personalizada, usar la del producto
        // Si no, heredar de la categoría
        let vaACocina: boolean;
        if (producto?.usarConfigPersonalizada) {
          // Usar configuración del producto
          vaACocina = producto.enviarACocina !== false;
        } else {
          // Heredar de la categoría (o default true si no hay categoría)
          vaACocina = categoria?.enviarACocina !== false;
        }

        if (vaACocina) {
          itemsACocina.push(item.nombre);
        } else {
          itemsAMesera.push(item.nombre);
        }
      }

      console.log('[ModeradorComandas] 📊 Distribución:', {
        mesaId,
        pedidoId,
        aCocina: itemsACocina.length,
        aMesera: itemsAMesera.length,
      });

      // 3. Actualizar estado de items según destino
      const updates: Record<string, any> = {};
      const pedidoRef = ref(this.db, `${this.tenantPath}/${resolver('pedidos')}/${pedidoId}`);
      const pedidoSnap = await get(pedidoRef);
      const pedido = pedidoSnap.val();

      if (!pedido || !pedido.items) {
        throw new Error('Pedido no encontrado o sin items');
      }

      // Validar que pedido pertenece a la mesa
      if (pedido.mesaId !== mesaId) {
        throw new Error(`Pedido ${pedidoId} no pertenece a mesa ${mesaId}`);
      }

      // Marcar items según destino
      Object.entries(pedido.items).forEach(([itemId, itemData]: [string, any]) => {
        const itemNombre = itemData.nombre;

        if (itemsACocina.includes(itemNombre)) {
          // Items que van a cocina: estado 'en_cocina'
          updates[`items/${itemId}/estado`] = 'en_cocina';
          updates[`items/${itemId}/destinoCocina`] = true;
        } else if (itemsAMesera.includes(itemNombre)) {
          // Items que se quedan en mesera: estado 'listo' directo (sin pasar por cocina)
          updates[`items/${itemId}/estado`] = 'listo';
          updates[`items/${itemId}/destinoCocina`] = false;
          updates[`items/${itemId}/listoAt`] = Date.now();
        }
      });

      // 4. Aplicar actualizaciones con runTransaction (atómico)
      await runTransaction(pedidoRef, (currentPedido) => {
        if (!currentPedido) return currentPedido;

        // Validar mesa nuevamente
        if (currentPedido.mesaId !== mesaId) {
          throw new Error('Mesa ID no coincide');
        }

        // Aplicar updates
        Object.entries(updates).forEach(([path, value]) => {
          const keys = path.split('/');
          let target: any = currentPedido;

          for (let i = 0; i < keys.length - 1; i++) {
            target = target[keys[i]];
          }

          target[keys[keys.length - 1]] = value;
        });

        currentPedido.updatedAt = Date.now();
        return currentPedido;
      });

      return {
        success: true,
        itemsACocina,
        itemsAMesera,
      };
    } catch (error) {
      console.error('[ModeradorComandas] ❌ Error distribuyendo comanda:', error);
      return {
        success: false,
        itemsACocina: [],
        itemsAMesera: [],
        error: error instanceof Error ? error.message : 'Error desconocido',
      };
    }
  }

  /**
   * 🔒 VALIDAR LÍMITE DE USUARIOS POR MESA
   *
   * Máximo 3 usuarios pueden estar suscritos activamente a una mesa.
   * Los demás solo pueden ver (read-only).
   *
   * @param mesaId - ID de la mesa
   * @param userId - ID del usuario que quiere suscribirse
   * @returns true si puede editar, false si solo puede ver
   */
  async validarAccesoMesa(mesaId: string, userId: string): Promise<boolean> {
    try {
      const mesaRef = ref(this.db, `${this.tenantPath}/${resolver('mesas_estado')}/${mesaId}`);

      const result = await runTransaction(mesaRef, (mesa) => {
        if (!mesa) {
          // Mesa no existe, crear con usuario
          return {
            ...mesa,
            usuariosActivos: {
              [userId]: {
                timestamp: Date.now(),
                puedeEditar: true,
              },
            },
          };
        }

        const usuariosActivos = mesa.usuariosActivos || {};
        const usuariosEditando = Object.values(usuariosActivos).filter(
          (u: any) => u.puedeEditar
        ).length;

        // Si ya está el usuario, mantener su estado
        if (usuariosActivos[userId]) {
          return mesa;
        }

        // Si hay menos de 3 usuarios editando, agregar con permisos
        if (usuariosEditando < 3) {
          usuariosActivos[userId] = {
            timestamp: Date.now(),
            puedeEditar: true,
          };
        } else {
          // Si ya hay 3, agregar como solo lectura
          usuariosActivos[userId] = {
            timestamp: Date.now(),
            puedeEditar: false,
          };
        }

        return {
          ...mesa,
          usuariosActivos,
        };
      });

      if (!result.committed) {
        return false;
      }

      const mesa = result.snapshot.val();
      return mesa?.usuariosActivos?.[userId]?.puedeEditar || false;
    } catch (error) {
      console.error('[ModeradorComandas] ❌ Error validando acceso:', error);
      return false;
    }
  }

  /**
   * 🚪 DESUSCRIBIR USUARIO DE MESA
   *
   * Liberar slot cuando usuario sale de mesa.
   */
  async desuscribirUsuario(mesaId: string, userId: string): Promise<void> {
    try {
      const mesaRef = ref(this.db, `${this.tenantPath}/${resolver('mesas_estado')}/${mesaId}`);

      await runTransaction(mesaRef, (mesa) => {
        if (!mesa || !mesa.usuariosActivos) return mesa;

        delete mesa.usuariosActivos[userId];

        // Si no quedan usuarios, limpiar objeto
        if (Object.keys(mesa.usuariosActivos).length === 0) {
          delete mesa.usuariosActivos;
        }

        return mesa;
      });
    } catch (error) {
      console.error('[ModeradorComandas] ❌ Error desuscribiendo usuario:', error);
    }
  }
}

/**
 * 🔌 OFFLINE PRINT FALLBACK
 *
 * Servicio que maneja la impresión cuando no hay conexión a Firebase.
 * Prioridades:
 * 1. Hub Firebase (cuando online)
 * 2. Bluetooth directo (cuando offline pero BT disponible)
 * 3. Cola local SQLite (cuando no hay nada más)
 *
 * DOGMA V2: Este servicio es independiente del PrintSpooler principal.
 * Se activa automáticamente cuando detecta pérdida de conexión.
 */

import NetInfo from '@react-native-community/netinfo';
import { logger } from '../monitoring';
import { SQLiteStorageAdapter } from '../offline/storage/SQLiteStorageAdapter';
import { hardwareService } from './HardwareService';

// ═══════════════════════════════════════════════════════════════════════════
// TIPOS
// ═══════════════════════════════════════════════════════════════════════════

export interface OfflinePrintJob {
  id: string;
  type: 'comanda' | 'cuenta' | 'venta_crudo';
  payload: any;
  createdAt: number;
}

export type PrintResult = {
  success: boolean;
  method: 'hub' | 'bluetooth' | 'queued';
  message?: string;
};

// ═══════════════════════════════════════════════════════════════════════════
// SERVICIO
// ═══════════════════════════════════════════════════════════════════════════

class OfflinePrintFallbackClass {
  private isOnline = true;
  private isBluetoothConnected = false;
  private unsubscribeNetInfo: (() => void) | null = null;

  /**
   * Inicializa el servicio de fallback.
   * Debe llamarse al inicio de la app.
   */
  async initialize(): Promise<void> {
    // Inicializar SQLite
    await SQLiteStorageAdapter.initialize();

    // Escuchar cambios de red
    this.unsubscribeNetInfo = NetInfo.addEventListener((state) => {
      const wasOffline = !this.isOnline;
      this.isOnline = state.isConnected ?? false;

      if (wasOffline && this.isOnline) {
        logger.info('OFFLINE_PRINT', '🌐 Network restored, processing local queue...');
        this.processLocalQueue();
      }
    });

    // Verificar estado inicial de Bluetooth
    this.checkBluetoothStatus();

    logger.info('OFFLINE_PRINT', '✅ Offline print fallback initialized');
  }

  /**
   * Detiene el servicio
   */
  destroy(): void {
    if (this.unsubscribeNetInfo) {
      this.unsubscribeNetInfo();
      this.unsubscribeNetInfo = null;
    }
  }

  /**
   * Verifica si hay impresora Bluetooth conectada
   */
  private async checkBluetoothStatus(): Promise<void> {
    try {
      // Usar el hardwareService existente para verificar conexión
      const status = hardwareService.getState();
      this.isBluetoothConnected = status.isConnected;
    } catch (error) {
      this.isBluetoothConnected = false;
    }
  }

  /**
   * Imprime un ticket con fallback automático.
   * @returns El método usado para imprimir
   */
  async print(job: OfflinePrintJob): Promise<PrintResult> {
    await this.checkBluetoothStatus();

    // 1. Si hay internet, delegar al Hub (el caller usará PrintSpooler)
    if (this.isOnline) {
      return { success: true, method: 'hub', message: 'Delegado a Hub' };
    }

    // 2. Si hay Bluetooth, imprimir directo
    if (this.isBluetoothConnected) {
      try {
        const result = await this.printViaBluetooth(job);
        if (result.success) {
          return { success: true, method: 'bluetooth', message: 'Impreso vía Bluetooth' };
        }
      } catch (error: any) {
        logger.warn('OFFLINE_PRINT', `Bluetooth print failed: ${error?.message}`);
      }
    }

    // 3. Último recurso: encolar en SQLite
    await this.enqueueLocally(job);
    return { success: true, method: 'queued', message: 'Encolado para cuando haya conexión' };
  }

  /**
   * Imprime directamente vía Bluetooth usando el hardware service existente
   */
  private async printViaBluetooth(job: OfflinePrintJob): Promise<{ success: boolean }> {
    const { type, payload } = job;

    switch (type) {
      case 'comanda':
        await hardwareService.imprimirComanda(payload, { rol: 'cocina' });
        break;
      case 'cuenta':
        await hardwareService.imprimirCuenta(payload, {
          rol: 'caja',
          tenantName: payload.businessName || 'Restaurante',
        });
        break;
      case 'venta_crudo':
        await hardwareService.imprimirTicketVenta(payload, {
          nombreNegocio: payload.businessName || 'NEGOCIO',
          encabezado: payload.businessName || 'TICKET',
          mensajeFinal: payload.footer || '¡Gracias!',
        });
        break;
      default:
        throw new Error(`Tipo de impresión no soportado: ${type}`);
    }

    logger.info('OFFLINE_PRINT', `✅ Impreso vía Bluetooth: ${job.id}`);
    return { success: true };
  }

  /**
   * Encola un job en SQLite para procesarlo después
   */
  private async enqueueLocally(job: OfflinePrintJob): Promise<void> {
    await SQLiteStorageAdapter.enqueuePrintJob(
      job.id,
      { type: job.type, payload: job.payload },
      'hub' // Target es hub porque cuando haya red se reenviará
    );
    logger.info('OFFLINE_PRINT', `📦 Encolado localmente: ${job.id}`);
  }

  /**
   * Procesa la cola local cuando vuelve la conexión
   */
  async processLocalQueue(): Promise<void> {
    if (!this.isOnline) return;

    const pendingJobs = await SQLiteStorageAdapter.getPendingPrintJobs();

    if (pendingJobs.length === 0) {
      logger.info('OFFLINE_PRINT', 'No hay jobs pendientes en cola local');
      return;
    }

    logger.info('OFFLINE_PRINT', `Procesando ${pendingJobs.length} jobs de cola local...`);

    for (const job of pendingJobs) {
      try {
        // Parsear el ticket data
        const data = JSON.parse(job.ticketData);

        // Intentar imprimir vía Bluetooth primero (más rápido que esperar Hub)
        await this.checkBluetoothStatus();

        if (this.isBluetoothConnected) {
          await this.printViaBluetooth({
            id: job.id,
            type: data.type,
            payload: data.payload,
            createdAt: job.createdAt,
          });
        }

        // Marcar como completado
        await SQLiteStorageAdapter.markPrintJobCompleted(job.id);
        logger.info('OFFLINE_PRINT', `✅ Job local procesado: ${job.id}`);
      } catch (error: any) {
        logger.error('OFFLINE_PRINT', `❌ Error procesando job local ${job.id}:`, error);
        await SQLiteStorageAdapter.incrementPrintJobAttempts(job.id);

        // Si excede 3 intentos, marcar como fallido
        if (job.attempts >= 3) {
          await SQLiteStorageAdapter.markPrintJobFailed(job.id);
        }
      }
    }
  }

  /**
   * Obtiene el número de jobs pendientes en cola local
   */
  async getPendingCount(): Promise<number> {
    const jobs = await SQLiteStorageAdapter.getPendingPrintJobs();
    return jobs.length;
  }

  /**
   * Verifica el estado actual del servicio
   */
  getStatus(): { isOnline: boolean; isBluetoothConnected: boolean } {
    return {
      isOnline: this.isOnline,
      isBluetoothConnected: this.isBluetoothConnected,
    };
  }
}

// Singleton
export const OfflinePrintFallback = new OfflinePrintFallbackClass();

