/**
 * 🔄 HOOK UNIFICADO DE SINCRONIZACIÓN DE ARRAYS
 *
 * Reemplaza:
 * - useMultiDeviceSync
 * - useOptimisticArray (de useOptimisticRTDB)
 *
 * CARACTERÍSTICAS:
 * - Sincronización en tiempo real con Firebase
 * - Updates optimistas (UI instantánea)
 * - Transacciones atómicas (sin race conditions)
 * - Detección automática de ecos
 * - IDs únicos obligatorios
 *
 * USO:
 * ```ts
 * const { items, loading, addItem, removeItem, updateItem } = useSynchronizedArray({
 *   db,
 *   path: `${tenantPath}/mesas_pendientes/${mesaId}/items`,
 *   optimistic: true, // UI instantánea
 * });
 * ```
 */

import { Database } from 'firebase/database';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  SynchronizationService,
  synchronizationService,
  type SynchronizableItem,
} from './SynchronizationService';
import { createLogger } from '../utils/logger';

const log = createLogger('useSynchronizedArray');

export interface UseSynchronizedArrayConfig<T extends SynchronizableItem> {
  /** Instancia de Firebase Database */
  db: Database;

  /** Path completo en Firebase (ej: "tenant/mesas_pendientes/mesa1/items") */
  path: string | null;

  /** Habilitar updates optimistas (default: true) */
  optimistic?: boolean;

  /** Tiempo en ms para detectar ecos (default: 150ms) */
  echoWindow?: number;

  /** Callback cuando hay cambios remotos */
  onRemoteChange?: (items: T[]) => void;

  /** Callback cuando hay error */
  onError?: (error: Error) => void;
}

export interface SynchronizedArrayResult<T extends SynchronizableItem> {
  /** Items sincronizados (fuente de verdad) */
  items: T[];

  /** Estado de carga inicial */
  loading: boolean;

  /** Estado de conexión */
  isOnline: boolean;

  /** Timestamp de última sincronización */
  lastSync: number;

  /** Agregar item (con ID único automático si no se provee) */
  addItem: (item: Omit<T, 'id'> & { id?: string }) => Promise<boolean>;

  /** Actualizar item por ID */
  updateItem: (id: string, updates: Partial<Omit<T, 'id'>>) => Promise<boolean>;

  /** Eliminar item por ID */
  removeItem: (id: string) => Promise<boolean>;

  /** Limpiar todos los items */
  clear: () => Promise<boolean>;

  /** Obtener item por ID */
  getItemById: (id: string) => T | undefined;

  /** Obtener item por índice (legacy support) */
  getItemByIndex: (index: number) => T | undefined;
}

/**
 * Hook unificado para sincronización de arrays
 */
export function useSynchronizedArray<T extends SynchronizableItem>(
  config: UseSynchronizedArrayConfig<T>
): SynchronizedArrayResult<T> {
  const { db, path, optimistic = true, echoWindow = 150, onRemoteChange, onError } = config;

  const [items, setItems] = useState<T[]>([]);
  const [loading, setLoading] = useState(true);
  const [isOnline, setIsOnline] = useState(true);
  const [lastSync, setLastSync] = useState(0);

  // Refs para evitar closure stale
  const itemsRef = useRef<T[]>([]);
  const pathRef = useRef<string | null>(null);
  const optimisticItemsRef = useRef<T[]>([]); // Estado optimista local

  // Actualizar refs
  useEffect(() => {
    itemsRef.current = items;
  }, [items]);

  useEffect(() => {
    pathRef.current = path;
  }, [path]);

  // Suscripción a Firebase
  useEffect(() => {
    if (!path) {
      setItems([]);
      setLoading(false);
      optimisticItemsRef.current = [];
      return;
    }

    log.debug(`🔗 Iniciando suscripción: ${path}`);
    setLoading(true);

    const unsubscribe = synchronizationService.subscribe(
      db,
      {
        path,
        echoWindow,
        onRemoteChange: (newItems) => {
          // Actualizar estado real
          setItems(newItems as T[]);
          optimisticItemsRef.current = newItems as T[];
          setLastSync(Date.now());
          setIsOnline(true);

          // Notificar callback
          onRemoteChange?.(newItems as T[]);
        },
        onError: (error) => {
          log.error('❌ Error en sincronización:', error);
          setIsOnline(false);
          setLoading(false);
          onError?.(error);
        },
      },
      (newItems) => {
        // Callback interno del servicio
        setItems(newItems as T[]);
        optimisticItemsRef.current = newItems as T[];
        setLastSync(Date.now());
        setIsOnline(true);
        setLoading(false);
      }
    );

    return () => {
      log.debug(`🔌 Limpiando suscripción: ${path}`);
      unsubscribe();
    };
  }, [db, path, echoWindow, onRemoteChange, onError]);

  // Agregar item
  const addItem = useCallback(
    async (item: Omit<T, 'id'> & { id?: string }): Promise<boolean> => {
      const activePath = pathRef.current;
      if (!activePath) {
        log.warn('⚠️ Path no disponible para agregar item');
        return false;
      }

      // Update optimista
      if (optimistic) {
        const itemWithId = synchronizationService.ensureId(item);
        const optimisticItems = [...optimisticItemsRef.current, itemWithId];
        optimisticItemsRef.current = optimisticItems;
        setItems(optimisticItems);
      }

      // Operación real
      const success = await synchronizationService.addItem<T>(db, activePath, item);

      if (!success && optimistic) {
        // Rollback en caso de error
        optimisticItemsRef.current = itemsRef.current;
        setItems(itemsRef.current);
        log.warn('⚠️ Rollback: error al agregar item');
      }

      return success;
    },
    [db, optimistic]
  );

  // Actualizar item por ID
  const updateItem = useCallback(
    async (id: string, updates: Partial<Omit<T, 'id'>>): Promise<boolean> => {
      const activePath = pathRef.current;
      if (!activePath) {
        log.warn('⚠️ Path no disponible para actualizar item');
        return false;
      }

      // Update optimista
      if (optimistic) {
        const optimisticItems = optimisticItemsRef.current.map((item) =>
          item.id === id ? { ...item, ...updates } : item
        );
        optimisticItemsRef.current = optimisticItems;
        setItems(optimisticItems);
      }

      // Operación real
      const success = await synchronizationService.updateItemById<T>(db, activePath, id, updates);

      if (!success && optimistic) {
        // Rollback
        optimisticItemsRef.current = itemsRef.current;
        setItems(itemsRef.current);
        log.warn('⚠️ Rollback: error al actualizar item');
      }

      return success;
    },
    [db, optimistic]
  );

  // Eliminar item por ID
  const removeItem = useCallback(
    async (id: string): Promise<boolean> => {
      const activePath = pathRef.current;
      if (!activePath) {
        log.warn('⚠️ Path no disponible para eliminar item');
        return false;
      }

      // Update optimista
      if (optimistic) {
        const optimisticItems = optimisticItemsRef.current.filter((item) => item.id !== id);
        optimisticItemsRef.current = optimisticItems;
        setItems(optimisticItems);
      }

      // Operación real
      const success = await synchronizationService.removeItemById(db, activePath, id);

      if (!success && optimistic) {
        // Rollback
        optimisticItemsRef.current = itemsRef.current;
        setItems(itemsRef.current);
        log.warn('⚠️ Rollback: error al eliminar item');
      }

      return success;
    },
    [db, optimistic]
  );

  // Limpiar todos los items
  const clear = useCallback(async (): Promise<boolean> => {
    const activePath = pathRef.current;
    if (!activePath) {
      setItems([]);
      optimisticItemsRef.current = [];
      return true;
    }

    // Update optimista
    if (optimistic) {
      optimisticItemsRef.current = [];
      setItems([]);
    }

    // Operación real
    const success = await synchronizationService.clearItems(db, activePath);

    if (!success && optimistic) {
      // Rollback
      optimisticItemsRef.current = itemsRef.current;
      setItems(itemsRef.current);
      log.warn('⚠️ Rollback: error al limpiar items');
    }

    return success;
  }, [db, optimistic]);

  // Helpers
  const getItemById = useCallback((id: string): T | undefined => {
    return itemsRef.current.find((item) => item.id === id);
  }, []);

  const getItemByIndex = useCallback((index: number): T | undefined => {
    return index >= 0 && index < itemsRef.current.length ? itemsRef.current[index] : undefined;
  }, []);

  return {
    items,
    loading,
    isOnline,
    lastSync,
    addItem,
    updateItem,
    removeItem,
    clear,
    getItemById,
    getItemByIndex,
  };
}

/**
 * 🧹 LIMPIADOR DE LOGS
 *
 * Reduce logs excesivos en producción manteniendo solo los críticos
 */

import { createLogger } from './logger';

const log = createLogger('LogCleaner');

/**
 * Niveles de logging
 */
export enum LogLevel {
  NONE = 0,
  ERROR = 1,
  WARN = 2,
  INFO = 3,
  DEBUG = 4,
}

/**
 * Configuración de logging por módulo
 */
const LOG_CONFIG: Record<string, LogLevel> = {
  // Críticos: siempre mostrar
  SynchronizationService: LogLevel.INFO,
  useSynchronizedArray: LogLevel.INFO,
  useMeseroLogic: LogLevel.INFO,
  useProductSelector: LogLevel.INFO,

  // Moderados: solo warnings y errores
  DASHBOARD: LogLevel.WARN,
  RolePacker: LogLevel.WARN,
  PrintNotificationListener: LogLevel.WARN,
  ItemStatusListener: LogLevel.WARN,

  // Verbosos: solo errores
  HardwareService: LogLevel.ERROR,
  usePrinterConnection: LogLevel.ERROR,
  BluetoothPrinterModal: LogLevel.ERROR,

  // Por defecto: INFO
  default: LogLevel.INFO,
};

/**
 * Obtiene el nivel de log para un módulo
 */
function getLogLevel(module: string): LogLevel {
  return LOG_CONFIG[module] || LOG_CONFIG['default'];
}

/**
 * Verifica si un log debe mostrarse
 */
export function shouldLog(module: string, level: 'error' | 'warn' | 'info' | 'debug'): boolean {
  const configLevel = getLogLevel(module);
  const messageLevel =
    level === 'error'
      ? LogLevel.ERROR
      : level === 'warn'
      ? LogLevel.WARN
      : level === 'info'
      ? LogLevel.INFO
      : LogLevel.DEBUG;

  return messageLevel <= configLevel;
}

/**
 * Wrapper para console.log que respeta configuración
 */
export function conditionalLog(
  module: string,
  level: 'error' | 'warn' | 'info' | 'debug',
  message: string,
  ...args: any[]
): void {
  if (!shouldLog(module, level)) return;

  const prefix = `[${module}]`;
  switch (level) {
    case 'error':
      console.error(prefix, message, ...args);
      break;
    case 'warn':
      console.warn(prefix, message, ...args);
      break;
    case 'info':
      console.log(prefix, message, ...args);
      break;
    case 'debug':
      console.log(prefix, message, ...args);
      break;
  }
}

/**
 * 🚀 CEREBRO - PROCESAMIENTO DE PEDIDOS
 * Módulo encargado de gestionar el envío de pedidos a cocina
 * SEPARACIÓN SAGRADA: Solo lógica pura de negocio
 */

import { useState, useRef, useEffect, useCallback } from 'react';
import { PedidosRepository, MesasRepository } from '../../../base/_persistencia';
import { PendingItem } from '../useMeseroLogic';
import { createLogger } from '../../../core/utils/logger';

const log = createLogger('procesarPedido');

const LOCK_TIMEOUT_MS = 15000;

type MesaSnapshot = {
  estado?: string;
  pedidoActivoId?: string | null;
  updatedAt?: number;
  _sendOrderLock?: {
    owner?: string;
    timestamp?: number;
  } | null;
};

type ProcesarPedidoProps = {
  selectedTable: string | null;
  activePendingItemsRef: React.MutableRefObject<PendingItem[]>;
  clearPendingItems: (subpedidoId?: string) => Promise<void>;
  addDraftItem: (item: PendingItem) => Promise<any>;
  tenantId: string;
  pedidosRepo: PedidosRepository;
  mesasRepo: MesasRepository;
};

const buildPedidoItemPayload = (item: PendingItem) => {
  const payload: any = {
    nombre: item.name,
    precio: item.price,
    cantidad: item.qty,
    estado: 'nuevo' as const,
    productId: item.productId || null,
    prepMin: item.prepMin || null,
    impreso: true,
  };

  if (item.id) {
    payload.draftId = item.id;
  }

  if (item.variants !== undefined) {
    payload.variantes = item.variants;
  }

  if ((item as any).variantLabels !== undefined) {
    payload.variantLabels = (item as any).variantLabels;
  }

  return payload;
};

export function useProcesarPedido({
  selectedTable,
  activePendingItemsRef,
  clearPendingItems,
  addDraftItem,
  tenantId,
  pedidosRepo,
  mesasRepo,
}: ProcesarPedidoProps) {
  const [isSending, setIsSending] = useState(false);
  const [lastError, setLastError] = useState<string | null>(null);
  const [puentePedidoId, setPuentePedidoId] = useState<string | null>(null);

  const sessionIdRef = useRef<string>('');
  useEffect(() => {
    sessionIdRef.current = `${tenantId}-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  }, [tenantId]);

  // Limpiar puentePedidoId al cambiar de mesa para evitar filtración de pedidos
  useEffect(() => {
    setPuentePedidoId(null);
  }, [selectedTable]);

  const sendOrder = useCallback(
    async (subpedidoId: string = 'default') => {
      if (!selectedTable) {
        log.warn('❌ sendOrder sin mesa seleccionada', { subpedidoId });
        return { success: false, error: 'No hay mesa seleccionada' };
      }

      const items = activePendingItemsRef.current;
      const itemsParaEnviar = items.filter((item: PendingItem) => Number(item.qty) > 0);

      if (itemsParaEnviar.length === 0) {
        return { success: false, error: 'No hay items para enviar a cocina' };
      }

      const previousDrafts = [...items];
      setIsSending(true);

      // Optimistic draft clean
      await clearPendingItems(subpedidoId);

      const sessionId =
        sessionIdRef.current || `${tenantId}-${Date.now()}-${Math.random().toString(36).slice(2)}`;

      const transactionResult = await mesasRepo.intentarBloquearMesaPedido(
        selectedTable,
        sessionId,
        LOCK_TIMEOUT_MS
      );

      if (!transactionResult.committed) {
        throw new Error('La mesa está siendo modificada por otro mesero. Intenta de nuevo.');
      }

      const mesaSnapshot = transactionResult.snapshotVal as MesaSnapshot | null;
      if (!mesaSnapshot) throw new Error('Error de consistencia en mesa');

      try {
        let pedidoId = mesaSnapshot.pedidoActivoId || undefined;
        let promisePedido: Promise<string | void>;

        if (pedidoId) {
          const itemPromises = itemsParaEnviar.map((item) =>
            pedidosRepo.agregarItem(pedidoId!, buildPedidoItemPayload(item) as any)
          );
          promisePedido = Promise.all(itemPromises).then(() => pedidoId!);
        } else {
          const itemsRecord: Record<string, any> = {};
          itemsParaEnviar.forEach((item, index) => {
            itemsRecord[`item_${index}`] = buildPedidoItemPayload(item);
          });

          const nuevoPedido = {
            tipo: 'mesa' as const,
            mesaId: selectedTable,
            estatus: 'activo',
            items: itemsRecord,
          };

          promisePedido = pedidosRepo.crear(nuevoPedido as any).then(async (newId: string) => {
            pedidoId = newId;
            setPuentePedidoId(newId);
            await mesasRepo.asignarPedido(selectedTable, newId);
            return newId;
          });
        }

        await promisePedido;

        await Promise.all([
          pedidosRepo.enviarACocina(pedidoId!),
          mesasRepo.actualizarEstado(selectedTable, 'ocupada'),
        ]);

        mesasRepo.liberarBloqueoMesaPedido(selectedTable).catch(console.error);

        log.info('🚀 Lógica Cuántica Completada', { pedidoId });
        return { success: true, pedidoId };
      } catch (err) {
        log.error('💥 Error en Lógica Cuántica:', err);

        // Rollback
        if (previousDrafts.length > 0) {
          log.info('🔄 Restaurando drafts por error...');
          for (const item of previousDrafts) {
            await addDraftItem(item);
          }
        }

        const error = err instanceof Error ? err : new Error(String(err));
        setLastError(error.message);

        try {
          await mesasRepo.liberarBloqueoMesaPedido(selectedTable);
        } catch {}

        return { success: false, error: error.message };
      } finally {
        setIsSending(false);
      }
    },
    [
      selectedTable,
      pedidosRepo,
      mesasRepo,
      clearPendingItems,
      tenantId,
      addDraftItem,
      activePendingItemsRef,
    ]
  );

  const sendOrderWithValidation = useCallback(
    async (subpedidoId: string) => {
      return sendOrder(subpedidoId);
    },
    [sendOrder]
  );

  return {
    isSending,
    lastError,
    setLastError,
    puentePedidoId,
    setPuentePedidoId,
    sendOrder,
    sendOrderWithValidation,
  };
}

