import type { ReactNode } from 'react';
import { useEffect, useMemo, useState } from 'react';

export type FabItem = {
  key: string;
  label: string;
  icon: ReactNode;
  onPress: () => void;
  enabled?: boolean;
  action?: string;
};

export function useFabRadial(itemsInput: FabItem[], initialActiveKey: string, visibleCount = 4) {
  const items = useMemo(() => itemsInput.filter((i) => i.enabled !== false), [itemsInput]);
  const firstKey = items[0]?.key;
  const safeInitialKey = useMemo(() => {
    if (!items.length) return undefined;
    return items.find((i) => i.key === initialActiveKey)?.key ?? firstKey;
  }, [items, initialActiveKey, firstKey]);

  const [expanded, setExpanded] = useState(false);
  const [activeKey, setActiveKey] = useState(safeInitialKey);
  const [offset, setOffset] = useState(0);

  useEffect(() => {
    if (safeInitialKey) {
      setActiveKey(safeInitialKey);
      setOffset(0);
    }
  }, [safeInitialKey]);

  const len = items.length;
  const visible = useMemo(() => {
    if (len === 0) return [] as FabItem[];
    const out: FabItem[] = [];
    for (let i = 0; i < Math.min(visibleCount, len); i++) {
      const idx = (offset + i) % len;
      out.push(items[idx]);
    }
    return out;
  }, [items, offset, len, visibleCount]);

  function toggle() {
    setExpanded((v) => !v);
  }

  function expand() {
    setExpanded(true);
  }

  function collapse() {
    setExpanded(false);
  }

  function rotateUp() {
    if (len === 0) return;
    setOffset((o) => (o + 1) % len);
  }

  function rotateDown() {
    if (len === 0) return;
    setOffset((o) => (o - 1 + len) % len);
  }

  function selectByKey(k: string) {
    const found = items.find((i) => i.key === k);
    if (!found) return;
    setActiveKey(k);
    setExpanded(false);
    found.onPress();
  }

  function selectItem(it: FabItem) {
    setActiveKey(it.key);
    setExpanded(false);
    it.onPress();
  }

  const activeItem = items.find((i) => i.key === activeKey) || items[0];

  return {
    expanded,
    activeKey,
    activeItem,
    visible,
    toggle,
    expand,
    collapse,
    rotateUp,
    rotateDown,
    selectByKey,
    selectItem,
  } as const;
}

/**
 * ⚡ HOOK MOSTRADOR PRO (VENTA Y CRUDO)
 * Refactorizado Phase 2:
 * - Registro de Ventas (SimpleSalesRepo)
 * - Impresión Robusta al Hub (Web & Native)
 * - Soporte Offline (SQLite + Bluetooth Fallback)
 */

import { useCallback, useEffect, useMemo, useState } from 'react';
import { MenuRepository, type Producto } from '../../base/_persistencia';
import { InventoryV2Repository } from '../../base/_persistencia/inventory.v2.repo';
import type { Categoria } from '../../base/_persistencia/menu.repo';
import { SimpleSalesRepo } from '../../base/_persistencia/SimpleSalesRepo';
import { getRtdb } from '../../core/firebase';
import { SQLiteStorageAdapter } from '../../core/offline/storage/SQLiteStorageAdapter';
import { OfflinePrintFallback } from '../../core/services/OfflinePrintFallback';
import { DespachadorCola } from '../../nucleo/sistema-impresion/cola/DespachadorCola';
import { useStore } from '../../core/store';
import { resolverDeviceIdADI } from '../../instalacion/vinculacion/generar-device-id-adi';
import { useTenantConfig } from '../../providers/TenantConfigProvider';
import { usePosConfig } from './usePosConfig';
import { useFeatureFlag } from '../../core/features';

function stripUndefinedDeep<T>(input: T): T {
  if (input === undefined) return null as any;
  if (input === null) return input;
  if (Array.isArray(input)) {
    return input.map((v) => stripUndefinedDeep(v)) as any;
  }
  if (typeof input === 'object') {
    const out: any = {};
    for (const [k, v] of Object.entries(input as any)) {
      if (v === undefined) continue;
      out[k] = stripUndefinedDeep(v);
    }
    return out;
  }
  return input;
}

export type UseMostradorProProps = {
  db?: any;
  tenantPath?: string;
};

export function useMostradorPro(props?: UseMostradorProProps) {
  const [loading, setLoading] = useState(true);
  const [productos, setProductos] = useState<Record<string, Producto>>({});
  const [categorias, setCategorias] = useState<Record<string, Categoria>>({});
  const [carrito, setCarrito] = useState<any[]>([]);
  const [ultimoTicket, setUltimoTicket] = useState<any | null>(null);
  const [efectivo, setEfectivo] = useState<string>('');
  const [deviceId, setDeviceId] = useState<string>('desconocido');

  const storeTenantPath = useStore((state) => state.sesion.tenantPath) || '';
  const ds = useStore((state) => state.dataSources);
  const usuario = useStore((state) => state.sesion.usuario?.nombre) || 'Mostrador';

  const tenantPath = props?.tenantPath !== undefined ? props.tenantPath : storeTenantPath;

  const db = useMemo(() => {
    if (props?.db) return props.db;
    return getRtdb(ds?.operacionUrl || undefined);
  }, [props?.db, ds?.operacionUrl]);

  useTenantConfig();
  const { config: posConfig, loading: configLoading } = usePosConfig(db, tenantPath);
  const menuRepo = useMemo(() => new MenuRepository(db, tenantPath), [db, tenantPath]);
  const salesRepo = useMemo(() => new SimpleSalesRepo(db, tenantPath), [db, tenantPath]);
  const inventoryRepo = useMemo(() => new InventoryV2Repository(db, tenantPath), [db, tenantPath]);

  useEffect(() => {
    resolverDeviceIdADI()
      .then(setDeviceId)
      .catch((err) => console.error('[MostradorPro] Error obteniendo deviceId:', err));
  }, []);
  const isInventarioEnabled = useFeatureFlag('inventario', true);
  const isImpresionEnabled = useFeatureFlag('impresion', true);
  const isBasculaEnabled = useFeatureFlag('bascula', true);
  const isDeliveryEnabled = useFeatureFlag('delivery', true);

  const rawInventoryAutoDiscount = useStore(
    (s) => s.negocio.features?.inventory_auto_discount?.enabled ?? true
  );
  const inventoryAutoDiscount = isInventarioEnabled && rawInventoryAutoDiscount;

  // --- Carga de Datos ---
  useEffect(() => {
    if (!tenantPath) return;

    // Cargar caché local primero por si estamos offline o para render rápido
    const cargarCacheOffline = async () => {
      try {
        const cachedProds = await SQLiteStorageAdapter.getProductos();
        const cachedCats = await SQLiteStorageAdapter.getCategorias();
        if (cachedProds && Object.keys(cachedProds).length > 0) {
          setProductos(cachedProds as Record<string, Producto>);
        }
        if (cachedCats && Object.keys(cachedCats).length > 0) {
          setCategorias(cachedCats as Record<string, Categoria>);
          setLoading(false);
        }
      } catch (err) {
        console.error('[MostradorPro] Error cargando caché de SQLite:', err);
      }
    };
    void cargarCacheOffline();

    const unsubMenu = menuRepo.suscribirProductos((data) => {
      setProductos(data);
      if (data && Object.keys(data).length > 0) {
        void SQLiteStorageAdapter.saveProductosBulk(data);
      }
    });

    const unsubCats = menuRepo.suscribirCategorias((data) => {
      setCategorias(data);
      setLoading(false);
      if (data && Object.keys(data).length > 0) {
        void SQLiteStorageAdapter.saveCategoriasBulk(data);
      }
    });

    return () => {
      unsubMenu();
      unsubCats();
    };
  }, [tenantPath, menuRepo]);

  // --- Computados ---
  const total = useMemo(
    () => carrito.reduce((acc, current) => acc + current.subtotal, 0),
    [carrito]
  );
  const cambio = useMemo(() => {
    const nTotal = total;
    const nEfectivo = parseFloat(efectivo) || 0;
    return Math.max(0, nEfectivo - nTotal);
  }, [total, efectivo]);

  // --- Acciones del Carrito ---
  const agregarAlCarrito = useCallback((producto: Producto, cantidad: number) => {
    setCarrito((prev) => {
      const id = `${producto.id}-${Math.random().toString(36).substr(2, 9)}`;
      return [
        ...prev,
        {
          id,
          productoId: producto.id,
          nombre: producto.nombre,
          precio: producto.precio,
          cantidad,
          subtotal: producto.precio * cantidad,
          unidad: producto.unidad || 'pza',
        },
      ];
    });
  }, []);

  const eliminarItem = (id: string) => setCarrito((prev) => prev.filter((i) => i.id !== id));

  const limpiarCarrito = () => setCarrito([]);

  const agregarPorCodigo = useCallback(
    (codigo: string) => {
      const producto = Object.values(productos).find((p) => p.codigoBarras === codigo);
      if (producto) {
        agregarAlCarrito(producto, 1);
        return true;
      }
      return false;
    },
    [productos, agregarAlCarrito]
  );

  // --- Finalización ---
  const completarVenta = async (metodoPago: string) => {
    const safeItems = (carrito || []).map((it) => {
      const productoId =
        typeof it?.productoId === 'string'
          ? it.productoId
          : typeof it?.productId === 'string'
          ? it.productId
          : null;

      return stripUndefinedDeep({
        id: it?.id,
        productoId,
        productId: productoId,
        nombre: it?.nombre,
        precio: it?.precio,
        cantidad: it?.cantidad,
        subtotal: it?.subtotal,
        unidad: it?.unidad ?? 'pza',
      });
    });

    // 1. Preparar Payload
    const randomHash = Math.random().toString(36).substring(2, 10).toUpperCase();
    const ventaId = `vc_${deviceId}_${Date.now()}_${randomHash}`;
    const payload = stripUndefinedDeep({
      id: ventaId,
      items: safeItems,
      total,
      timestamp: Date.now(),
      metodoPago,
      usuario,
      origen: 'venta_crudo' as const,
    });

    // 2. Detectar estado de conexión
    const { isOnline } = OfflinePrintFallback.getStatus();

    if (isOnline) {
      // ═══════════════════════════════════════════════════════════════════
      // MODO ONLINE: Comportamiento normal (Firebase + PrintSpooler)
      // ═══════════════════════════════════════════════════════════════════
      try {
        await salesRepo.registrarVenta(payload);
        console.log('[MostradorPro] ✅ Venta registrada en DB');
      } catch (error) {
        console.error('[MostradorPro] ⚠️ Error registrando venta en DB:', error);
      }

      // Inventario
      if (inventoryAutoDiscount) {
        try {
          const areas = await inventoryRepo.obtenerAreas();
          const areaId = Object.entries(areas).find(([, a]) => a?.hubId === 'venta_crudo')?.[0];
          if (areaId) {
            const inventoryItems = safeItems.filter((i) => typeof i?.productoId === 'string');
            if (inventoryItems.length > 0) {
              await inventoryRepo.registrarVentaMultiple({
                items: inventoryItems,
                areaId,
                total,
                metodoPago,
                usuario,
                allowNegative: !!posConfig?.allowNegativeStock,
                metadata: { origen: 'venta_crudo', tsVenta: payload?.timestamp },
              });
            }
          }
        } catch (error) {
          console.error('[MostradorPro] ⚠️ Error inventario V2:', error);
        }
      }

      // Imprimir vía Hub
      if (isImpresionEnabled) {
        console.log('[MostradorPro] 🖨️ ONLINE -> Hub');
        const spooler = DespachadorCola.obtenerInstancia(
          db,
          tenantPath,
          'pos_venta_crudo',
          {},
          'dispositivo'
        );
        await spooler.encolar({
          proposito: 'venta_crudo',
          idPedido: ventaId,
          canal: 'venta_crudo',
          payload,
        });
      } else {
        console.log('[MostradorPro] 🖨️ ONLINE -> Impresión desactivada por Feature Flag');
      }

      limpiarCarrito();
      setUltimoTicket(payload);
      return { success: true, ventaId, offline: false, method: 'hub' };
    } else {
      // ═══════════════════════════════════════════════════════════════════
      // MODO OFFLINE: Guardar en SQLite + Imprimir vía Bluetooth/Queue
      // ═══════════════════════════════════════════════════════════════════
      console.log('[MostradorPro] 📴 OFFLINE -> Guardando localmente...');

      // Guardar venta en SQLite para sincronizar después
      try {
        await SQLiteStorageAdapter.createVentaOffline(ventaId, 'venta_crudo', payload);
        console.log('[MostradorPro] ✅ Venta guardada localmente');
      } catch (error: any) {
        console.error('[MostradorPro] ❌ Error guardando venta local:', error);
        throw new Error(`Error local: ${error?.message || 'Desconocido'}`);
      }

      // Inventario Offline
      if (inventoryAutoDiscount) {
        try {
          const storeState = useStore.getState();
          const areaId = Object.entries(storeState.areas).find(
            ([, a]) => a?.hubId === 'venta_crudo'
          )?.[0];
          if (areaId) {
            const inventoryItems = safeItems.filter((i) => typeof i?.productoId === 'string');
            for (const item of inventoryItems) {
              await storeState.ajustarStockDelta({
                db: null as any,
                tenantPath,
                containerId: areaId,
                itemId: item.productoId,
                delta: -item.cantidad,
                usuario,
                razon: `Venta Offline Mostrador #${ventaId}`,
                allowNegative: !!posConfig?.allowNegativeStock,
              });
            }
            console.log(
              '[MostradorPro] 📦 Movimientos de inventario offline encolados y stock local actualizado'
            );
          }
        } catch (invError) {
          console.error('[MostradorPro] ⚠️ Error descontando inventario offline:', invError);
        }
      }

      // Imprimir usando fallback (Bluetooth o cola local)
      let printResult: { method: string; message?: string } = {
        method: 'none',
        message: 'Impresión desactivada por Feature Flag',
      };
      if (isImpresionEnabled) {
        const result = await OfflinePrintFallback.print({
          id: ventaId,
          type: 'venta_crudo',
          payload,
          createdAt: Date.now(),
        });
        printResult = { method: result.method, message: result.message };
      }
      console.log('[MostradorPro] 🖨️ Impresión:', printResult.method, printResult.message);

      limpiarCarrito();
      setUltimoTicket(payload);
      return {
        success: true,
        ventaId,
        offline: true,
        method: printResult.method,
        message: printResult.message,
      };
    }
  };

  const reimprimirUltimoTicket = async () => {
    if (!ultimoTicket) return { success: false, error: 'No hay ticket previo' };

    const jobId = `reprint_vc_${Date.now()}`;
    const spooler = DespachadorCola.obtenerInstancia(
      db,
      tenantPath,
      'pos_venta_crudo',
      {},
      'dispositivo'
    );
    await spooler.encolar({
      proposito: 'venta_crudo',
      idPedido: jobId,
      canal: 'venta_crudo',
      payload: ultimoTicket,
    });
    return { success: true, jobId };
  };

  return {
    loading: loading || configLoading,
    productos: Object.values(productos).filter((p) => p.visible?.ventaCrudo === true),
    categorias: Object.values(categorias).filter((c) => c.herencia?.ventaCrudo !== false),
    areas: [],
    selectedAreaId: null,
    setSelectedAreaId: () => {},
    stockByProduct: {},
    carrito,
    total,
    efectivo,
    setEfectivo,
    cambio,
    isHubOnline: true,
    isBasculaEnabled,
    isImpresionEnabled,
    isInventarioEnabled,
    isDeliveryEnabled,
    actions: {
      agregarAlCarrito,
      agregarPorCodigo,
      eliminarItem,
      limpiarCarrito,
      completarVenta,
      reimprimirUltimoTicket,
      marcarSinStock: () => {}, // No-op
    },
  };
}

/**
 * 🧠 CEREBRO - LÓGICA DE PUNTO DE VENTA (POS)
 *
 * Hook maestro que gestiona toda la lógica del módulo de caja rápida / POS.
 *
 * PROCESO 1 (TIENDAS):
 * - Venta rápida con escáner de código de barras
 * - Venta por peso con báscula (carnicerías, frutas/verduras)
 * - Descuento automático de inventario
 * - Impresión de ticket de venta
 *
 * SEPARACIÓN SAGRADA:
 * - Este hook NUNCA renderiza UI
 * - Solo maneja estado, suscripciones y acciones
 * - Usa repositorios y HardwareService para acceder a datos/dispositivos
 *
 * REUTILIZABLE en cualquier negocio de venta al público (tienda de abarrotes,
 * carnicería, panadería, marisquería, etc.)
 */

import type { Database } from 'firebase/database';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { MenuRepository, type Producto } from '../../base/_persistencia';
import {
  hardwareService,
  type CodigoResult,
  type PesoResult,
} from '../../core/services/HardwareService';

// ═══════════════════════════════════════════════════════════════════════════
// TIPOS
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Item en el carrito de venta
 */
export interface ItemVenta {
  id: string; // ID único en el carrito
  productoId: string; // ID del producto en el menú
  codigo?: string; // Código de barras
  nombre: string;
  precio: number;
  cantidad: number;
  unidad: 'pza' | 'kg' | 'lt' | 'otro';
  peso?: number; // Si es venta por peso
  subtotal: number;
  notas?: string;
}

/**
 * Totales de la venta
 */
export interface TotalesVenta {
  subtotal: number;
  descuento: number;
  total: number;
  itemsCount: number;
}

/**
 * Métodos de pago soportados
 */
export type MetodoPago = 'efectivo' | 'tarjeta' | 'transferencia' | 'mixto';

/**
 * Venta completada
 */
export interface Venta {
  id: string;
  items: ItemVenta[];
  totales: TotalesVenta;
  metodoPago: MetodoPago;
  efectivo?: number; // Monto recibido en efectivo
  cambio?: number; // Cambio devuelto
  timestamp: number;
  vendedor?: string; // ID o nombre del vendedor
}

// ═══════════════════════════════════════════════════════════════════════════
// HOOK
// ═══════════════════════════════════════════════════════════════════════════

interface UsePOSProps {
  db: Database;
  tenantPath: string;
  vendedor?: string;
}

export function usePOS({ db, tenantPath, vendedor }: UsePOSProps) {
  // Repositorios
  const menuRepo = useMemo(() => new MenuRepository(db, tenantPath), [db, tenantPath]);

  // Estado
  const [carrito, setCarrito] = useState<ItemVenta[]>([]);
  const [productos, setProductos] = useState<Record<string, Producto>>({});
  const [loading, setLoading] = useState(true);
  const [modoEscaneo, setModoEscaneo] = useState(false);
  const [ultimoEscaneado, setUltimoEscaneado] = useState<string | null>(null);

  // ═══════════════════════════════════════════════════════════════════════════
  // CARGA INICIAL
  // ═══════════════════════════════════════════════════════════════════════════

  // Cargar productos del menú
  useEffect(() => {
    if (!tenantPath) return;

    const unsub = menuRepo.suscribirProductos((productosData) => {
      setProductos(productosData);
      setLoading(false);
    });

    return unsub;
  }, [menuRepo, tenantPath]);

  // ═══════════════════════════════════════════════════════════════════════════
  // ACCIONES - ESCANEO Y BÚSQUEDA
  // ═══════════════════════════════════════════════════════════════════════════

  /**
   * Escanear código de barras y agregar al carrito
   */
  const escanearProducto = useCallback(async () => {
    if (!hardwareService.hasScanner()) {
      throw new Error('No hay escáner configurado');
    }

    const result: CodigoResult = await hardwareService.escanearCodigo();

    if (!result.success || !result.codigo) {
      throw new Error(result.message || 'Error al escanear código');
    }

    setUltimoEscaneado(result.codigo);

    // Buscar producto por código de barras
    const producto = Object.values(productos).find(
      (p) => p.codigoBarras === result.codigo && p.visible?.mesero !== false
    );

    if (!producto) {
      throw new Error(`Producto no encontrado: ${result.codigo}`);
    }

    // Agregar al carrito
    await agregarAlCarrito(producto.id, 1);

    return result.codigo;
  }, [productos]);

  /**
   * Activar modo escaneo continuo
   */
  const activarEscaneoContinuo = useCallback(async () => {
    if (!hardwareService.hasScanner()) {
      throw new Error('No hay escáner configurado');
    }

    const stopScanning = await hardwareService.escanearContinuo(async (result) => {
      if (!result.success || !result.codigo) return;

      setUltimoEscaneado(result.codigo);

      // Buscar producto por código de barras
      const producto = Object.values(productos).find(
        (p) => p.codigoBarras === result.codigo && p.visible?.mesero !== false
      );

      if (producto) {
        await agregarAlCarrito(producto.id, 1);
      }
    });

    setModoEscaneo(true);

    return stopScanning;
  }, [productos]);

  /**
   * Desactivar modo escaneo continuo
   */
  const desactivarEscaneoContinuo = useCallback((stopFunction: () => void) => {
    stopFunction();
    setModoEscaneo(false);
  }, []);

  /**
   * Buscar producto por código manualmente
   */
  const buscarPorCodigo = useCallback(
    async (codigo: string) => {
      const producto = Object.values(productos).find(
        (p) => p.codigoBarras === codigo && p.visible?.mesero !== false
      );

      if (!producto) {
        throw new Error(`Producto no encontrado: ${codigo}`);
      }

      return producto;
    },
    [productos]
  );

  // ═══════════════════════════════════════════════════════════════════════════
  // ACCIONES - BÁSCULA
  // ═══════════════════════════════════════════════════════════════════════════

  /**
   * Leer peso de báscula y agregar producto al carrito
   */
  const pesarProducto = useCallback(
    async (productoId: string) => {
      if (!hardwareService.hasScale()) {
        throw new Error('No hay báscula configurada');
      }

      const producto = productos[productoId];
      if (!producto) {
        throw new Error('Producto no encontrado');
      }

      // Leer peso
      const result: PesoResult = await hardwareService.leerPeso({
        aplicarTara: true,
        esperarEstabilidad: true,
      });

      if (!result.success || !result.peso) {
        throw new Error(result.message || 'Error al leer peso');
      }

      // Agregar al carrito con el peso
      await agregarAlCarrito(productoId, result.peso);

      return result;
    },
    [productos]
  );

  /**
   * Tarar báscula
   */
  const tararBascula = useCallback(async () => {
    if (!hardwareService.hasScale()) {
      throw new Error('No hay báscula configurada');
    }

    const result = await hardwareService.tararBascula();

    if (!result.success) {
      throw new Error(result.message || 'Error al tarar báscula');
    }

    return result;
  }, []);

  // ═══════════════════════════════════════════════════════════════════════════
  // ACCIONES - CARRITO
  // ═══════════════════════════════════════════════════════════════════════════

  /**
   * Agregar producto al carrito
   */
  const agregarAlCarrito = useCallback(
    async (productoId: string, cantidad: number) => {
      const producto = productos[productoId];
      if (!producto) {
        throw new Error('Producto no encontrado');
      }

      // Verificar stock disponible
      // TODO: Implementar verificación de stock

      const itemId = `item-${Date.now()}-${Math.random()}`;
      const subtotal = producto.precio * cantidad;

      const nuevoItem: ItemVenta = {
        id: itemId,
        productoId: producto.id,
        codigo: producto.codigoBarras,
        nombre: producto.nombre,
        precio: producto.precio,
        cantidad,
        unidad: (producto.unidad as 'pza' | 'kg' | 'lt' | 'otro') || 'pza',
        peso: producto.unidad === 'kg' ? cantidad : undefined,
        subtotal,
      };

      setCarrito((prev) => [...prev, nuevoItem]);
    },
    [productos]
  );

  /**
   * Actualizar cantidad de un item en el carrito
   */
  const actualizarCantidad = useCallback((itemId: string, nuevaCantidad: number) => {
    setCarrito((prev) =>
      prev.map((item) =>
        item.id === itemId
          ? { ...item, cantidad: nuevaCantidad, subtotal: item.precio * nuevaCantidad }
          : item
      )
    );
  }, []);

  /**
   * Eliminar item del carrito
   */
  const eliminarItem = useCallback((itemId: string) => {
    setCarrito((prev) => prev.filter((item) => item.id !== itemId));
  }, []);

  /**
   * Limpiar carrito completo
   */
  const limpiarCarrito = useCallback(() => {
    setCarrito([]);
  }, []);

  /**
   * Calcular totales de la venta
   */
  const calcularTotales = useCallback((): TotalesVenta => {
    const subtotal = carrito.reduce((sum, item) => sum + item.subtotal, 0);
    const descuento = 0; // TODO: Implementar lógica de descuentos
    const total = subtotal - descuento;
    const itemsCount = carrito.length;

    return { subtotal, descuento, total, itemsCount };
  }, [carrito]);

  const totales = useMemo(() => calcularTotales(), [calcularTotales]);
  const completarVenta = useCallback(
    async (metodoPago: MetodoPago, efectivo?: number): Promise<Venta> => {
      if (carrito.length === 0) {
        throw new Error('El carrito está vacío');
      }

      const totales = calcularTotales();

      // Calcular cambio si es efectivo
      let cambio = 0;
      if (metodoPago === 'efectivo' && efectivo) {
        cambio = Math.max(0, efectivo - totales.total);
      }

      const venta: Venta = {
        id: `VENTA-${Date.now()}`,
        items: carrito,
        totales,
        metodoPago,
        efectivo,
        cambio,
        timestamp: Date.now(),
        vendedor,
      };

      // Imprimir ticket de venta
      if (hardwareService.hasPrinter()) {
        await hardwareService.imprimirTicketVenta({
          items: carrito.map((item) => ({
            nombre: item.nombre,
            cantidad: item.cantidad,
            precio: item.precio,
            peso: item.peso,
          })),
          total: totales.total,
          timestamp: venta.timestamp,
        });
      }

      // Limpiar carrito
      limpiarCarrito();

      return venta;
    },
    [carrito, vendedor, calcularTotales, limpiarCarrito]
  );

  // ═══════════════════════════════════════════════════════════════════════════
  // RETURN
  // ═══════════════════════════════════════════════════════════════════════════

  return {
    // Estado
    carrito,
    productos,
    loading,
    modoEscaneo,
    ultimoEscaneado,
    totales,

    // Acciones - Escaneo
    escanearProducto,
    activarEscaneoContinuo,
    desactivarEscaneoContinuo,
    buscarPorCodigo,

    // Acciones - Báscula
    pesarProducto,
    tararBascula,

    // Acciones - Carrito
    agregarAlCarrito,
    actualizarCantidad,
    eliminarItem,
    limpiarCarrito,

    // Acciones - Venta
    completarVenta,

    // Hardware
    tieneBascula: hardwareService.hasScale(),
    tieneEscaner: hardwareService.hasScanner(),
    tieneImpresora: hardwareService.hasPrinter(),
  };
}

