/**
 * 🧠 CEREBRO - SELECTOR DE PRODUCTOS
 *
 * Hook reutilizable para seleccionar productos del menú
 * Funciona en CUALQUIER negocio de alimentos
 *
 * ✅ OPTIMIZADO: Consume del store centralizado (NO crea listeners)
 */

import { useCallback, useEffect, useMemo, useState } from 'react';
import { useCategorias, useProductos } from '../../core/store';
import type { Category, Product } from '../../base/tipos/contratos';
export type { Product };

type UseProductSelectorProps = Record<string, never>;

export function useProductSelector(
  _props: UseProductSelectorProps = {} as UseProductSelectorProps
) {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  // 🔌 DOGMA V2: Leer del store centralizado (NO crear listeners)
  const categoriasDelStore = useCategorias();
  const productosDelStore = useProductos();

  // Convertir a formato legacy (compatibilidad)
  const categories = useMemo(() => categoriasDelStore, [categoriasDelStore]);
  const products = useMemo(() => productosDelStore, [productosDelStore]);

  // Auto-seleccionar primera categoría
  useEffect(() => {
    if (!selectedCategory && Object.keys(categories).length > 0) {
      const firstCat = Object.keys(categories)[0];
      if (firstCat) {
        setSelectedCategory(firstCat);
        console.log('[useProductSelector] 🎯 Auto-seleccionada categoría:', firstCat);
      }
    }

    // Marcar como cargado cuando hay datos
    if (Object.keys(categories).length > 0) {
      setLoading(false);
    }
  }, [categories, selectedCategory]);

  // Productos de la categoría seleccionada
  const productsInCategory = useMemo(() => {
    if (!selectedCategory || !products) {
      return [];
    }

    // ✅ Filtrar por categoría y estado activo desde el store
    const allProducts = Object.entries(products);
    const filtered = allProducts.filter(([_, prod]) => {
      const isInCategory = prod.categoriaId === selectedCategory;
      const isActive = prod.activo !== false;
      // 🛡️ isolation: Respect mesero visibility flag
      const isVisible = prod.visible?.mesero !== false;
      return isInCategory && isActive && isVisible;
    });

    return filtered
      .map(([id, prod]) => ({ ...prod, id, categoriaId: prod.categoriaId || '' }))
      .sort((a, b) => (a.nombre || '').localeCompare(b.nombre || ''));
  }, [products, selectedCategory]);

  // Categorías activas ordenadas
  const activeCategories = useMemo(() => {
    return Object.entries(categories)
      .filter(([_, cat]) => {
        const isActive = cat.activo !== false;
        // 🛡️ isolation: Respect mesero visibility flag (inheritance)
        const isVisible = cat.herencia?.mesero !== false;
        return isActive && isVisible;
      })
      .map(([id, cat]) => ({ ...cat, id }))
      .sort((a, b) => (a.orden || 0) - (b.orden || 0));
  }, [categories]);

  // Acciones
  const selectCategory = useCallback((categoryId: string) => {
    setSelectedCategory(categoryId);
    console.log('[useProductSelector] 📂 Categoría seleccionada:', categoryId);
  }, []);

  // ✅ OPTIMIZADO: Leer producto directamente del store (sin fetch async)
  const getProduct = useCallback(
    (productId: string): Product | null => {
      const prod = products[productId];
      if (!prod) return null;
      return { ...prod, categoriaId: prod.categoriaId || '' };
    },
    [products]
  );

  // ✅ OPTIMIZADO: Versión async simplificada (lee del store inmediatamente)
  const getProductAsync = useCallback(
    async (productId: string): Promise<Product | null> => {
      const prod = products[productId];
      if (!prod) return null;
      return { ...prod, categoriaId: prod.categoriaId || '' };
    },
    [products]
  );

  return {
    // Estado
    categories: activeCategories,
    products: productsInCategory,
    selectedCategory,
    loading,

    // Acciones
    selectCategory,
    getProduct,
    getProductAsync,
  };
}

/**
 * 🧠 CEREBRO: Cargador de Roles y Features
 * Hook de lógica pura para cargar características/features del tenant
 * SEPARACIÓN SAGRADA: Solo lógica, cero UI
 */

import { useEffect, useState, useCallback } from 'react';
import type { Database } from 'firebase/database';
import { TenantRepository } from '../../base/_persistencia/tenant.repo';
import { normalizeFeatures, type FlatFeatures } from '../../core/utils/features';
import type { Feature } from '../../core/types/contratos';

type UseRolesLoaderProps = {
  db: Database;
  tenantPath: string;
  onFeaturesLoaded?: (features: Record<string, Feature>) => void;
};

/**
 * Adapta features planas (FlatFeatures) al formato normalizado del store
 */
function adaptFeatures(flat: FlatFeatures): Record<string, Feature> {
  const adapted: Record<string, Feature> = {};
  for (const [key, value] of Object.entries(flat)) {
    adapted[key] = { enabled: value };
  }
  return adapted;
}

export function useRolesLoader({ db, tenantPath, onFeaturesLoaded }: UseRolesLoaderProps) {
  const tenantRepo = useState(() => new TenantRepository(db, tenantPath))[0];
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  /**
   * Cargar features del tenant (solo si no están ya cargadas)
   */
  const loadFeatures = useCallback(
    async (force = false) => {
      if (!tenantPath) {
        setError('No hay tenantPath');
        return;
      }

      setLoading(true);
      setError(null);

      try {
        // Asegurar bootstrap primero
        await tenantRepo.asegurarBootstrap();

        // Obtener características o features
        const rawFeat = await tenantRepo.obtenerCaracteristicasOFeatures();

        if (!rawFeat) {
          setError('No se encontraron características ni features');
          setLoading(false);
          return;
        }

        // Normalizar a formato plano
        const flat = normalizeFeatures(rawFeat);

        // Adaptar al formato del store
        const adapted = adaptFeatures(flat);

        // Notificar al callback si está disponible
        onFeaturesLoaded?.(adapted);

        setLoading(false);
      } catch (err: any) {
        console.error('[useRolesLoader] Error cargando features:', err);
        setError(err?.message || 'Error desconocido');
        setLoading(false);
      }
    },
    [tenantPath, tenantRepo, onFeaturesLoaded]
  );

  return {
    loading,
    error,
    loadFeatures,
  };
}

