jest.mock('firebase/database', () => ({
  ref: jest.fn(),
  onValue: jest.fn(),
  off: jest.fn(),
}));

describe('useRolePacker — Autoridad Remota', () => {
  const dbMock = {} as Database;
  const tenantPath = 'marisquerias/el-arrecife';

  let effectCallback: any;
  let stateSetter: any;
  let mockState = null;

  beforeEach(() => {
    jest.clearAllMocks();
    mockState = null;
    stateSetter = jest.fn((val) => {
      mockState = typeof val === 'function' ? val(mockState) : val;
    });

    jest.spyOn(React, 'useEffect').mockImplementation((cb) => {
      effectCallback = cb;
    });

    let callCount = 0;
    jest.spyOn(React, 'useState').mockImplementation((initial: any) => {
      // Very naive mock for this specific hook:
      // First call is config, second is loading, third is error.
      const isConfig = callCount % 3 === 0;
      const isLoading = callCount % 3 === 1;
      callCount++;

      if (isConfig) {
        return [mockState, stateSetter];
      }
      if (isLoading) {
        return [false, jest.fn()];
      }
      return [initial, jest.fn()];
    });
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('valida roles remotos y rechaza fallback local cuando RTDB devuelve null', () => {
    (ref as jest.Mock).mockReturnValue('mockRef');

    (onValue as jest.Mock).mockImplementation((ref, callback) => {
      callback({ val: () => null });
      return jest.fn();
    });

    const getRoles = useRolePacker({ db: dbMock, tenantPath }).getRolesHabilitados;

    // Simulate mount
    if (effectCallback) effectCallback();

    // Still empty since fallback was removed
    expect(getRoles()).toEqual([]);
  });

  it('carga roles desde RTDB correctamente', () => {
    (ref as jest.Mock).mockReturnValue('mockRef');

    (onValue as jest.Mock).mockImplementation((ref, callback) => {
      callback({
        val: () => ({
          roles: {
            mesero: true,
            cocina: false,
          },
        }),
      });
      return jest.fn();
    });

    const getRoles = useRolePacker({ db: dbMock, tenantPath }).getRolesHabilitados;

    // Simulate mount
    if (effectCallback) effectCallback();

    // Call getRoles after state has updated (simulated by mocking useState returns)
    // We need to re-render conceptually. Let's just call useRolePacker again to get the updated closure if needed.
    // In our simplistic mock, useRolePacker reads `mockState` through the first useState.

    // Mock the state as it would be after setConfig(configData)
    const { getRolesHabilitados } = useRolePacker({ db: dbMock, tenantPath });

    const rolesHabilitados = getRolesHabilitados();

    expect(rolesHabilitados.length).toBe(1);
    expect(rolesHabilitados[0].nombre).toBe('Mesero');
  });
});

/**
 * 📦 ENSAMBLADOR DE ROLES (Role Packer)
 * Sistema dinámico que activa/desactiva módulos según las features del tenant
 *
 * MODULARIDAD EXTREMA:
 * - Lee features desde Firebase
 * - Auto-configura la aplicación
 * - Permite hiper-personalización sin tocar código
 */

import type { Database } from 'firebase/database';
import { off, onValue, ref } from 'firebase/database';
import { useEffect, useState } from 'react';
import { RUTAS } from '../../compartido/rutas';

export type RolConfig = {
  habilitado: boolean;
  nombre: string;
  icono: string;
  ruta: string;
  modulos?: Record<string, boolean>;
};

export type RolesDisponibles = {
  mesero?: RolConfig;
  cocina?: RolConfig;
  admin?: RolConfig;
  mostrador?: RolConfig; // Para Venta en Crudo / POS
  inventario?: RolConfig;
  repart?: RolConfig;
};

export type TipoNegocio = 'restaurante' | 'tienda' | 'hibrido';

export type ConfiguracionNegocio = {
  tipo: TipoNegocio;
  proceso: 1 | 2; // 1 = Tiendas, 2 = Restaurantes
  roles: RolesDisponibles;
  features: Record<string, boolean>;
};

type UseRolePackerProps = {
  db: Database;
  tenantPath: string;
};

export function useRolePacker({ db, tenantPath }: UseRolePackerProps) {
  const [config, setConfig] = useState<ConfiguracionNegocio | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!tenantPath) {
      console.log('[RolePacker] ❌ Sin tenantPath, no se cargarán roles');
      return;
    }

    console.log('[RolePacker] 🔍 Iniciando carga de roles desde:', tenantPath);
    setLoading(true);

    const configRef = ref(db, `${tenantPath}/caracteristicas`);

    const callback = onValue(
      configRef,
      (snapshot) => {
        try {
          console.log('[RolePacker] ✅ Snapshot recibido de caracteristicas');
          const data = snapshot.val() || {};

          // 🔥 CORRECCIÓN: Verificar si hay datos válidos
          if (!data || typeof data !== 'object') {
            console.warn('[RolePacker] ⚠️ Datos inválidos en caracteristicas:', data);
            // Intentar cargar desde ruta alternativa
            const featuresRef = ref(db, `${tenantPath}/features`);
            onValue(
              featuresRef,
              (featSnap) => {
                const featData = featSnap.val() || {};
                if (!featData || typeof featData !== 'object') {
                  console.error('[RolePacker] ❌ No se encontraron datos en features');
                  setError('No se encontraron datos de configuración');
                  setLoading(false);
                  return;
                }

                console.log('[RolePacker] ✅ Usando datos de features como fallback');
                procesarDatos(featData);
              },
              { onlyOnce: true }
            );
            return;
          }

          procesarDatos(data);
        } catch (err: any) {
          console.error('[RolePacker] ❌ Error procesando configuración:', err);
          setError(`Error al cargar configuración: ${err.message || 'Desconocido'}`);
          setLoading(false);
        }
      },
      (err: any) => {
        console.error('[RolePacker] ❌ Firebase error:', err);
        setError(`Error de Firebase: ${err.message || 'Desconocido'}`);
        setLoading(false);
      }
    );

    function procesarDatos(data: any) {
      console.log('[RolePacker] 🔎 Procesando datos:', Object.keys(data));

      // Determinar tipo de negocio
      const tipo: TipoNegocio = data.tipo || 'restaurante';
      const proceso = (tipo === 'tienda' ? 1 : 2) as 1 | 2;

      // Normalizar roles
      const rolesData = data.roles || {};
      const roles: RolesDisponibles = {};

      // Helper robusto para extraer configuración de rol
      const extraherRol = (
        key: string,
        fallbackKey: string | null,
        nombre: string,
        icono: string,
        ruta: string,
        forceEnabledByFeature?: boolean
      ): RolConfig | undefined => {
        const raw =
          rolesData[key] ??
          (fallbackKey ? rolesData[fallbackKey] : undefined) ??
          data[key] ??
          (fallbackKey ? data[fallbackKey] : undefined);

        if (raw === undefined && !forceEnabledByFeature) return undefined;

        const isTruthy = (v: any) => v === true || v === 'true' || v === 1 || v === '1';

        // Determinar si está habilitado
        let habilitado = false;
        if (forceEnabledByFeature) {
          habilitado = true;
        } else if (typeof raw === 'boolean') {
          habilitado = raw;
        } else if (typeof raw === 'object' && raw !== null) {
          habilitado =
            isTruthy(raw.habilitado) ||
            isTruthy(raw.enabled) ||
            isTruthy(raw.activo) ||
            Object.keys(raw).length > 0;
        } else {
          habilitado = isTruthy(raw);
        }

        // Casos especiales de deshabilitación explícita
        if (typeof raw === 'object' && raw !== null && raw.habilitado === false) habilitado = false;

        return {
          habilitado,
          nombre,
          icono,
          ruta,
          modulos: typeof raw === 'object' ? { ...raw } : {},
        };
      };

      // 1. MESERO
      roles.mesero = extraherRol('mesero', 'waiter', 'Mesero', 'restaurant', RUTAS.ROLES.MESERO);

      // 2. COCINA
      roles.cocina = extraherRol('cocina', 'kitchen', 'Cocina', 'flame', RUTAS.ROLES.COCINA);

      // 3. VENTA Y CRUDO (POS)
      const isVCrudoFeature = (v: any) => v === true || v === 'true' || v === 1 || v === '1';
      const forceVentaCrudo =
        isVCrudoFeature(data.module_venta_crudo) ||
        isVCrudoFeature(data.features?.module_venta_crudo);

      roles.mostrador = extraherRol(
        'mostrador',
        'venta_crudo',
        'Venta y Crudo',
        'cart',
        RUTAS.ROLES.VENTA_CRUDO,
        forceVentaCrudo
      );

      // 4. ADMIN
      roles.admin = extraherRol('admin', null, 'Admin', 'settings', RUTAS.ROLES.ADMIN);
      if (roles.admin && typeof rolesData.admin === 'object') {
        roles.admin.modulos = {
          dashboard: rolesData.admin.dashboard !== false,
          menu: rolesData.admin.menu !== false,
          inventario: rolesData.admin.inventario !== false,
          mesas: rolesData.admin.mesas !== false,
          dispositivos: rolesData.admin.dispositivos !== false,
          repart: rolesData.admin.repart !== false,
        };
      }

      // 5. INVENTARIO
      roles.inventario = extraherRol(
        'inventario',
        'inventory',
        'Inventario',
        'cube',
        RUTAS.ROLES.INVENTARIO
      );

      // 6. REPARTIDOR
      roles.repart = extraherRol(
        'repart',
        'repartidor',
        'ADI-Repart',
        'bicycle',
        RUTAS.ROLES.REPARTIDOR
      );

      // Normalizar features globales
      const features: Record<string, boolean> = {};
      Object.entries(data).forEach(([key, value]) => {
        if (typeof value === 'boolean') {
          features[key] = value;
        }
      });

      const configData: ConfiguracionNegocio = {
        tipo,
        proceso,
        roles,
        features,
      };

      console.log('[RolePacker] ✅ Configuración cargada:', {
        tipo,
        proceso,
        rolesHabilitados: Object.keys(roles).filter(
          (k) => roles[k as keyof RolesDisponibles]?.habilitado
        ),
        featuresCount: Object.keys(features).length,
      });

      setConfig(configData);
      setLoading(false);
    }

    return () => {
      console.log('[RolePacker] 🔌 Desuscribiendo de configuración');
      off(configRef, 'value', callback as any);
    };
  }, [db, tenantPath]);

  /**
   * Obtener roles habilitados
   */
  const getRolesHabilitados = (): RolConfig[] => {
    if (!config) {
      console.warn('[RolePacker] ⚠️ getRolesHabilitados: No hay configuración cargada');
      // 🔥 CORRECCIÓN: Proporcionar roles por defecto si no hay configuración
      if (!loading) {
        // Fallback remoto debe existir, no usamos hardcodeo
        return [];
      }
      return [];
    }

    const roles = Object.values(config.roles).filter(
      (rol): rol is RolConfig => !!rol && rol.habilitado === true
    );
    console.log(
      '[RolePacker] 🔍 getRolesHabilitados:',
      roles.map((r) => r.nombre)
    );
    return roles;
  };

  /**
   * Verificar si un rol está habilitado
   */
  const isRolHabilitado = (rolKey: keyof RolesDisponibles): boolean => {
    return config?.roles[rolKey]?.habilitado === true;
  };

  /**
   * Verificar si un módulo de un rol está habilitado
   */
  const isModuloHabilitado = (rolKey: keyof RolesDisponibles, moduloKey: string): boolean => {
    const rol = config?.roles[rolKey];
    if (!rol || !rol.habilitado) return false;
    return rol.modulos?.[moduloKey] !== false;
  };

  /**
   * Verificar si una feature global está habilitada
   */
  const isFeatureHabilitada = (featureKey: string): boolean => {
    return config?.features[featureKey] === true;
  };

  return {
    config,
    loading,
    error,

    // Helpers
    getRolesHabilitados,
    isRolHabilitado,
    isModuloHabilitado,
    isFeatureHabilitada,

    // Datos directos
    tipo: config?.tipo || 'restaurante',
    proceso: config?.proceso || 2,
  };
}

/**
 * 📶 ADAPTADOR BLUETOOTH
 *
 * Wrapper limpio de react-native-bluetooth-classic.
 * Maneja permisos, escaneo, conexión y escritura.
 *
 * USO:
 * ```typescript
 * const bt = new AdaptadorBluetooth();
 * const dispositivos = await bt.escanear();
 * await bt.conectar(dispositivos[0].direccion);
 * await bt.escribir(bytesEscPos);
 * await bt.desconectar();
 * ```
 */

import { Platform } from 'react-native';
import type { DispositivoFierro } from '../contratos/tipos';

// Importación condicional para web
let RNBluetoothClassic: any = null;

// Solo importar en nativo
if (Platform.OS !== 'web') {
  try {
    RNBluetoothClassic = require('react-native-bluetooth-classic').default;
  } catch (e) {
    console.warn('[AdaptadorBluetooth] react-native-bluetooth-classic no disponible');
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// TIPOS INTERNOS
// ═══════════════════════════════════════════════════════════════════════════

interface DispositivoBT {
  id?: string;
  address: string;
  name?: string;
  bonded?: boolean;
}

// ═══════════════════════════════════════════════════════════════════════════
// ADAPTADOR BLUETOOTH
// ═══════════════════════════════════════════════════════════════════════════

export class AdaptadorBluetooth {
  private dispositivoConectado: DispositivoBT | null = null;
  private conectado: boolean = false;

  /**
   * Verifica si Bluetooth está disponible
   */
  async estaDisponible(): Promise<boolean> {
    if (!RNBluetoothClassic) {
      return false;
    }

    try {
      return await RNBluetoothClassic.isBluetoothAvailable();
    } catch (e) {
      console.error('[AdaptadorBluetooth] Error verificando disponibilidad:', e);
      return false;
    }
  }

  /**
   * Verifica si Bluetooth está habilitado
   */
  async estaHabilitado(): Promise<boolean> {
    if (!RNBluetoothClassic) return false;

    try {
      return await RNBluetoothClassic.isBluetoothEnabled();
    } catch (e) {
      return false;
    }
  }

  /**
   * Solicita habilitar Bluetooth (Android)
   */
  async solicitarHabilitar(): Promise<boolean> {
    if (!RNBluetoothClassic) return false;

    try {
      return await RNBluetoothClassic.requestBluetoothEnabled();
    } catch (e) {
      return false;
    }
  }

  /**
   * Obtiene dispositivos emparejados
   */
  async obtenerEmparejados(): Promise<DispositivoFierro[]> {
    if (!RNBluetoothClassic) return [];

    try {
      const emparejados: DispositivoBT[] = await RNBluetoothClassic.getBondedDevices();

      return emparejados.map((d) => ({
        nombre: d.name || 'Desconocido',
        direccion: d.address || d.id || '',
        tipo: 'bluetooth' as const,
        emparejado: true,
      }));
    } catch (e) {
      console.error('[AdaptadorBluetooth] Error obteniendo emparejados:', e);
      return [];
    }
  }

  /**
   * Escanea dispositivos cercanos
   * @param duracionMs - Duración del escaneo en ms (default: 10s)
   */
  async escanear(duracionMs: number = 10000): Promise<DispositivoFierro[]> {
    if (!RNBluetoothClassic) return [];

    try {
      // Primero verificar que esté habilitado
      const habilitado = await this.estaHabilitado();
      if (!habilitado) {
        throw new Error('Bluetooth no está habilitado');
      }

      // Iniciar discovery
      const iniciado = await RNBluetoothClassic.startDiscovery();
      if (!iniciado) {
        // Si no inició discovery, al menos devolver emparejados
        return this.obtenerEmparejados();
      }

      // Esperar la duración del escaneo
      await new Promise((resolve) => setTimeout(resolve, duracionMs));

      // Cancelar discovery y obtener resultados
      await RNBluetoothClassic.cancelDiscovery().catch(() => {});

      // Combinar nuevos descubiertos con emparejados
      const descubiertos: DispositivoBT[] = (await RNBluetoothClassic.getUnpairedDevices()) || [];
      const emparejados: DispositivoBT[] = (await RNBluetoothClassic.getBondedDevices()) || [];

      const todosMap = new Map<string, DispositivoFierro>();

      // Primero emparejados (tienen prioridad)
      for (const d of emparejados) {
        const direccion = d.address || d.id || '';
        if (direccion) {
          todosMap.set(direccion, {
            nombre: d.name || 'Desconocido',
            direccion,
            tipo: 'bluetooth',
            emparejado: true,
          });
        }
      }

      // Luego descubiertos (solo si no están ya)
      for (const d of descubiertos) {
        const direccion = d.address || d.id || '';
        if (direccion && !todosMap.has(direccion)) {
          todosMap.set(direccion, {
            nombre: d.name || 'Desconocido',
            direccion,
            tipo: 'bluetooth',
            emparejado: false,
          });
        }
      }

      return Array.from(todosMap.values());
    } catch (e: any) {
      console.error('[AdaptadorBluetooth] Error en escaneo:', e);
      // Fallback: devolver emparejados
      return this.obtenerEmparejados();
    }
  }

  /**
   * Conecta a un dispositivo
   * @param direccion - MAC address del dispositivo
   */
  async conectar(direccion: string): Promise<void> {
    if (!RNBluetoothClassic) {
      throw new Error('Bluetooth no disponible en esta plataforma');
    }

    if (this.conectado) {
      await this.desconectar();
    }

    try {
      const dispositivo = await RNBluetoothClassic.connectToDevice(direccion, {
        delimiter: '\n',
        charset: 'latin1', // Para ESC/POS
      });

      if (!dispositivo) {
        throw new Error('No se pudo establecer conexión');
      }

      this.dispositivoConectado = {
        address: direccion,
        name: dispositivo.name,
      };
      this.conectado = true;

      console.log(`[AdaptadorBluetooth] ✅ Conectado a ${direccion}`);
    } catch (e: any) {
      this.conectado = false;
      this.dispositivoConectado = null;
      throw new Error(`Error al conectar: ${e?.message || 'Desconocido'}`);
    }
  }

  /**
   * Desconecta el dispositivo actual
   */
  async desconectar(): Promise<void> {
    if (!RNBluetoothClassic || !this.dispositivoConectado) {
      this.conectado = false;
      this.dispositivoConectado = null;
      return;
    }

    try {
      await RNBluetoothClassic.disconnectFromDevice(this.dispositivoConectado.address);
      console.log('[AdaptadorBluetooth] 🔴 Desconectado');
    } catch (e) {
      console.warn('[AdaptadorBluetooth] Error al desconectar:', e);
    } finally {
      this.conectado = false;
      this.dispositivoConectado = null;
    }
  }

  /**
   * Escribe bytes al dispositivo conectado
   * @param datos - Bytes a enviar (Uint8Array o string base64)
   */
  async escribir(datos: Uint8Array | string): Promise<void> {
    if (!RNBluetoothClassic || !this.dispositivoConectado) {
      throw new Error('No hay dispositivo conectado');
    }

    try {
      let dataToSend: string;

      if (datos instanceof Uint8Array) {
        // Convertir Uint8Array a string base64
        let binary = '';
        for (let i = 0; i < datos.length; i++) {
          binary += String.fromCharCode(datos[i]);
        }
        dataToSend =
          typeof btoa !== 'undefined' ? btoa(binary) : Buffer.from(datos).toString('base64');
      } else {
        dataToSend = datos;
      }

      await RNBluetoothClassic.writeToDevice(
        this.dispositivoConectado.address,
        dataToSend,
        'base64'
      );
    } catch (e: any) {
      throw new Error(`Error al escribir: ${e?.message || 'Desconocido'}`);
    }
  }

  /**
   * Lee datos del dispositivo (para básculas)
   * @param timeout - Timeout en ms
   */
  async leer(timeout: number = 5000): Promise<string> {
    if (!RNBluetoothClassic || !this.dispositivoConectado) {
      throw new Error('No hay dispositivo conectado');
    }

    try {
      const resultado = await Promise.race([
        RNBluetoothClassic.readFromDevice(this.dispositivoConectado.address),
        new Promise((_, reject) =>
          setTimeout(() => reject(new Error('Timeout de lectura')), timeout)
        ),
      ]);

      return resultado as string;
    } catch (e: any) {
      throw new Error(`Error al leer: ${e?.message || 'Desconocido'}`);
    }
  }

  /**
   * Verifica si está conectado
   */
  estaConectado(): boolean {
    return this.conectado && this.dispositivoConectado !== null;
  }

  /**
   * Obtiene info del dispositivo conectado
   */
  obtenerDispositivoConectado(): DispositivoFierro | null {
    if (!this.dispositivoConectado) return null;

    return {
      nombre: this.dispositivoConectado.name || 'Desconocido',
      direccion: this.dispositivoConectado.address,
      tipo: 'bluetooth',
      emparejado: true,
    };
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// SINGLETON EXPORTADO
// ═══════════════════════════════════════════════════════════════════════════

/** Instancia singleton del adaptador Bluetooth */
export const adaptadorBluetooth = new AdaptadorBluetooth();

/**
 * 🖨️ GESTOR HUB (Componente Invisible)
 *
 * Orquesta la impresión remota cuando el dispositivo actúa como Hub Central.
 * Se monta globalmente en _layout.tsx y reacciona al EstadoHub (Zustand).
 *
 * DIFERENCIAS CON HubManager.tsx LEGACY:
 * - ❌ No usa polling de AsyncStorage cada 5 segundos
 * - ✅ Reacciona instantáneamente via Zustand (useEstadoHub)
 * - ✅ Usa el nuevo ServicioFierros en lugar de HardwareService
 * - ✅ Nombres en español
 */

import NetInfo from '@react-native-community/netinfo';
import { ref, set } from 'firebase/database';
import { useEffect, useRef } from 'react';
import { getRtdb } from '../../../core/firebase';
import { DespachadorCola } from '../cola/DespachadorCola';
import { destinoACanal, useEstadoHub } from '../estado/EstadoHub';

// ═══════════════════════════════════════════════════════════════════════════
// TIPOS
// ═══════════════════════════════════════════════════════════════════════════

interface PropiedadesGestorHub {
  /** Path del tenant (ej: "tenants/miNegocio") */
  tenantPath: string;
}

// ═══════════════════════════════════════════════════════════════════════════
// COMPONENTE
// ═══════════════════════════════════════════════════════════════════════════

export const GestorHub = ({ tenantPath }: PropiedadesGestorHub) => {
  // Estado del Hub desde Zustand (REACTIVO, sin polling!)
  const { habilitado, destino, idDispositivo, enLinea, setEnLinea, inicializar } = useEstadoHub();

  // Refs para cleanup
  const heartbeatRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const listenerRedRef = useRef<(() => void) | null>(null);

  // Inicializar estado desde AsyncStorage al montar
  useEffect(() => {
    console.log('[GestorHub] 🔷 Componente MONTADO');
    console.log('[GestorHub] Estado inicial:', { habilitado, destino, idDispositivo, enLinea });
    inicializar();
  }, [inicializar]);

  // ═══════════════════════════════════════════════════════════════════════════
  // LISTENER DE RED
  // ═══════════════════════════════════════════════════════════════════════════

  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener((state) => {
      const ahora = state.isConnected ?? false;
      setEnLinea(ahora);

      if (!ahora) {
        console.log('[GestorHub] 🔴 Red perdida, entrando en modo STANDBY');
      } else if (ahora && !enLinea) {
        console.log('[GestorHub] 🟢 Red restaurada');
      }
    });

    listenerRedRef.current = unsubscribe;

    return () => unsubscribe();
  }, [enLinea, setEnLinea]);

  // ═══════════════════════════════════════════════════════════════════════════
  // CICLO DE VIDA DEL HUB
  // ═══════════════════════════════════════════════════════════════════════════

  useEffect(() => {
    // Condiciones para activar
    const debeActivar = habilitado && tenantPath && enLinea && destino;

    if (debeActivar) {
      console.log('[GestorHub] 🟢 Activando modo HUB...');

      const db = getRtdb();
      if (!db) {
        console.error('[GestorHub] ❌ Firebase RTDB no disponible');
        return;
      }

      const canal = destinoACanal(destino);

      // 🔥 INTEGRACIÓN: Iniciar DespachadorCola
      const despachador = DespachadorCola.obtenerInstancia(
        db,
        tenantPath,
        idDispositivo,
        {
          procesamientoAuto: true,
          maxReintentos: 1,
          canal,
        },
        'hub'
      );
      despachador.iniciar();

      console.log(
        `[GestorHub] ✅ Hub inicializado (canal: ${canal}, dispositivo: ${idDispositivo})`
      );

      // Heartbeat: Avisar que estamos vivos cada 30 segundos
      heartbeatRef.current = setInterval(async () => {
        try {
          const heartbeatPath = ref(db, `${tenantPath}/config/hub/heartbeat`);
          await set(heartbeatPath, Date.now());
        } catch (e) {
          console.warn('[GestorHub] Error enviando heartbeat:', e);
        }
      }, 30000);

      // Enviar heartbeat inicial
      const heartbeatPath = ref(db, `${tenantPath}/config/hub/heartbeat`);
      set(heartbeatPath, Date.now()).catch(() => {});

      // Sincronizar config a la nube
      set(ref(db, `${tenantPath}/config/hub`), {
        enabled: true,
        destination: destino,
        deviceId: idDispositivo,
        updatedAt: Date.now(),
      }).catch((e) => console.warn('[GestorHub] Error sincronizando config:', e));
    } else {
      console.log(`[GestorHub] 🔴 Hub ${!habilitado ? 'desactivado' : 'en standby'}`, {
        habilitado,
        tenantPath: !!tenantPath,
        enLinea,
        destino,
      });

      // Si estaba activo y ahora no, detener despachador
      if (tenantPath) {
        DespachadorCola.destruirInstancia(tenantPath, 'hub');
      }
    }

    // Cleanup
    return () => {
      if (heartbeatRef.current) {
        clearInterval(heartbeatRef.current);
        heartbeatRef.current = null;
      }

      // Detener despachador al desmontar
      if (tenantPath) {
        DespachadorCola.destruirInstancia(tenantPath, 'hub');
      }
    };
  }, [habilitado, tenantPath, enLinea, destino, idDispositivo]);

  // Componente invisible
  return null;
};

// ═══════════════════════════════════════════════════════════════════════════
// WRAPPER GLOBAL (para usar en _layout.tsx)
// ═══════════════════════════════════════════════════════════════════════════

interface PropiedadesGestorHubGlobal {
  /** Función o hook para obtener tenantPath (ej: useSesion) */
  tenantPath: string | null;
}

/**
 * Componente global que se monta en _layout.tsx
 * Solo monta GestorHub si hay tenantPath
 */
export const GestorHubGlobal = ({ tenantPath }: PropiedadesGestorHubGlobal) => {
  if (!tenantPath) {
    return null;
  }

  return <GestorHub tenantPath={tenantPath} />;
};

