/**
 * 🔊 PROVIDER GLOBAL DE AUDIO PARA NOTIFICACIONES
 * Solución robusta al bug de "AudioPlayer already released"
 *
 * PROBLEMA:
 * - useAudioPlayer() crea un player que se libera al desmontar el componente
 * - Si el listener de notificaciones dispara después del desmontaje, crashea
 *
 * SOLUCIÓN:
 * - Player único global que NUNCA se desmonta
 * - Usar replay() en lugar de play() para reiniciar desde el inicio
 * - Guardas para evitar llamadas sobre player liberado
 */

import { useAudioPlayer } from 'expo-audio';
import React, { createContext, useContext, useEffect, useRef } from 'react';
import { Platform } from 'react-native';

type NotificationsAudioContextType = {
  playNotificationSound: () => void;
};

const NotificationsAudioContext = createContext<NotificationsAudioContextType | null>(null);

function NotificationsAudioProviderWeb({ children }: { children: React.ReactNode }) {
  const playNotificationSound = () => {
    return;
  };

  return (
    <NotificationsAudioContext.Provider value={{ playNotificationSound }}>
      {children}
    </NotificationsAudioContext.Provider>
  );
}

function NotificationsAudioProviderNative({ children }: { children: React.ReactNode }) {
  const player = useAudioPlayer(require('@assets/sounds/huge.wav'));
  const isPlayerReady = useRef(false);

  useEffect(() => {
    isPlayerReady.current = true;
    return () => {
      isPlayerReady.current = false;
    };
  }, []);

  const playNotificationSound = () => {
    try {
      if (!isPlayerReady.current) {
        console.warn('[NotificationsAudio] Player no está listo');
        return;
      }

      if (player.playing) {
        try {
          player.pause();
          player.currentTime = 0;
        } catch {
          // Ignorar errores de pause/seek
        }
      }

      try {
        player.play();
      } catch (error: any) {
        const errorMsg = error?.message || String(error);
        if (
          errorMsg.includes('not allowed') ||
          errorMsg.includes('permission') ||
          errorMsg.includes('user agent') ||
          errorMsg.includes('platform')
        ) {
          return;
        }
        throw error;
      }
    } catch (error: any) {
      const errorMsg = error?.message || String(error);
      if (
        errorMsg.includes('not allowed') ||
        errorMsg.includes('permission') ||
        errorMsg.includes('user agent') ||
        errorMsg.includes('platform')
      ) {
        return;
      }
      console.warn('[NotificationsAudio] Error playing sound:', errorMsg);
    }
  };

  return (
    <NotificationsAudioContext.Provider value={{ playNotificationSound }}>
      {children}
    </NotificationsAudioContext.Provider>
  );
}

export function NotificationsAudioProvider({ children }: { children: React.ReactNode }) {
  if (Platform.OS === 'web') {
    return <NotificationsAudioProviderWeb>{children}</NotificationsAudioProviderWeb>;
  }
  return <NotificationsAudioProviderNative>{children}</NotificationsAudioProviderNative>;
}

/**
 * Hook para usar el audio de notificaciones
 */
export function useNotificationsAudio() {
  const context = useContext(NotificationsAudioContext);
  if (!context) {
    throw new Error('useNotificationsAudio debe usarse dentro de NotificationsAudioProvider');
  }
  return context;
}

import type { ComponentType } from 'react';

type ContratoSlots<Contrato> = {
  [NombreSlot in keyof Contrato]: object;
};

export type SlotRegistry<Contrato extends ContratoSlots<Contrato>> = {
  readonly [NombreSlot in keyof Contrato]: Readonly<
    Record<string, ComponentType<Contrato[NombreSlot]>>
  >;
};

export function defineSlotRegistry<Contrato extends ContratoSlots<Contrato>>() {
  return <const Registro extends SlotRegistry<Contrato>>(
    registro: Registro
  ): Readonly<Registro> => {
    const copia = Object.fromEntries(
      Object.entries(registro).map(([nombreSlot, allowlist]) => [
        nombreSlot,
        Object.freeze(Object.assign({}, allowlist)),
      ])
    ) as Registro;

    return Object.freeze(copia);
  };
}

export function resolveSlotOverride<
  Contrato extends ContratoSlots<Contrato>,
  NombreSlot extends Extract<keyof Contrato, string>
>(
  registro: SlotRegistry<Contrato>,
  nombreSlot: NombreSlot,
  rawId: unknown
): ComponentType<Contrato[NombreSlot]> | undefined {
  if (typeof rawId !== 'string') {
    return undefined;
  }

  const allowlist = registro[nombreSlot];
  if (!Object.prototype.hasOwnProperty.call(allowlist, rawId)) {
    return undefined;
  }

  return allowlist[rawId];
}
